CREATE OR REPLACE FUNCTION public.fn_atualizar_carga_voluntario()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
DECLARE
  v_mes_inicio DATE := date_trunc('month', CURRENT_DATE)::DATE;
  v_mes_fim    DATE := (date_trunc('month', CURRENT_DATE) + interval '1 month - 1 day')::DATE;
  v_total_mes  INT;
  v_max_mes    INT;
  v_sobrecarga INT;
  v_area       UUID;
BEGIN
  SELECT count(*) INTO v_total_mes
  FROM escala_voluntarios ev
  JOIN escalas e ON e.id = ev.escala_id
  WHERE ev.pessoa_id = NEW.pessoa_id
    AND ev.status NOT IN ('recusado')
    AND e.data_evento BETWEEN v_mes_inicio AND v_mes_fim;

  SELECT max_escalas_mes INTO v_max_mes
  FROM perfil_servico WHERE pessoa_id = NEW.pessoa_id;
  v_max_mes := COALESCE(v_max_mes, 4);

  v_sobrecarga := LEAST(10, GREATEST(0, ROUND((v_total_mes::NUMERIC / GREATEST(v_max_mes, 1)) * 10)));

  INSERT INTO public.perfil_servico (pessoa_id, carga_atual_mes, nivel_sobrecarga)
  VALUES (NEW.pessoa_id, v_total_mes, v_sobrecarga)
  ON CONFLICT (pessoa_id) DO UPDATE
    SET carga_atual_mes  = v_total_mes,
        nivel_sobrecarga = v_sobrecarga,
        updated_at       = now();

  SELECT e.area_id INTO v_area FROM escalas e WHERE e.id = NEW.escala_id;

  IF v_area IS NOT NULL THEN
    UPDATE public.area_voluntarios av
    SET
      -- A data do EVENTO, e só de evento que já aconteceu. Antes era
      -- CURRENT_DATE: o dia do clique, não o dia do serviço.
      ultima_escala_em = (
        SELECT max(e3.data_evento)
        FROM escala_voluntarios ev3
        JOIN escalas e3 ON e3.id = ev3.escala_id
        WHERE ev3.pessoa_id = NEW.pessoa_id
          AND e3.area_id = v_area
          AND ev3.status IN ('confirmado','presente')
          AND e3.data_evento <= CURRENT_DATE
      ),
      total_escalas = (
        SELECT count(*)
        FROM escala_voluntarios ev2
        JOIN escalas e2 ON e2.id = ev2.escala_id
        WHERE ev2.pessoa_id = NEW.pessoa_id
          AND e2.area_id = v_area
          AND ev2.status IN ('confirmado','presente')
      )
    WHERE av.membro_id = NEW.pessoa_id
      AND av.area_id = v_area;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_atualizar_contato()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE membros
  SET 
    ultimo_contato_em = NOW(),
    status_acolhimento = 'contatado',
    score_engajamento = calcular_score_engajamento(NEW.visitante_id)
  WHERE id = NEW.visitante_id;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_atualizar_membro_por_tarefa()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_status   TEXT;
  v_visitas  INTEGER;
  v_novo_status public.status_acolhimento_enum;
BEGIN
  -- Apenas quando tarefa passa de não-concluída para concluída
  IF NEW.concluida = true AND (OLD.concluida = false OR OLD.concluida IS NULL) THEN

    SELECT status_acolhimento::TEXT, numero_visitas
      INTO v_status, v_visitas
      FROM public.membros
     WHERE id = NEW.visitante_id;

    -- Determinar novo status
    IF v_status IN ('novo', 'contatar') THEN
      v_novo_status := 'contatado';
    ELSIF v_status = 'contatado' AND COALESCE(v_visitas, 1) >= 2 THEN
      v_novo_status := 'em_relacionamento';
    ELSE
      v_novo_status := v_status::public.status_acolhimento_enum;
    END IF;

    UPDATE public.membros
       SET ultimo_contato_em  = now(),
           score_engajamento  = public.calcular_score_engajamento(NEW.visitante_id),
           status_acolhimento = v_novo_status
     WHERE id = NEW.visitante_id;

  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_auditoria_exclusao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid      uuid;
  v_email    text;
  v_reg_id   text;
BEGIN
  v_uid   := (SELECT auth.uid());
  v_email := (SELECT email FROM auth.users WHERE id = v_uid LIMIT 1);

  -- Tentar obter id do registro excluído (pode ser uuid, bigint, text)
  BEGIN
    v_reg_id := (row_to_json(OLD) ->> 'id')::text;
  EXCEPTION WHEN OTHERS THEN
    v_reg_id := NULL;
  END;

  INSERT INTO public.log_exclusoes (
    usuario_id,
    usuario_email,
    tipo,
    tabela,
    registro_id,
    dados_antes,
    confirmado_em
  ) VALUES (
    v_uid,
    v_email,
    'exclusao_manual',
    TG_TABLE_NAME,
    v_reg_id,
    row_to_json(OLD)::jsonb,
    now()
  );

  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_auto_status_por_visitas()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Avançar para 'retornou' quando volta pela 2ª vez
  IF NEW.numero_visitas >= 2
     AND NEW.status_acolhimento::TEXT IN ('novo', 'contatar', 'contatado')
  THEN
    NEW.status_acolhimento := 'retornou'::public.status_acolhimento_enum;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_contexto_usuario()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := (SELECT auth.uid());
  v_role app_role;
  v_mid  uuid;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN '{}'::jsonb; END IF;

  SELECT role INTO v_role FROM user_roles WHERE user_id = v_uid LIMIT 1;
  IF v_role IS NULL THEN
    RETURN jsonb_build_object('autenticado', true, 'tem_role', false, 'user_id', v_uid);
  END IF;

  -- Ministério do líder
  IF v_role = 'lideranca' THEN
    v_mid := public.fn_meu_ministerio_id();
  END IF;

  -- Montar permissões por módulo
  v_result := jsonb_build_object(
    'user_id',    v_uid,
    'role',       v_role::text,
    'tem_role',   true,
    'ministerio_id', v_mid,
    'permissoes', (
      SELECT jsonb_object_agg(
        pm.modulo,
        jsonb_build_object(
          'ver',      pm.pode_ver,
          'criar',    pm.pode_criar,
          'editar',   pm.pode_editar,
          'excluir',  pm.pode_excluir,
          'exportar', pm.pode_exportar,
          'apenas_proprio',    pm.apenas_proprio,
          'apenas_ministerio', pm.apenas_ministerio
        )
      )
      FROM permissoes_modulo pm WHERE pm.role = v_role
    )
  );

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_ebd_proteger_classe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mat int;
  v_aul int;
BEGIN
  SELECT COUNT(*) INTO v_mat FROM public.ebd_matriculas WHERE classe_id = OLD.id AND ativo = true;
  SELECT COUNT(*) INTO v_aul FROM public.ebd_aulas      WHERE classe_id = OLD.id;
  IF v_mat > 0 THEN
    RAISE EXCEPTION 'Nao eh possivel excluir: a classe % tem % aluno(s) matriculado(s). Desmatricule antes ou desative a classe.', OLD.nome, v_mat;
  END IF;
  IF v_aul > 0 THEN
    RAISE EXCEPTION 'Nao eh possivel excluir: a classe % tem % aula(s) registrada(s). Desative em vez de excluir.', OLD.nome, v_aul;
  END IF;
  RETURN OLD;
END;
$function$
;

