CREATE OR REPLACE FUNCTION public.fn_minha_permissao(p_modulo text)
 RETURNS TABLE(pode_ver boolean, pode_criar boolean, pode_editar boolean, pode_excluir boolean, pode_exportar boolean, apenas_proprio boolean, apenas_ministerio boolean, role app_role)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := (SELECT auth.uid());
  v_role app_role;
BEGIN
  IF v_uid IS NULL THEN
    RETURN QUERY SELECT false,false,false,false,false,false,false,NULL::app_role;
    RETURN;
  END IF;

  SELECT ur.role INTO v_role FROM user_roles ur WHERE ur.user_id = v_uid LIMIT 1;

  RETURN QUERY
  SELECT
    COALESCE(pm.pode_ver,false),
    COALESCE(pm.pode_criar,false),
    COALESCE(pm.pode_editar,false),
    COALESCE(pm.pode_excluir,false),
    COALESCE(pm.pode_exportar,false),
    COALESCE(pm.apenas_proprio,false),
    COALESCE(pm.apenas_ministerio,false),
    v_role
  FROM permissoes_modulo pm
  WHERE pm.modulo = p_modulo AND pm.role = v_role;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false,false,false,false,false,false,false,v_role;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_permissao(p_modulo text, p_acao text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := (SELECT auth.uid());
  v_role app_role;
  v_perm permissoes_modulo%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  SELECT role INTO v_role FROM user_roles WHERE user_id = v_uid LIMIT 1;
  IF v_role IS NULL THEN RETURN false; END IF;

  SELECT * INTO v_perm
  FROM permissoes_modulo
  WHERE modulo = p_modulo AND role = v_role;

  IF NOT FOUND THEN RETURN false; END IF;

  RETURN CASE p_acao
    WHEN 'ver'      THEN v_perm.pode_ver
    WHEN 'criar'    THEN v_perm.pode_criar
    WHEN 'editar'   THEN v_perm.pode_editar
    WHEN 'excluir'  THEN v_perm.pode_excluir
    WHEN 'exportar' THEN v_perm.pode_exportar
    ELSE false
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_pode_editar_obs_pastoral()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT has_any_role((SELECT auth.uid()), ARRAY['admin'::app_role,'pastor'::app_role,'diakonia'::app_role])
$function$
;

CREATE OR REPLACE FUNCTION public.fn_pode_executar(acao text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := (SELECT auth.uid());
  v_role app_role;
BEGIN
  SELECT role INTO v_role FROM user_roles WHERE user_id = v_uid LIMIT 1;
  IF v_role IS NULL THEN RETURN false; END IF;

  RETURN CASE acao
    -- Exclusão: só admin
    WHEN 'excluir'              THEN v_role = 'admin'
    -- Cadastros
    WHEN 'cadastrar_membro'     THEN v_role IN ('admin','secretaria','operador')
    WHEN 'editar_membro'        THEN v_role IN ('admin','secretaria','operador','diakonia')
    WHEN 'exportar_dados'       THEN v_role IN ('admin','secretaria','pastor')
    -- Ministérios
    WHEN 'gerir_ministerio'     THEN v_role IN ('admin','lideranca')
    WHEN 'gerar_escala'         THEN v_role IN ('admin','lideranca')
    WHEN 'gerir_voluntarios'    THEN v_role IN ('admin','lideranca')
    -- Financeiro
    WHEN 'acessar_financeiro'   THEN v_role IN ('admin','secretaria','pastor')
    -- Configurações
    WHEN 'acessar_configuracoes' THEN v_role = 'admin'
    WHEN 'gerir_usuarios'       THEN v_role = 'admin'
    -- Visualizações globais
    WHEN 'ver_todas_pessoas'    THEN v_role IN ('admin','secretaria','pastor','operador','diakonia')
    WHEN 'ver_todos_ministerios' THEN v_role IN ('admin','secretaria','pastor','operador','diakonia')
    WHEN 'ver_todas_escalas'    THEN v_role IN ('admin','secretaria','pastor','operador','diakonia')
    WHEN 'ver_agenda'           THEN true
    WHEN 'visualizar'           THEN true
    WHEN 'confirmar_presenca'   THEN true
    -- Observações pastorais
    WHEN 'registrar_obs_pastoral' THEN v_role IN ('admin','pastor','diakonia')
    -- Relatórios
    WHEN 'ver_relatorios'       THEN v_role IN ('admin','secretaria','pastor','diakonia')
    ELSE false
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_status_por_visitas()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.numero_visitas >= 2 THEN
    NEW.status_acolhimento := 'retornou';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_sync_acesso_sistema()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE membros SET tem_acesso_sistema = true WHERE id = NEW.user_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    -- Só desativa se não houver outros roles
    UPDATE membros SET tem_acesso_sistema = false
    WHERE id = OLD.user_id
      AND NOT EXISTS (SELECT 1 FROM user_roles WHERE user_id = OLD.user_id AND id != OLD.id);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_todas_minhas_permissoes()
 RETURNS TABLE(modulo text, pode_ver boolean, pode_criar boolean, pode_editar boolean, pode_excluir boolean, pode_exportar boolean, apenas_proprio boolean, apenas_ministerio boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := (SELECT auth.uid());
  v_role app_role;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  SELECT ur.role INTO v_role FROM user_roles ur WHERE ur.user_id = v_uid LIMIT 1;
  IF v_role IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT
    pm.modulo,
    pm.pode_ver,
    pm.pode_criar,
    pm.pode_editar,
    pm.pode_excluir,
    pm.pode_exportar,
    pm.apenas_proprio,
    pm.apenas_ministerio
  FROM permissoes_modulo pm
  WHERE pm.role = v_role
  ORDER BY pm.modulo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.gbt_bit_compress(internal)
 RETURNS internal
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/btree_gist', $function$gbt_bit_compress$function$
;

CREATE OR REPLACE FUNCTION public.gbt_bit_consistent(internal, bit, smallint, oid, internal)
 RETURNS boolean
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
