CREATE OR REPLACE FUNCTION public.gerar_notificacoes_campanha(p_campanha_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inicio DATE;
  v_fim    DATE;
  v_dia    DATE;
BEGIN
  SELECT data_inicio, data_fim INTO v_inicio, v_fim
  FROM public.campanhas WHERE id = p_campanha_id;

  DELETE FROM public.campanha_notificacoes
  WHERE campanha_id = p_campanha_id AND NOT enviada;

  INSERT INTO public.campanha_notificacoes(campanha_id, tipo, data_envio, mensagem)
  VALUES(p_campanha_id, 'inicio', v_inicio, 'A campanha começa hoje!');

  v_dia := v_inicio + 1;
  WHILE v_dia < v_fim LOOP
    INSERT INTO public.campanha_notificacoes(campanha_id, tipo, data_envio, mensagem)
    VALUES(p_campanha_id, 'lembrete_diario', v_dia,
           'Lembrete: campanha em andamento — Dia ' || (v_dia - v_inicio + 1));
    v_dia := v_dia + 1;
  END LOOP;

  INSERT INTO public.campanha_notificacoes(campanha_id, tipo, data_envio, mensagem)
  VALUES(p_campanha_id, 'encerramento', v_fim, 'A campanha encerra hoje!');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_email(target_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  caller_role TEXT;
  user_email  TEXT;
BEGIN
  SELECT role INTO caller_role FROM profiles WHERE id = auth.uid();
  IF caller_role NOT IN ('admin', 'secretaria') THEN
    RAISE EXCEPTION 'Permissao negada.';
  END IF;
  SELECT email INTO user_email FROM auth.users WHERE id = target_user_id;
  RETURN user_email;
END;
$function$
;

