CREATE OR REPLACE FUNCTION public.solicitar_lgpd(p_email text, p_tipo text, p_descricao text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id UUID; v_pid UUID;
BEGIN
  SELECT id INTO v_pid FROM public.pessoas WHERE email=p_email LIMIT 1;
  INSERT INTO public.solicitacoes_lgpd (pessoa_id,email_solicitante,tipo,descricao)
  VALUES (v_pid,p_email,p_tipo,p_descricao) RETURNING id INTO v_id;
