CREATE OR REPLACE FUNCTION public.sugerir_classe_ebd(p_data_nascimento date, p_sexo text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  WITH calc AS (
    SELECT EXTRACT(YEAR FROM AGE(CURRENT_DATE, p_data_nascimento))::int AS idade
  )
  SELECT c.id
    FROM public.ebd_classes c, calc
   WHERE c.ativo = true
     AND (c.idade_min IS NULL OR calc.idade >= c.idade_min)
     AND (c.idade_max IS NULL OR calc.idade <= c.idade_max)
     AND (c.genero = 'misto'
          OR (p_sexo IS NOT NULL AND c.genero = p_sexo))
   ORDER BY 
     (c.genero <> 'misto') DESC,  -- prefere classe específica de gênero
     COALESCE(c.idade_max - c.idade_min, 999) ASC,
     c.ordem ASC
   LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.sugerir_identidade_por_tag(p_tag text, p_limite integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_result JSONB;
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
    'secao_id',     s.id,
    'secao_titulo', s.titulo,
    'trecho',       left(s.conteudo, 400),
    'doc_tipo',     d.tipo,
    'doc_titulo',   d.titulo,
    'referencia',   d.titulo || CASE WHEN s.titulo <> '' THEN ' — ' || s.titulo ELSE '' END
  ))
  INTO v_result
  FROM public.secoes_documento s
  JOIN public.documentos d ON d.id = s.documento_id
  WHERE s.tags_conceituais @> ARRAY[lower(p_tag)]
    AND d.vigente = true
    AND s.conteudo IS NOT NULL AND s.conteudo <> ''
  ORDER BY d.tipo, s.ordem
  LIMIT p_limite;
  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sugerir_vinculos_familiares(p_pessoa_id uuid DEFAULT NULL::uuid, p_nome_completo text DEFAULT NULL::text)
 RETURNS TABLE(pessoa_id uuid, nome_completo text, sobrenome text, familia_id uuid, familia_nome text, parentesco text, responsavel boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH base AS (
    SELECT public.extrair_sobrenome(
      COALESCE(p_nome_completo, (SELECT nome_completo FROM public.membros WHERE id = p_pessoa_id))
    ) AS sobrenome_base
  )
  SELECT 
    m.id,
    m.nome_completo,
    public.extrair_sobrenome(m.nome_completo) AS sobrenome,
    vf.familia_id,
    f.nome_familia,
    vf.parentesco::text,
    COALESCE(vf.responsavel_familia, false) AS responsavel
  FROM public.membros m
  LEFT JOIN public.vinculos_familiares vf ON vf.membro_id = m.id
  LEFT JOIN public.familias f             ON f.id = vf.familia_id
  WHERE m.id IS DISTINCT FROM p_pessoa_id
    AND m.status = 'ativo'
    AND m.tipo_pessoa IN ('membro','congregado','visitante')
    AND public.extrair_sobrenome(m.nome_completo) = (SELECT sobrenome_base FROM base)
    AND (SELECT sobrenome_base FROM base) IS NOT NULL
    AND length((SELECT sobrenome_base FROM base)) >= 3
  ORDER BY 
    (vf.familia_id IS NOT NULL) DESC,
    COALESCE(vf.responsavel_familia, false) DESC,
    m.nome_completo
  LIMIT 30;
$function$
;

CREATE OR REPLACE FUNCTION public.sugerir_voluntarios_escala(p_area_id uuid, p_data_evento date, p_dia_semana text DEFAULT NULL::text, p_turno text DEFAULT NULL::text, p_limite integer DEFAULT 10)
 RETURNS TABLE(pessoa_id uuid, nome_completo text, score numeric, motivo text, ultima_escala_em date, total_escalas_mes bigint, carga_atual integer, nivel_sobrecarga integer, disponivel boolean, em_descanso boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mes_atual DATE := date_trunc('month', p_data_evento)::DATE;
  v_mes_fim   DATE := (date_trunc('month', p_data_evento) + interval '1 month - 1 day')::DATE;
BEGIN
  RETURN QUERY
  WITH
  voluntarios_area AS (
    SELECT av.membro_id AS pid
    FROM area_voluntarios av
    WHERE av.area_id = p_area_id
      AND av.status = 'ativa'
      AND av.data_fim IS NULL
  ),
  escalas_mes AS (
    SELECT ev.pessoa_id, count(*) AS total_mes
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    WHERE e.area_id = p_area_id
      AND e.data_evento BETWEEN v_mes_atual AND v_mes_fim
      AND ev.status NOT IN ('recusado')
    GROUP BY ev.pessoa_id
  ),
  ultima_escala AS (
    SELECT ev.pessoa_id, max(e.data_evento) AS ultima_data
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    WHERE ev.status IN ('confirmado','presente')
    GROUP BY ev.pessoa_id
  ),
  ja_escalado AS (
    SELECT ev.pessoa_id
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    WHERE e.area_id = p_area_id
      AND e.data_evento = p_data_evento
      AND ev.status != 'recusado'
  ),
  base AS (
    SELECT
      m.id            AS pessoa_id,
      m.nome_completo,

      -- ── Choca com o dia pedido? ────────────────────────────────────────
      -- Só é TRUE quando há informação suficiente para afirmar. Perfil
      -- ausente, ou lista de dias vazia, devolve FALSE: não sabemos.
      (p_dia_semana IS NOT NULL
        AND ps.dias_disponiveis IS NOT NULL
        AND array_length(ps.dias_disponiveis, 1) > 0
        AND NOT (p_dia_semana::dia_semana = ANY (ps.dias_disponiveis))
      ) AS fora_do_dia,

      (p_turno IS NOT NULL
        AND ps.turnos_disponiveis IS NOT NULL
        AND array_length(ps.turnos_disponiveis, 1) > 0
        AND NOT ('dia_todo'::turno_disponibilidade = ANY (ps.turnos_disponiveis))
        AND NOT (p_turno::turno_disponibilidade = ANY (ps.turnos_disponiveis))
      ) AS fora_do_turno,

      ROUND(
        GREATEST(0, LEAST(100,
          50.0
          -- Teto de 40, alcançado aos 80 dias. Quem nunca serviu entra no
          -- teto (o COALESCE de 90 dias * 0.5 = 45, cortado em 40).
          + LEAST(40.0, COALESCE((p_data_evento - ue.ultima_data), 90) * 0.5)
          - COALESCE(ps.nivel_sobrecarga, 0) * 3.0
          - COALESCE(em.total_mes, 0) * 8.0
          + CASE WHEN p_area_id = ANY(COALESCE(ps.areas_preferidas, '{}')) THEN 10.0 ELSE 0 END
          - CASE WHEN p_area_id = ANY(COALESCE(ps.areas_evitar, '{}')) THEN 20.0 ELSE 0 END
        ))
      , 2) AS score,

      ue.ultima_data                  AS ultima_escala_em,
      COALESCE(em.total_mes, 0)       AS total_escalas_mes,
      COALESCE(ps.carga_atual_mes, 0) AS carga_atual,
      COALESCE(ps.nivel_sobrecarga,0) AS nivel_sobrecarga,
      COALESCE(ps.em_descanso, false) AS em_descanso,
      (ja_escalado.pessoa_id IS NOT NULL) AS ja_esta,
      COALESCE(ps.max_escalas_mes, 4) AS max_mes,
      (ps.pessoa_id IS NOT NULL)      AS tem_perfil
    FROM voluntarios_area va
    JOIN membros m ON m.id = va.pid AND m.status = 'ativo'
    LEFT JOIN perfil_servico ps ON ps.pessoa_id = va.pid AND ps.ativo = true
    LEFT JOIN escalas_mes em ON em.pessoa_id = va.pid
    LEFT JOIN ultima_escala ue ON ue.pessoa_id = va.pid
    LEFT JOIN ja_escalado ON ja_escalado.pessoa_id = va.pid
  ),
  julgada AS (
    SELECT b.*,
      (b.em_descanso = false
       AND b.ja_esta = false
       AND b.total_escalas_mes < b.max_mes
       AND b.fora_do_dia = false
       AND b.fora_do_turno = false
      ) AS disp,
      CASE
        WHEN b.em_descanso              THEN 'Em período de descanso'
        WHEN b.ja_esta                  THEN 'Já escalado para este evento'
        WHEN b.total_escalas_mes >= b.max_mes THEN 'Atingiu o limite do mês'
        WHEN b.fora_do_dia              THEN 'Não serve neste dia da semana'
        WHEN b.fora_do_turno            THEN 'Não serve neste turno'
        WHEN b.nivel_sobrecarga >= 7    THEN 'Carga elevada — revisão pastoral recomendada'
        WHEN b.nivel_sobrecarga >= 4    THEN 'Carga moderada — usar com cuidado'
        WHEN b.ultima_escala_em IS NULL AND NOT b.tem_perfil
                                        THEN 'Nunca serviu — e ainda não disse quando pode'
        WHEN b.ultima_escala_em IS NULL THEN 'Nunca serviu — ótima oportunidade de incluir'
        WHEN (p_data_evento - b.ultima_escala_em) > 30
                                        THEN 'Sem servir há ' || (p_data_evento - b.ultima_escala_em) || ' dias — priorizar'
        WHEN NOT b.tem_perfil           THEN 'Disponível, mas não informou quando pode servir'
        ELSE 'Disponível'
      END AS razao
    FROM base b
  ),
  -- O limite passa a valer POR GRUPO: os melhores disponíveis e os
  -- indisponíveis mais relevantes. Antes, um bloqueava o outro.
  ordenada AS (
    SELECT j.*,
      row_number() OVER (PARTITION BY j.disp ORDER BY j.score DESC, j.nome_completo ASC) AS posicao
    FROM julgada j
  )
  SELECT
    o.pessoa_id, o.nome_completo, o.score, o.razao,
    o.ultima_escala_em, o.total_escalas_mes, o.carga_atual,
    o.nivel_sobrecarga, o.disp, o.em_descanso
  FROM ordenada o
  WHERE o.posicao <= p_limite
  ORDER BY o.disp DESC, o.score DESC, o.nome_completo ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sugerir_voluntarios_escala(p_area_id uuid, p_data_evento date, p_dia_semana text DEFAULT NULL::text, p_turno text DEFAULT NULL::text, p_limite integer DEFAULT 10, p_hora_inicio time without time zone DEFAULT NULL::time without time zone, p_hora_fim time without time zone DEFAULT NULL::time without time zone)
 RETURNS TABLE(pessoa_id uuid, nome_completo text, score numeric, motivo text, ultima_escala_em date, total_escalas_mes bigint, carga_atual integer, nivel_sobrecarga integer, disponivel boolean, em_descanso boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mes_atual DATE := date_trunc('month', p_data_evento)::DATE;
  v_mes_fim   DATE := (date_trunc('month', p_data_evento) + interval '1 month - 1 day')::DATE;
BEGIN
  RETURN QUERY
  WITH
  voluntarios_area AS (
    SELECT av.membro_id AS pid
    FROM area_voluntarios av
    WHERE av.area_id = p_area_id
      AND av.status = 'ativa'
      AND av.data_fim IS NULL
  ),
  escalas_mes AS (
    SELECT ev.pessoa_id, count(*) AS total_mes
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    WHERE e.area_id = p_area_id
      AND e.data_evento BETWEEN v_mes_atual AND v_mes_fim
      AND ev.status NOT IN ('recusado')
    GROUP BY ev.pessoa_id
  ),
  ultima_escala AS (
    SELECT ev.pessoa_id, max(e.data_evento) AS ultima_data
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    WHERE ev.status IN ('confirmado','presente')
      AND e.data_evento <= p_data_evento
    GROUP BY ev.pessoa_id
  ),
  ja_escalado AS (
    SELECT ev.pessoa_id
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    WHERE e.area_id = p_area_id
      AND e.data_evento = p_data_evento
      AND ev.status != 'recusado'
  ),
  -- Em OUTRA área, no mesmo dia, com horário que cruza o desta escala.
  -- `tsrange` com limite aberto no fim: 10h–12h e 12h–14h não se cruzam.
  conflito_horario AS (
    SELECT ev.pessoa_id, min(COALESCE(a.nome, e.titulo)) AS onde
    FROM escala_voluntarios ev
    JOIN escalas e ON e.id = ev.escala_id
    LEFT JOIN areas a ON a.id = e.area_id
    WHERE e.data_evento = p_data_evento
      AND e.area_id IS DISTINCT FROM p_area_id
      AND ev.status != 'recusado'
      AND (
        p_hora_inicio IS NULL OR e.hora_inicio IS NULL
        OR tsrange(
             (p_data_evento + p_hora_inicio)::timestamp,
             (p_data_evento + COALESCE(p_hora_fim, p_hora_inicio + interval '1 hour'))::timestamp,
             '[)')
           && tsrange(
             (e.data_evento + e.hora_inicio)::timestamp,
             (e.data_evento + COALESCE(e.hora_fim, e.hora_inicio + interval '1 hour'))::timestamp,
             '[)')
      )
    GROUP BY ev.pessoa_id
  ),
  base AS (
    SELECT
      m.id AS pessoa_id,
      m.nome_completo,
      (p_dia_semana IS NOT NULL
        AND ps.dias_disponiveis IS NOT NULL
        AND array_length(ps.dias_disponiveis, 1) > 0
        AND NOT (p_dia_semana::dia_semana = ANY (ps.dias_disponiveis))
      ) AS fora_do_dia,
      (p_turno IS NOT NULL
        AND ps.turnos_disponiveis IS NOT NULL
        AND array_length(ps.turnos_disponiveis, 1) > 0
        AND NOT ('dia_todo'::turno_disponibilidade = ANY (ps.turnos_disponiveis))
        AND NOT (p_turno::turno_disponibilidade = ANY (ps.turnos_disponiveis))
      ) AS fora_do_turno,
      ch.onde AS conflito_com,
      ROUND(
        GREATEST(0, LEAST(100,
          50.0
          + LEAST(40.0, COALESCE((p_data_evento - ue.ultima_data), 90) * 0.5)
          - COALESCE(ps.nivel_sobrecarga, 0) * 3.0
          - COALESCE(em.total_mes, 0) * 8.0
          + CASE WHEN p_area_id = ANY(COALESCE(ps.areas_preferidas, '{}')) THEN 10.0 ELSE 0 END
          - CASE WHEN p_area_id = ANY(COALESCE(ps.areas_evitar, '{}')) THEN 20.0 ELSE 0 END
        ))
      , 2) AS score,
      ue.ultima_data                  AS ultima_escala_em,
      COALESCE(em.total_mes, 0)       AS total_escalas_mes,
      COALESCE(ps.carga_atual_mes, 0) AS carga_atual,
      COALESCE(ps.nivel_sobrecarga,0) AS nivel_sobrecarga,
      COALESCE(ps.em_descanso, false) AS em_descanso,
      (ja_escalado.pessoa_id IS NOT NULL) AS ja_esta,
      COALESCE(ps.max_escalas_mes, 4) AS max_mes,
      (ps.pessoa_id IS NOT NULL)      AS tem_perfil
    FROM voluntarios_area va
    JOIN membros m ON m.id = va.pid AND m.status = 'ativo'
    LEFT JOIN perfil_servico ps ON ps.pessoa_id = va.pid AND ps.ativo = true
    LEFT JOIN escalas_mes em ON em.pessoa_id = va.pid
    LEFT JOIN ultima_escala ue ON ue.pessoa_id = va.pid
    LEFT JOIN ja_escalado ON ja_escalado.pessoa_id = va.pid
    LEFT JOIN conflito_horario ch ON ch.pessoa_id = va.pid
  ),
  julgada AS (
    SELECT b.*,
      (b.em_descanso = false
       AND b.ja_esta = false
       AND b.conflito_com IS NULL
       AND b.total_escalas_mes < b.max_mes
       AND b.fora_do_dia = false
       AND b.fora_do_turno = false
      ) AS disp,
      CASE
        WHEN b.em_descanso              THEN 'Em período de descanso'
        WHEN b.ja_esta                  THEN 'Já escalado para este evento'
        -- Antes de qualquer outra razão: estar em dois lugares ao mesmo tempo
        -- é impossível, e as outras razões são só desaconselhamento.
        WHEN b.conflito_com IS NOT NULL THEN 'Já escalado em ' || b.conflito_com || ' neste horário'
        WHEN b.total_escalas_mes >= b.max_mes THEN 'Atingiu o limite do mês'
        WHEN b.fora_do_dia              THEN 'Não serve neste dia da semana'
        WHEN b.fora_do_turno            THEN 'Não serve neste turno'
        WHEN b.nivel_sobrecarga >= 7    THEN 'Carga elevada — revisão pastoral recomendada'
        WHEN b.nivel_sobrecarga >= 4    THEN 'Carga moderada — usar com cuidado'
        WHEN b.ultima_escala_em IS NULL AND NOT b.tem_perfil
                                        THEN 'Nunca serviu — e ainda não disse quando pode'
        WHEN b.ultima_escala_em IS NULL THEN 'Nunca serviu — ótima oportunidade de incluir'
        WHEN (p_data_evento - b.ultima_escala_em) > 30
                                        THEN 'Sem servir há ' || (p_data_evento - b.ultima_escala_em) || ' dias — priorizar'
        WHEN NOT b.tem_perfil           THEN 'Disponível, mas não informou quando pode servir'
        ELSE 'Disponível'
      END AS razao
    FROM base b
  ),
  ordenada AS (
    SELECT j.*,
      row_number() OVER (PARTITION BY j.disp ORDER BY j.score DESC, j.nome_completo ASC) AS posicao
    FROM julgada j
  )
  SELECT
    o.pessoa_id, o.nome_completo, o.score, o.razao,
    o.ultima_escala_em, o.total_escalas_mes, o.carga_atual,
    o.nivel_sobrecarga, o.disp, o.em_descanso
  FROM ordenada o
  WHERE o.posicao <= p_limite
  ORDER BY o.disp DESC, o.score DESC, o.nome_completo ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tem_permissao(p_codigo text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.user_roles ur
    join public.role_permissoes rp on rp.role = ur.role
    where ur.user_id = auth.uid()
      and rp.permissao_codigo = p_codigo
  );
$function$
;

