CREATE OR REPLACE FUNCTION public.validar_convite(p_token uuid)
 RETURNS TABLE(valido boolean, motivo text, pessoa_id uuid, nome_completo text, telefone text, role text, tipo text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  v_conv  convites_acesso%ROWTYPE;
  v_pess  membros%ROWTYPE;
BEGIN
  SELECT * INTO v_conv FROM convites_acesso WHERE convites_acesso.token = p_token;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Convite não encontrado', NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  IF v_conv.used_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'Convite já foi utilizado', NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  IF v_conv.expires_at < now() THEN
    RETURN QUERY SELECT false, 'Convite expirado. Solicite um novo à secretaria.', NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  SELECT * INTO v_pess FROM membros WHERE id = v_conv.pessoa_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Pessoa do convite não encontrada', NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    true, NULL::TEXT,
    v_pess.id, v_pess.nome_completo, v_pess.telefone_celular,
    v_conv.role::TEXT, v_conv.tipo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_evento_conflito()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conflito_titulo text;
  v_conflito_inicio time;
  v_conflito_fim time;
BEGIN
  IF NEW.status = 'cancelado' OR NEW.local_id IS NULL
     OR NEW.hora_inicio IS NULL OR NEW.hora_fim IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT titulo, hora_inicio, hora_fim
    INTO v_conflito_titulo, v_conflito_inicio, v_conflito_fim
  FROM public.eventos
  WHERE id <> NEW.id
    AND local_id = NEW.local_id
    AND data = NEW.data
    AND status <> 'cancelado'
    AND hora_inicio IS NOT NULL AND hora_fim IS NOT NULL
    AND NEW.hora_inicio < hora_fim
    AND NEW.hora_fim > hora_inicio
  LIMIT 1;

  IF v_conflito_titulo IS NOT NULL THEN
    RAISE EXCEPTION 'Este local já está reservado neste horário (conflito com "%": %–%).',
      v_conflito_titulo, v_conflito_inicio, v_conflito_fim;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.validate_evento_local()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status local_status;
  v_permite boolean;
BEGIN
  IF NEW.local_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT status, permite_agendamento INTO v_status, v_permite
  FROM public.locais WHERE id = NEW.local_id;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Local informado não existe.';
  END IF;
  IF v_status <> 'ativo' THEN
    RAISE EXCEPTION 'Local inativo não pode ser usado em eventos.';
  END IF;
  IF v_permite = false THEN
    RAISE EXCEPTION 'Este local não permite agendamento.';
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.validate_evento_ministerios()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_evento uuid;
  v_principais int;
begin
  if tg_op = 'DELETE' then
    v_evento := old.evento_id;
  else
    v_evento := new.evento_id;
  end if;

  select count(*) filter (where responsabilidade = 'principal')
    into v_principais
  from public.evento_ministerios
  where evento_id = v_evento;

  -- Sem teto de quantidade: quem limita é a lista de ministérios da igreja.
  if v_principais > 1 then
    raise exception 'Um evento tem um ministério principal. Os demais entram como apoio.';
  end if;

  return coalesce(new, old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.verifica_conflito_ocupacao(p_local_id uuid, p_periodo tstzrange, p_origem text, p_excluir_ref_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conflito record;
begin
  if p_local_id is null then
    return jsonb_build_object('conflito', false);
  end if;
  -- Procura o primeiro conflito (informação suficiente pra mensagem)
  select origem, ref_id, periodo into v_conflito
  from vw_ocupacao_local
  where local_id = p_local_id
    and periodo && p_periodo
    and not (origem = p_origem and ref_id = p_excluir_ref_id)
  limit 1;
  if not found then
    return jsonb_build_object('conflito', false);
  end if;
  return jsonb_build_object(
    'conflito', true,
    'origem',   v_conflito.origem,
    'ref_id',   v_conflito.ref_id,
    'periodo',  v_conflito.periodo::text
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.vincular_pessoa_familia(p_familia_id uuid, p_pessoa_id uuid, p_parentesco text, p_responsavel boolean DEFAULT false, p_copiar_endereco_para_familia boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_vinculo_id uuid;
  v_pessoa     public.membros%ROWTYPE;
BEGIN
  -- Se for responsavel, desmarca outros responsaveis dessa familia
  IF p_responsavel THEN
    UPDATE public.vinculos_familiares SET responsavel_familia = false 
     WHERE familia_id = p_familia_id;
  END IF;

  -- UPSERT do vinculo (uma pessoa so pode ter 1 vinculo ativo numa familia)
  INSERT INTO public.vinculos_familiares (familia_id, membro_id, parentesco, responsavel_familia)
  VALUES (p_familia_id, p_pessoa_id, p_parentesco::parentesco_tipo, p_responsavel)
  ON CONFLICT (familia_id, membro_id) DO UPDATE 
     SET parentesco = EXCLUDED.parentesco,
         responsavel_familia = EXCLUDED.responsavel_familia,
         updated_at = NOW()
  RETURNING id INTO v_vinculo_id;

  -- Se pediu pra copiar endereco
  IF p_copiar_endereco_para_familia THEN
    SELECT * INTO v_pessoa FROM public.membros WHERE id = p_pessoa_id;
    UPDATE public.familias SET
      endereco    = v_pessoa.endereco,
      numero      = v_pessoa.numero,
      complemento = v_pessoa.complemento,
      bairro      = v_pessoa.bairro,
      cidade      = v_pessoa.cidade,
      cep         = v_pessoa.cep,
      updated_at  = NOW()
     WHERE id = p_familia_id;
  END IF;

  RETURN v_vinculo_id;
END;
$function$
;

