CASE tipo
    WHEN 'reembolso_pessoa'::arr_mov_tipo THEN ((beneficiario_membro_id IS NOT NULL) AND (nf_numero IS NOT NULL))
    WHEN 'abate_compra_cnpj'::arr_mov_tipo THEN ((fin_lancamento_id IS NOT NULL) AND (nf_numero IS NOT NULL))
    WHEN 'reversao_admin'::arr_mov_tipo THEN (beneficiario_membro_id IS NULL)
    WHEN 'ajuste'::arr_mov_tipo THEN (ajuste_positivo IS NOT NULL)
    ELSE true
END);

