CREATE OR REPLACE VIEW public.arr_caixa_resumo AS  WITH vendas_agg AS (
         SELECT v.caixa_id,
            count(*) FILTER (WHERE v.cancelada = false) AS qtd_vendas,
            COALESCE(sum(v.valor_total) FILTER (WHERE v.cancelada = false), 0::numeric) AS total_bruto,
            COALESCE(sum(v.valor_total) FILTER (WHERE v.cancelada = false AND v.forma_pagamento = 'debito'::arr_forma_pgto), 0::numeric) AS total_debito,
            COALESCE(sum(v.valor_total) FILTER (WHERE v.cancelada = false AND v.forma_pagamento = 'credito'::arr_forma_pgto), 0::numeric) AS total_credito,
            COALESCE(sum(v.valor_total) FILTER (WHERE v.cancelada = false AND v.forma_pagamento = 'pix'::arr_forma_pgto), 0::numeric) AS total_pix,
            COALESCE(sum(v.valor_total) FILTER (WHERE v.cancelada = false AND v.forma_pagamento = 'dinheiro'::arr_forma_pgto), 0::numeric) AS total_dinheiro,
            COALESCE(sum(v.valor_total) FILTER (WHERE v.cancelada = false AND v.forma_pagamento = 'outros'::arr_forma_pgto), 0::numeric) AS total_outros
           FROM arr_vendas v
          WHERE v.arquivado_em IS NULL
          GROUP BY v.caixa_id
        ), mov_agg AS (
         SELECT m.caixa_id,
            COALESCE(sum(m.valor) FILTER (WHERE m.tipo = 'custo'::arr_mov_tipo), 0::numeric) AS total_custos,
            COALESCE(sum(m.valor) FILTER (WHERE m.tipo = 'reembolso_pessoa'::arr_mov_tipo), 0::numeric) AS total_reemb_pessoa,
            COALESCE(sum(m.valor) FILTER (WHERE m.tipo = 'abate_compra_cnpj'::arr_mov_tipo), 0::numeric) AS total_abate_cnpj,
            COALESCE(sum(m.valor) FILTER (WHERE m.tipo = 'reversao_admin'::arr_mov_tipo), 0::numeric) AS total_revertido,
            COALESCE(sum(
                CASE
                    WHEN m.tipo = 'ajuste'::arr_mov_tipo AND m.ajuste_positivo THEN m.valor
                    WHEN m.tipo = 'ajuste'::arr_mov_tipo AND NOT m.ajuste_positivo THEN - m.valor
                    ELSE 0::numeric
                END), 0::numeric) AS total_ajustes
           FROM arr_movimentos m
          WHERE m.arquivado_em IS NULL
          GROUP BY m.caixa_id
        )
 SELECT c.id AS caixa_id,
    c.reserva_id,
    c.estado,
    COALESCE(va.qtd_vendas, 0::bigint) AS qtd_vendas,
    COALESCE(va.total_bruto, 0::numeric) AS total_bruto,
    COALESCE(va.total_dinheiro, 0::numeric) AS total_dinheiro,
    COALESCE(va.total_pix, 0::numeric) AS total_pix,
    COALESCE(va.total_debito, 0::numeric) AS total_debito,
    COALESCE(va.total_credito, 0::numeric) AS total_credito,
    COALESCE(va.total_outros, 0::numeric) AS total_outros,
    round(COALESCE(va.total_debito, 0::numeric) * c.taxa_debito_pct / 100::numeric, 2) AS taxa_debito_calc,
    round(COALESCE(va.total_credito, 0::numeric) * c.taxa_credito_pct / 100::numeric, 2) AS taxa_credito_calc,
    round(COALESCE(va.total_pix, 0::numeric) * c.taxa_pix_pct / 100::numeric, 2) AS taxa_pix_calc,
    COALESCE(ma.total_custos, 0::numeric) AS total_custos,
    COALESCE(ma.total_reemb_pessoa, 0::numeric) AS total_reemb_pessoa,
    COALESCE(ma.total_abate_cnpj, 0::numeric) AS total_abate_cnpj,
    COALESCE(ma.total_revertido, 0::numeric) AS total_revertido,
    COALESCE(ma.total_ajustes, 0::numeric) AS total_ajustes,
    COALESCE(va.total_bruto, 0::numeric) - round(COALESCE(va.total_debito, 0::numeric) * c.taxa_debito_pct / 100::numeric, 2) - round(COALESCE(va.total_credito, 0::numeric) * c.taxa_credito_pct / 100::numeric, 2) - round(COALESCE(va.total_pix, 0::numeric) * c.taxa_pix_pct / 100::numeric, 2) - COALESCE(ma.total_custos, 0::numeric) - COALESCE(ma.total_reemb_pessoa, 0::numeric) - COALESCE(ma.total_abate_cnpj, 0::numeric) - COALESCE(ma.total_revertido, 0::numeric) + COALESCE(ma.total_ajustes, 0::numeric) AS saldo_virtual
   FROM arr_caixas c
     LEFT JOIN vendas_agg va ON va.caixa_id = c.id
     LEFT JOIN mov_agg ma ON ma.caixa_id = c.id
  WHERE c.arquivado_em IS NULL;

CREATE OR REPLACE VIEW public.v_conselho_da_igreja AS  SELECT m.id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
        CASE f.f
            WHEN 'presidente'::funcao_ministerial THEN 'Presidente'::text
            WHEN 'vice_presidente_1'::funcao_ministerial THEN '1º Vice Presidente'::text
            WHEN 'vice_presidente_2'::funcao_ministerial THEN '2º Vice Presidente'::text
            WHEN 'secretaria_1'::funcao_ministerial THEN '1ª Secretária'::text
            WHEN 'secretaria_2'::funcao_ministerial THEN '2ª Secretária'::text
            WHEN 'secretario'::funcao_ministerial THEN 'Secretário'::text
            WHEN 'tesoureiro_1'::funcao_ministerial THEN '1º Tesoureiro'::text
            WHEN 'tesoureiro_2'::funcao_ministerial THEN '2º Tesoureiro'::text
            WHEN 'tesoureiro'::funcao_ministerial THEN 'Tesoureiro'::text
            WHEN 'auditor'::funcao_ministerial THEN 'Auditor(a)'::text
            ELSE NULL::text
        END AS cargo,
        CASE f.f
            WHEN 'presidente'::funcao_ministerial THEN 1
            WHEN 'vice_presidente_1'::funcao_ministerial THEN 2
            WHEN 'vice_presidente_2'::funcao_ministerial THEN 2
            WHEN 'secretaria_1'::funcao_ministerial THEN 3
            WHEN 'secretaria_2'::funcao_ministerial THEN 3
            WHEN 'secretario'::funcao_ministerial THEN 3
            WHEN 'tesoureiro_1'::funcao_ministerial THEN 4
            WHEN 'tesoureiro_2'::funcao_ministerial THEN 4
            WHEN 'tesoureiro'::funcao_ministerial THEN 4
            WHEN 'auditor'::funcao_ministerial THEN 5
            ELSE NULL::integer
        END AS nivel_cargo,
    'diretoria'::text AS tipo_participacao,
    NULL::text AS contexto
   FROM membros m
     CROSS JOIN LATERAL unnest(m.funcoes_ministeriais) f(f)
  WHERE m.status = 'ativo'::membro_status AND (f.f = ANY (ARRAY['presidente'::funcao_ministerial, 'vice_presidente_1'::funcao_ministerial, 'vice_presidente_2'::funcao_ministerial, 'secretaria_1'::funcao_ministerial, 'secretaria_2'::funcao_ministerial, 'secretario'::funcao_ministerial, 'tesoureiro_1'::funcao_ministerial, 'tesoureiro_2'::funcao_ministerial, 'tesoureiro'::funcao_ministerial, 'auditor'::funcao_ministerial]))
UNION ALL
 SELECT m.id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
    'Líder de Ministério'::text AS cargo,
    10 AS nivel_cargo,
    'ministerio'::text AS tipo_participacao,
    mi.nome AS contexto
   FROM ministerios mi
     JOIN membros m ON m.id = mi.lider_id
  WHERE mi.ativo = true AND mi.lider_id IS NOT NULL
UNION ALL
 SELECT m.id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
    'Vice-líder de Ministério'::text AS cargo,
    11 AS nivel_cargo,
    'ministerio'::text AS tipo_participacao,
    mi.nome AS contexto
   FROM ministerios mi
     JOIN membros m ON m.id = mi.vice_lider_id
  WHERE mi.ativo = true AND mi.vice_lider_id IS NOT NULL
UNION ALL
 SELECT m.id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
    'Líder de Área'::text AS cargo,
    20 AS nivel_cargo,
    'area'::text AS tipo_participacao,
    a.nome AS contexto
   FROM areas a
     JOIN membros m ON m.id = a.lider_id
  WHERE a.ativo = true AND a.lider_id IS NOT NULL
UNION ALL
 SELECT m.id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
    'Co-líder de Área'::text AS cargo,
    21 AS nivel_cargo,
    'area'::text AS tipo_participacao,
    a.nome AS contexto
   FROM areas a
     JOIN membros m ON m.id = a.co_lider_id
  WHERE a.ativo = true AND a.co_lider_id IS NOT NULL
UNION ALL
 SELECT m.id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
    'Diácono'::text AS cargo,
    30 AS nivel_cargo,
    'diacono'::text AS tipo_participacao,
    NULL::text AS contexto
   FROM membros m
  WHERE m.status = 'ativo'::membro_status AND m.funcoes_ministeriais && ARRAY['diacono'::funcao_ministerial];

CREATE OR REPLACE VIEW public.v_dashboard_visitantes AS  SELECT count(*) AS total_visitantes,
    count(
        CASE
            WHEN data_entrada >= (now() - '7 days'::interval) THEN 1
            ELSE NULL::integer
        END) AS visitantes_semana,
    count(
        CASE
            WHEN numero_visitas >= 2 THEN 1
            ELSE NULL::integer
        END) AS retornaram,
    count(
        CASE
            WHEN status_acolhimento::text = 'novo'::text THEN 1
            ELSE NULL::integer
        END) AS sem_contato,
    count(
        CASE
            WHEN ultimo_contato_em IS NULL AND data_entrada <= (now() - '7 days'::interval) THEN 1
            ELSE NULL::integer
        END) AS atrasados_7d,
    count(
        CASE
            WHEN como_conheceu = 'amigo_familiar'::text THEN 1
            ELSE NULL::integer
        END) AS origem_amigo,
    count(
        CASE
            WHEN como_conheceu = 'indicacao_membro'::text THEN 1
            ELSE NULL::integer
        END) AS origem_membro,
    count(
        CASE
            WHEN como_conheceu = 'redes_sociais'::text THEN 1
            ELSE NULL::integer
        END) AS origem_redes,
    count(
        CASE
            WHEN como_conheceu = 'projeto_social'::text THEN 1
            ELSE NULL::integer
        END) AS origem_projeto,
    count(
        CASE
            WHEN como_conheceu = 'evento_igreja'::text THEN 1
            ELSE NULL::integer
        END) AS origem_evento,
    count(
        CASE
            WHEN como_conheceu = 'outros'::text OR como_conheceu IS NULL THEN 1
            ELSE NULL::integer
        END) AS origem_outros
   FROM membros
  WHERE tipo_pessoa = 'visitante'::tipo_pessoa AND status = 'ativo'::membro_status;

CREATE OR REPLACE VIEW public.v_diretoria_atual AS  SELECT pc.id,
    m.nome_completo,
    m.email,
    ci.nome AS cargo,
    ci.nivel_id,
    no.nome AS nivel_nome,
    pc.inicio_mandato,
    pc.fim_mandato
   FROM pessoas_cargos pc
     JOIN membros m ON m.id = pc.membro_id
     JOIN cargos_institucionais ci ON ci.id = pc.cargo_id
     JOIN niveis_organizacionais no ON no.id = ci.nivel_id
  WHERE pc.ativo = true
  ORDER BY ci.nivel_id, ci.nome;

CREATE OR REPLACE VIEW public.v_estrutura_fisica AS  SELECT u.id AS unidade_id,
    u.nome AS unidade_nome,
    u.tipo AS unidade_tipo,
    p.id AS predio_id,
    p.nome AS predio_nome,
    p.tipo AS predio_tipo,
    p.logradouro,
    p.numero,
    p.bairro,
    p.cidade,
    l.id AS local_id,
    l.nome AS local_nome,
    l.status_operacional,
    l.capacidade,
    l.permite_agendamento,
    l.proxima_manutencao
   FROM unidades u
     LEFT JOIN predios p ON p.unidade_id = u.id AND p.ativo = true
     LEFT JOIN locais l ON l.predio_id = p.id AND l.status <> 'inativo'::local_status
  WHERE u.ativa = true
  ORDER BY u.nome, p.nome, l.nome;

CREATE OR REPLACE VIEW public.v_igrejas_ativas AS  SELECT id,
    nome,
    cidade,
    estado
   FROM igrejas
  WHERE ativa = true;

CREATE OR REPLACE VIEW public.v_importacoes_resumo AS  SELECT i.id,
    i.nome_arquivo,
    i.status,
    i.total_linhas,
    i.importados,
    i.ignorados,
    i.duplicados,
    i.erros,
    i.created_at,
    i.concluido_em,
    p.email AS enviado_por_email
   FROM importacoes_membros i
     LEFT JOIN profiles p ON p.id = i.enviado_por;

CREATE OR REPLACE VIEW public.v_membros_mapa AS  SELECT id,
    COALESCE(nome_social, nome_completo) AS nome_exibicao,
    tipo_pessoa,
    status,
    latitude,
    longitude,
    endereco_completo,
    bairro,
    cidade,
    estado,
    cep,
    telefone_celular,
    geo_fonte
   FROM membros m
  WHERE latitude IS NOT NULL AND longitude IS NOT NULL AND (status <> ALL (ARRAY['falecido'::membro_status, 'inativo'::membro_status, 'transferido'::membro_status]));

CREATE OR REPLACE VIEW public.v_membros_perfil AS  SELECT m.id,
    m.nome_completo,
    m.email,
    m.telefone_celular,
    m.foto_url,
    m.status AS status_membro,
    m.tipo_pessoa,
    m.funcao_ministerial,
    m.tem_acesso_sistema,
    m.perfil_acesso AS perfil_acesso_legado,
    ur.role AS perfil_acesso_sistema,
        CASE
            WHEN ur.role = 'admin'::app_role THEN 'Administrador'::text
            WHEN ur.role = 'secretaria'::app_role THEN 'Secretaria'::text
            WHEN ur.role = 'lideranca'::app_role THEN 'Liderança'::text
            WHEN ur.role = 'diakonia'::app_role THEN 'Diakonia'::text
            WHEN ur.role = 'operador'::app_role THEN 'Operador'::text
            WHEN ur.role = 'voluntario'::app_role THEN 'Voluntário (sistema)'::text
            ELSE 'Sem acesso ao sistema'::text
        END AS perfil_acesso_label,
        CASE m.funcao_ministerial
            WHEN 'membro'::funcao_ministerial THEN 'Membro'::text
            WHEN 'voluntario'::funcao_ministerial THEN 'Voluntário'::text
            WHEN 'lider'::funcao_ministerial THEN 'Líder'::text
            WHEN 'pastor'::funcao_ministerial THEN 'Pastor'::text
            WHEN 'professor_ebd'::funcao_ministerial THEN 'Professor EBD'::text
            WHEN 'tesoureiro'::funcao_ministerial THEN 'Tesoureiro'::text
            WHEN 'secretario'::funcao_ministerial THEN 'Secretário'::text
            WHEN 'evangelista'::funcao_ministerial THEN 'Evangelista'::text
            WHEN 'missionario'::funcao_ministerial THEN 'Missionário'::text
            WHEN 'diacono'::funcao_ministerial THEN 'Diácono'::text
            WHEN 'presbitero'::funcao_ministerial THEN 'Presbítero'::text
            WHEN 'coordenador'::funcao_ministerial THEN 'Coordenador'::text
            WHEN 'obreiro'::funcao_ministerial THEN 'Obreiro'::text
            ELSE m.funcao_ministerial::text
        END AS funcao_ministerial_label,
    m.created_at,
    m.updated_at
   FROM membros m
     LEFT JOIN user_roles ur ON ur.user_id = m.id;

CREATE OR REPLACE VIEW public.v_meu_contexto AS  SELECT ur.user_id AS id,
    ur.role AS perfil_acesso,
        CASE ur.role
            WHEN 'admin'::app_role THEN 'Administrador'::text
            WHEN 'pastor'::app_role THEN 'Pastor'::text
            WHEN 'lideranca'::app_role THEN 'Líder'::text
            WHEN 'secretaria'::app_role THEN 'Secretaria'::text
            WHEN 'operador'::app_role THEN 'Operador'::text
            WHEN 'diakonia'::app_role THEN 'Diakonia'::text
            WHEN 'voluntario'::app_role THEN 'Voluntário'::text
            WHEN 'membro'::app_role THEN 'Membro'::text
            ELSE ur.role::text
        END AS perfil_label,
    m.nome_completo,
    m.email,
    m.foto_url,
    m.funcao_ministerial,
        CASE
            WHEN ur.role = 'lideranca'::app_role THEN fn_meu_ministerio_id()
            ELSE NULL::uuid
        END AS ministerio_id,
    mn.nome AS ministerio_nome,
    ur.role = 'admin'::app_role AS is_admin,
    ur.role = ANY (ARRAY['admin'::app_role, 'pastor'::app_role]) AS pode_ver_tudo,
    ur.role = 'admin'::app_role AS pode_excluir,
    ur.role = ANY (ARRAY['admin'::app_role, 'secretaria'::app_role, 'operador'::app_role]) AS pode_cadastrar,
    ur.role = ANY (ARRAY['admin'::app_role, 'lideranca'::app_role]) AS pode_gerir_ministerio,
    ur.role = 'admin'::app_role AS pode_configurar
   FROM user_roles ur
     LEFT JOIN membros m ON m.id = ur.user_id
     LEFT JOIN ministerios mn ON mn.id =
        CASE
            WHEN ur.role = 'lideranca'::app_role THEN fn_meu_ministerio_id()
            ELSE NULL::uuid
        END
  WHERE ur.user_id = (( SELECT auth.uid() AS uid));

CREATE OR REPLACE VIEW public.v_minha_escala AS  SELECT ev.id AS escala_vol_id,
    e.id AS escala_id,
    e.titulo,
    e.data_evento,
    e.hora_inicio,
    e.hora_fim,
    e.local,
    a.nome AS area_nome,
    a.cor_identidade AS area_cor,
    mn.nome AS ministerio_nome,
    ev.funcao,
    ev.status,
    ev.sugerido_automaticamente,
    ev.pessoa_id
   FROM escala_voluntarios ev
     JOIN escalas e ON e.id = ev.escala_id
     JOIN areas a ON a.id = e.area_id
     LEFT JOIN ministerios mn ON mn.id = e.ministerio_id
  WHERE e.data_evento >= CURRENT_DATE AND ev.status <> 'recusado'::status_presenca_escala
  ORDER BY e.data_evento;

CREATE OR REPLACE VIEW public.v_proximas_escalas AS  SELECT e.id,
    e.titulo,
    e.data_evento,
    e.hora_inicio,
    e.hora_fim,
    e.local,
    e.status,
    a.nome AS area_nome,
    a.cor_identidade AS area_cor,
    mn.nome AS ministerio_nome,
    count(ev.id) AS total_escalados,
    sum(
        CASE
            WHEN ev.status = 'confirmado'::status_presenca_escala THEN 1
            ELSE 0
        END) AS confirmados,
    sum(
        CASE
            WHEN ev.status = 'pendente'::status_presenca_escala THEN 1
            ELSE 0
        END) AS pendentes,
    sum(
        CASE
            WHEN ev.status = 'recusado'::status_presenca_escala THEN 1
            ELSE 0
        END) AS recusados
   FROM escalas e
     JOIN areas a ON a.id = e.area_id
     LEFT JOIN ministerios mn ON mn.id = e.ministerio_id
     LEFT JOIN escala_voluntarios ev ON ev.escala_id = e.id
  WHERE e.data_evento >= CURRENT_DATE
  GROUP BY e.id, a.nome, a.cor_identidade, mn.nome
  ORDER BY e.data_evento, e.hora_inicio;

CREATE OR REPLACE VIEW public.v_ranking_convidadores AS  SELECT m.id,
    m.nome_completo,
    m.tipo_pessoa,
    count(v.id) AS total_convidados,
    count(
        CASE
            WHEN v.numero_visitas >= 2 THEN 1
            ELSE NULL::integer
        END) AS retornaram,
    count(
        CASE
            WHEN v.tipo_pessoa = ANY (ARRAY['congregado'::tipo_pessoa, 'membro'::tipo_pessoa]) THEN 1
            ELSE NULL::integer
        END) AS convertidos,
    round(count(v.id)::numeric * 1.0 + count(
        CASE
            WHEN v.numero_visitas >= 2 THEN 1
            ELSE NULL::integer
        END)::numeric * 2.0 + count(
        CASE
            WHEN v.tipo_pessoa = ANY (ARRAY['congregado'::tipo_pessoa, 'membro'::tipo_pessoa]) THEN 1
            ELSE NULL::integer
        END)::numeric * 5.0, 0)::integer AS score_convites
   FROM membros m
     JOIN membros v ON v.quem_convidou_id = m.id
  GROUP BY m.id, m.nome_completo, m.tipo_pessoa
  ORDER BY (count(v.id)) DESC, (round(count(v.id)::numeric * 1.0 + count(
        CASE
            WHEN v.numero_visitas >= 2 THEN 1
            ELSE NULL::integer
        END)::numeric * 2.0 + count(
        CASE
            WHEN v.tipo_pessoa = ANY (ARRAY['congregado'::tipo_pessoa, 'membro'::tipo_pessoa]) THEN 1
            ELSE NULL::integer
        END)::numeric * 5.0, 0)::integer) DESC
 LIMIT 10;

CREATE OR REPLACE VIEW public.v_solicitacoes_lgpd AS  SELECT id,
    pessoa_id,
    email_solicitante,
    tipo,
    descricao,
    status,
    resposta,
    solicitado_em,
    concluido_em,
    atendido_por,
    solicitado_em + '15 days'::interval AS prazo_legal,
        CASE
            WHEN (status = ANY (ARRAY['pendente'::text, 'em_analise'::text])) AND now() > (solicitado_em + '15 days'::interval) THEN true
            ELSE false
        END AS prazo_vencido
   FROM solicitacoes_lgpd;

CREATE OR REPLACE VIEW public.v_visitantes_alerta AS  SELECT id,
    nome_completo,
    telefone_celular,
    status_acolhimento,
    data_entrada,
    numero_visitas,
    score_engajamento,
    ultimo_contato_em,
    como_conheceu,
    quem_convidou_id,
        CASE
            WHEN status_acolhimento::text = 'novo'::text THEN 'sem_acolhimento'::text
            WHEN ultimo_contato_em IS NULL AND data_entrada <= (now() - '7 days'::interval)::date THEN 'sem_contato_7d'::text
            WHEN ultimo_contato_em IS NOT NULL AND ultimo_contato_em <= (now() - '7 days'::interval) AND (status_acolhimento::text <> ALL (ARRAY['congregado'::text, 'membro'::text])) THEN 'sem_retorno_7d'::text
            WHEN numero_visitas >= 2 THEN 'retornou'::text
            ELSE 'ok'::text
        END AS alerta,
        CASE
            WHEN status_acolhimento::text = 'novo'::text THEN 'alta'::text
            WHEN ultimo_contato_em IS NULL AND data_entrada <= (now() - '7 days'::interval)::date THEN 'alta'::text
            WHEN ultimo_contato_em <= (now() - '7 days'::interval) THEN 'media'::text
            WHEN numero_visitas = 1 AND status_acolhimento::text = 'contatado'::text THEN 'media'::text
            ELSE 'baixa'::text
        END AS prioridade,
    EXTRACT(day FROM now() - data_entrada::timestamp without time zone::timestamp with time zone)::integer AS dias_desde_visita,
        CASE
            WHEN numero_visitas >= 3 AND tipo_pessoa = 'visitante'::tipo_pessoa THEN 'converter_congregado'::text
            WHEN status_acolhimento::text = 'em_relacionamento'::text THEN 'inserir_grupo'::text
            WHEN status_acolhimento::text = 'novo'::text THEN 'fazer_contato'::text
            ELSE NULL::text
        END AS sugestao
   FROM membros m
  WHERE tipo_pessoa = 'visitante'::tipo_pessoa AND status = 'ativo'::membro_status
  ORDER BY (
        CASE
            WHEN status_acolhimento::text = 'novo'::text THEN 0
            WHEN ultimo_contato_em IS NULL THEN 1
            ELSE 2
        END), data_entrada DESC;

CREATE OR REPLACE VIEW public.v_voluntarios_completo AS  SELECT av.membro_id AS pessoa_id,
    m.nome_completo,
    m.foto_url,
    m.telefone_celular,
    m.email,
    a.id AS area_id,
    a.nome AS area_nome,
    a.cor_identidade AS area_cor,
    mn.id AS ministerio_id,
    mn.nome AS ministerio_nome,
    mn.cor_identidade AS ministerio_cor,
    av.funcao,
    av.status AS status_voluntario,
    av.data_inicio,
    av.ultima_escala_em,
    av.total_escalas,
    COALESCE(ps.max_escalas_mes, 4) AS max_escalas_mes,
    COALESCE(ps.carga_atual_mes, 0) AS carga_atual_mes,
    COALESCE(ps.nivel_sobrecarga, 0) AS nivel_sobrecarga,
    COALESCE(ps.em_descanso, false) AS em_descanso,
    ps.descanso_ate,
    ps.frequencia_maxima,
    ps.dias_disponiveis,
    ps.turnos_disponiveis,
    ps.restricoes
   FROM area_voluntarios av
     JOIN membros m ON m.id = av.membro_id
     JOIN areas a ON a.id = av.area_id
     LEFT JOIN ministerios mn ON mn.id = a.ministerio_id
     LEFT JOIN perfil_servico ps ON ps.pessoa_id = av.membro_id
  WHERE av.data_fim IS NULL;

CREATE OR REPLACE VIEW public.vw_agenda_igreja AS  SELECT 'evento'::text AS origem,
    e.id AS ref_id,
    e.titulo,
    ((e.data + COALESCE(e.hora_inicio, '00:00:00'::time without time zone)) AT TIME ZONE 'America/Sao_Paulo'::text) AS inicio,
    (
        CASE
            WHEN e.hora_fim IS NOT NULL AND e.hora_inicio IS NOT NULL AND e.hora_fim < e.hora_inicio THEN e.data + 1 + e.hora_fim
            ELSE e.data + COALESCE(e.hora_fim, '23:59:00'::time without time zone)
        END AT TIME ZONE 'America/Sao_Paulo'::text) AS fim,
    COALESCE(l.nome, e.local, '—'::text) AS local_ou_espaco,
    e.tipo::text AS tipo,
    e.status::text AS status,
    NULL::text AS espaco_codigo,
    e.ministerio_principal_id AS ministerio_id
   FROM eventos e
     LEFT JOIN locais l ON l.id = e.local_id
  WHERE e.status = ANY (ARRAY['agendado'::evento_status, 'realizado'::evento_status])
UNION ALL
 SELECT 'arrecadacao'::text AS origem,
    r.id AS ref_id,
    r.finalidade AS titulo,
    lower(r.periodo) AS inicio,
    upper(r.periodo) AS fim,
    esp.nome AS local_ou_espaco,
    'arrecadacao'::text AS tipo,
    r.status::text AS status,
    esp.codigo AS espaco_codigo,
    NULL::uuid AS ministerio_id
   FROM arr_reservas r
     JOIN arr_espacos esp ON esp.id = r.espaco_id
  WHERE (r.status = ANY (ARRAY['aprovada'::arr_reserva_status, 'em_uso'::arr_reserva_status, 'encerrada'::arr_reserva_status])) AND r.arquivado_em IS NULL;

CREATE OR REPLACE VIEW public.vw_agenda_pastoral AS  SELECT 'aniversario'::text AS tipo,
    m.id::text AS ref_id,
    m.id AS pessoa_id,
    NULL::uuid AS familia_id,
    m.nome_completo AS titulo,
    m.nome_completo AS subtitulo,
    m.data_nascimento AS data_origem,
    proximo_aniversario(m.data_nascimento) AS proxima_data,
    date_part('year'::text, age(CURRENT_DATE::timestamp with time zone, m.data_nascimento::timestamp with time zone))::integer AS anos_vai_completar,
    m.telefone_celular AS telefone,
    NULL::text AS telefone_secundario,
    m.tipo_pessoa
   FROM membros m
  WHERE m.status = 'ativo'::membro_status AND m.data_nascimento IS NOT NULL AND (m.tipo_pessoa = ANY (ARRAY['membro'::tipo_pessoa, 'congregado'::tipo_pessoa, 'visitante'::tipo_pessoa]))
UNION ALL
 SELECT 'casamento'::text AS tipo,
    f.id::text AS ref_id,
    NULL::uuid AS pessoa_id,
    f.id AS familia_id,
    COALESCE(( SELECT string_agg(split_part(m2.nome_completo, ' '::text, 1), ' e '::text ORDER BY vf.responsavel_familia DESC, m2.nome_completo) AS string_agg
           FROM vinculos_familiares vf
             JOIN membros m2 ON m2.id = vf.membro_id
          WHERE vf.familia_id = f.id AND (vf.parentesco = ANY (ARRAY['pai_mae'::parentesco_tipo, 'conjuge'::parentesco_tipo])) AND m2.status = 'ativo'::membro_status), 'Família '::text || f.nome_familia) AS titulo,
    'Família '::text || f.nome_familia AS subtitulo,
    f.data_casamento AS data_origem,
    proximo_aniversario(f.data_casamento) AS proxima_data,
    date_part('year'::text, age(CURRENT_DATE::timestamp with time zone, f.data_casamento::timestamp with time zone))::integer AS anos_vai_completar,
    ( SELECT m3.telefone_celular
           FROM vinculos_familiares vf3
             JOIN membros m3 ON m3.id = vf3.membro_id
          WHERE vf3.familia_id = f.id AND vf3.responsavel_familia = true
         LIMIT 1) AS telefone,
    ( SELECT m4.telefone_celular
           FROM vinculos_familiares vf4
             JOIN membros m4 ON m4.id = vf4.membro_id
          WHERE vf4.familia_id = f.id AND vf4.responsavel_familia = false AND (vf4.parentesco = ANY (ARRAY['pai_mae'::parentesco_tipo, 'conjuge'::parentesco_tipo]))
          ORDER BY m4.nome_completo
         LIMIT 1) AS telefone_secundario,
    NULL::tipo_pessoa AS tipo_pessoa
   FROM familias f
  WHERE f.data_casamento IS NOT NULL
UNION ALL
 SELECT 'membresia'::text AS tipo,
    m.id::text AS ref_id,
    m.id AS pessoa_id,
    NULL::uuid AS familia_id,
    m.nome_completo AS titulo,
    m.nome_completo AS subtitulo,
    m.data_entrada AS data_origem,
    proximo_aniversario(m.data_entrada) AS proxima_data,
    date_part('year'::text, age(CURRENT_DATE::timestamp with time zone, m.data_entrada::timestamp with time zone))::integer AS anos_vai_completar,
    m.telefone_celular AS telefone,
    NULL::text AS telefone_secundario,
    m.tipo_pessoa
   FROM membros m
  WHERE m.status = 'ativo'::membro_status AND m.data_entrada IS NOT NULL AND m.tipo_pessoa = 'membro'::tipo_pessoa
UNION ALL
 SELECT 'pastorado'::text AS tipo,
    m.id::text AS ref_id,
    m.id AS pessoa_id,
    NULL::uuid AS familia_id,
    m.nome_completo AS titulo,
    m.nome_completo AS subtitulo,
    m.data_consagracao_pastoral AS data_origem,
    proximo_aniversario(m.data_consagracao_pastoral) AS proxima_data,
    date_part('year'::text, age(CURRENT_DATE::timestamp with time zone, m.data_consagracao_pastoral::timestamp with time zone))::integer AS anos_vai_completar,
    m.telefone_celular AS telefone,
    NULL::text AS telefone_secundario,
    m.tipo_pessoa
   FROM membros m
  WHERE m.status = 'ativo'::membro_status AND m.data_consagracao_pastoral IS NOT NULL AND m.funcoes_ministeriais && ARRAY['pastor'::funcao_ministerial, 'presidente'::funcao_ministerial, 'pastor_auxiliar'::funcao_ministerial, 'pastor_missionario'::funcao_ministerial];

CREATE OR REPLACE VIEW public.vw_arr_reservas_publica AS  SELECT r.id,
    r.finalidade,
    r.status,
    r.periodo,
    r.espaco_id,
    e.codigo AS espaco_codigo,
    e.nome AS espaco_nome
   FROM arr_reservas r
     JOIN arr_espacos e ON e.id = r.espaco_id
  WHERE (r.status = ANY (ARRAY['aprovada'::arr_reserva_status, 'em_uso'::arr_reserva_status, 'encerrada'::arr_reserva_status])) AND r.arquivado_em IS NULL;

CREATE OR REPLACE VIEW public.vw_assuntos_dashboard AS  SELECT id,
    titulo,
    descricao,
    status,
    prioridade,
    responsavel_id,
    responsavel_nome,
    prazo,
    data_criacao,
    data_conclusao,
    origem,
    reuniao_origem_id,
    vinculo_tipo,
    vinculo_id,
    vinculo_descricao,
    observacao_conclusao,
    vezes_discutido,
    ultima_atualizacao_em,
    created_by,
    created_at,
    updated_at,
        CASE
            WHEN status = 'concluido'::assunto_status THEN 'concluido'::text
            WHEN prazo IS NOT NULL AND prazo < CURRENT_DATE THEN 'atrasado'::text
            WHEN prazo IS NOT NULL AND prazo <= (CURRENT_DATE + '3 days'::interval) THEN 'vence_em_breve'::text
            WHEN ultima_atualizacao_em IS NOT NULL AND ultima_atualizacao_em < (now() - '7 days'::interval) THEN 'parado'::text
            ELSE 'normal'::text
        END AS situacao,
        CASE
            WHEN prazo IS NULL THEN NULL::integer
            ELSE prazo - CURRENT_DATE
        END AS dias_para_prazo
   FROM assuntos a;

CREATE OR REPLACE VIEW public.vw_ebd_alertas_idade AS  SELECT em.pessoa_id,
    m.nome_completo,
    m.sexo::text AS sexo,
    m.data_nascimento,
    EXTRACT(year FROM age(CURRENT_DATE::timestamp with time zone, m.data_nascimento::timestamp with time zone))::integer AS idade_atual,
    em.classe_id AS classe_atual_id,
    c.nome AS classe_atual,
    sugerir_classe_ebd(m.data_nascimento, m.sexo::text) AS classe_sugerida_id,
    c.idade_max,
    (m.data_nascimento + ((((c.idade_max + 1)::text) || ' years'::text)::interval))::date AS passou_da_faixa_em
   FROM ebd_matriculas em
     JOIN membros m ON m.id = em.pessoa_id
     JOIN ebd_classes c ON c.id = em.classe_id
  WHERE em.ativo = true AND m.data_nascimento IS NOT NULL AND c.idade_max IS NOT NULL AND EXTRACT(year FROM age(CURRENT_DATE::timestamp with time zone, m.data_nascimento::timestamp with time zone)) > c.idade_max::numeric AND em.progressao_dispensada_em IS NULL;

CREATE OR REPLACE VIEW public.vw_fin_centros_resumo AS  SELECT id,
    nome,
    vinculo_tipo,
    vinculo_id,
    vinculo_nome,
    centro_pai_id,
    cor,
    ativo,
    COALESCE(( SELECT sum(l.valor) AS sum
           FROM fin_lancamentos l
          WHERE l.centro_custo_id = cc.id AND l.tipo = 'saida'::fin_movimento_tipo AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status])) AND l.data >= (CURRENT_DATE - '90 days'::interval)), 0::numeric) AS gasto_90d,
    COALESCE(( SELECT sum(l.valor) AS sum
           FROM fin_lancamentos l
          WHERE l.centro_custo_id = cc.id AND l.tipo = 'entrada'::fin_movimento_tipo AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status])) AND l.data >= (CURRENT_DATE - '90 days'::interval)), 0::numeric) AS recebido_90d,
    COALESCE(( SELECT sum(l.valor) AS sum
           FROM fin_lancamentos l
          WHERE l.centro_custo_id = cc.id AND l.tipo = 'saida'::fin_movimento_tipo AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status])) AND l.data >= date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)), 0::numeric) AS gasto_mes,
    COALESCE(( SELECT count(l.id) AS count
           FROM fin_lancamentos l
          WHERE l.centro_custo_id = cc.id AND l.data >= (CURRENT_DATE - '90 days'::interval)), 0::bigint)::integer AS qtd_lancamentos_90d,
    ( SELECT max(fin_lancamentos.data) AS max
           FROM fin_lancamentos
          WHERE fin_lancamentos.centro_custo_id = cc.id) AS ultima_movimentacao
   FROM fin_centros_custo cc
  WHERE ativo;

CREATE OR REPLACE VIEW public.vw_fin_estoque_alertas AS  WITH consumo AS (
         SELECT fin_estoque_movimentos.item_id,
            sum(fin_estoque_movimentos.quantidade) FILTER (WHERE fin_estoque_movimentos.tipo = 'saida'::fin_estoque_movimento_tipo AND fin_estoque_movimentos.data >= (CURRENT_DATE - '90 days'::interval)) / 90.0 AS consumo_medio_dia
           FROM fin_estoque_movimentos
          WHERE fin_estoque_movimentos.data >= (CURRENT_DATE - '90 days'::interval)
          GROUP BY fin_estoque_movimentos.item_id
        )
 SELECT i.id,
    i.nome,
    i.unidade,
    i.categoria,
    i.estoque_atual,
    i.estoque_minimo,
    i.ponto_pedido,
    i.custo_medio,
    i.fornecedor_padrao_id,
    COALESCE(c.consumo_medio_dia, 0::numeric) AS consumo_medio_dia,
    COALESCE(c.consumo_medio_dia * 30::numeric, 0::numeric) AS consumo_medio_mes,
        CASE
            WHEN COALESCE(c.consumo_medio_dia, 0::numeric) > 0::numeric THEN floor(i.estoque_atual / c.consumo_medio_dia)::integer
            ELSE NULL::integer
        END AS dias_restantes_estimados,
        CASE
            WHEN i.estoque_atual <= 0::numeric THEN 'esgotado'::text
            WHEN i.estoque_atual <= i.estoque_minimo THEN 'critico'::text
            WHEN i.ponto_pedido IS NOT NULL AND i.estoque_atual <= i.ponto_pedido THEN 'comprar'::text
            WHEN COALESCE(c.consumo_medio_dia, 0::numeric) > 0::numeric AND floor(i.estoque_atual / c.consumo_medio_dia) <= 15::numeric THEN 'baixo'::text
            ELSE 'ok'::text
        END AS urgencia
   FROM fin_estoque_itens i
     LEFT JOIN consumo c ON c.item_id = i.id
  WHERE i.ativo;

CREATE OR REPLACE VIEW public.vw_fin_orcamento_vs_real AS  WITH mes_atual AS (
         SELECT EXTRACT(year FROM CURRENT_DATE)::integer AS ano,
            EXTRACT(month FROM CURRENT_DATE)::integer AS mes,
            date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)::date AS ini,
            (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) + '1 mon -1 days'::interval)::date AS fim
        )
 SELECT o.id,
    o.ano,
    o.mes,
    o.centro_custo_id,
    o.categoria_id,
    cc.nome AS centro_nome,
    o.valor_planejado,
    COALESCE(( SELECT sum(l.valor) AS sum
           FROM fin_lancamentos l,
            mes_atual m
          WHERE l.centro_custo_id = o.centro_custo_id AND (o.categoria_id IS NULL OR l.categoria_id = o.categoria_id) AND l.tipo = 'saida'::fin_movimento_tipo AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status])) AND l.data >= m.ini AND l.data <= m.fim), 0::numeric) AS valor_real,
        CASE
            WHEN o.valor_planejado = 0::numeric THEN 0::numeric
            ELSE round(100.0 * COALESCE(( SELECT sum(l.valor) AS sum
               FROM fin_lancamentos l,
                mes_atual m
              WHERE l.centro_custo_id = o.centro_custo_id AND (o.categoria_id IS NULL OR l.categoria_id = o.categoria_id) AND l.tipo = 'saida'::fin_movimento_tipo AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status])) AND l.data >= m.ini AND l.data <= m.fim), 0::numeric) / o.valor_planejado, 1)
        END AS percentual_consumido
   FROM fin_orcamentos o
     JOIN fin_centros_custo cc ON cc.id = o.centro_custo_id
     CROSS JOIN mes_atual ma
  WHERE (o.mes IS NULL OR o.mes = ma.mes) AND o.ano = ma.ano;

CREATE OR REPLACE VIEW public.vw_fin_proximos_vencimentos AS  SELECT l.id,
    l.data,
    l.tipo,
    l.status,
    l.valor,
    l.descricao,
    l.conta_id,
    c.nome AS conta_nome,
    l.categoria_id,
    k.nome AS categoria_nome,
    k.cor AS categoria_cor,
    l.fornecedor_id,
    f.nome AS fornecedor_nome,
    l.data - CURRENT_DATE AS dias_para_vencer,
        CASE
            WHEN l.data < CURRENT_DATE THEN 'vencido'::text
            WHEN l.data = CURRENT_DATE THEN 'vence_hoje'::text
            WHEN l.data <= (CURRENT_DATE + '3 days'::interval) THEN 'urgente'::text
            WHEN l.data <= (CURRENT_DATE + '7 days'::interval) THEN 'esta_semana'::text
            ELSE 'futuro'::text
        END AS urgencia
   FROM fin_lancamentos l
     LEFT JOIN fin_contas c ON c.id = l.conta_id
     LEFT JOIN fin_categorias k ON k.id = l.categoria_id
     LEFT JOIN fin_fornecedores f ON f.id = l.fornecedor_id
  WHERE l.status = 'previsto'::fin_lancamento_status;

CREATE OR REPLACE VIEW public.vw_fin_resumo_mes AS  WITH mes_atual AS (
         SELECT date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)::date AS ini,
            (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) + '1 mon -1 days'::interval)::date AS fim
        )
 SELECT ( SELECT COALESCE(sum(fin_contas.saldo_atual), 0::numeric) AS "coalesce"
           FROM fin_contas
          WHERE fin_contas.ativo) AS saldo_total,
    ( SELECT COALESCE(sum(l.valor), 0::numeric) AS "coalesce"
           FROM fin_lancamentos l,
            mes_atual m
          WHERE l.tipo = 'entrada'::fin_movimento_tipo AND l.data >= m.ini AND l.data <= m.fim AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status]))) AS entradas_mes,
    ( SELECT COALESCE(sum(l.valor), 0::numeric) AS "coalesce"
           FROM fin_lancamentos l,
            mes_atual m
          WHERE l.tipo = 'saida'::fin_movimento_tipo AND l.data >= m.ini AND l.data <= m.fim AND (l.status = ANY (ARRAY['realizado'::fin_lancamento_status, 'conciliado'::fin_lancamento_status]))) AS saidas_mes,
    ( SELECT COALESCE(sum(l.valor), 0::numeric) AS "coalesce"
           FROM fin_lancamentos l,
            mes_atual m
          WHERE l.tipo = 'saida'::fin_movimento_tipo AND l.status = 'previsto'::fin_lancamento_status AND l.data >= CURRENT_DATE AND l.data <= m.fim) AS previstas_mes;

CREATE OR REPLACE VIEW public.vw_gov_convocacao_lista AS  SELECT ap.assembleia_id,
    ap.pessoa_id,
    ap.pessoa_nome,
    m.telefone_celular,
    m.email
   FROM gov_assembleia_presentes ap
     LEFT JOIN membros m ON m.id = ap.pessoa_id;

CREATE OR REPLACE VIEW public.vw_ocupacao_local AS  SELECT e.local_id,
    tstzrange(((e.data + COALESCE(e.hora_inicio, '00:00:00'::time without time zone)) AT TIME ZONE 'America/Sao_Paulo'::text), (
        CASE
            WHEN e.hora_fim IS NOT NULL AND e.hora_inicio IS NOT NULL AND e.hora_fim < e.hora_inicio THEN e.data + 1 + e.hora_fim
            ELSE e.data + COALESCE(e.hora_fim, '23:59:00'::time without time zone)
        END AT TIME ZONE 'America/Sao_Paulo'::text), '[)'::text) AS periodo,
    'evento'::text AS origem,
    e.id AS ref_id
   FROM eventos e
  WHERE e.local_id IS NOT NULL AND e.status = 'agendado'::evento_status AND (e.recorrencia_regra IS NULL OR e.is_excecao = true OR e.recorrencia_id = e.id)
UNION ALL
 SELECT esp.local_id,
    r.periodo,
    'arrecadacao'::text AS origem,
    r.id AS ref_id
   FROM arr_reservas r
     JOIN arr_espacos esp ON esp.id = r.espaco_id
  WHERE esp.local_id IS NOT NULL AND (r.status = ANY (ARRAY['aprovada'::arr_reserva_status, 'em_uso'::arr_reserva_status])) AND r.arquivado_em IS NULL;

CREATE OR REPLACE VIEW public.vw_pgm_grupos_resumo AS  SELECT g.id,
    g.nome,
    g.descricao,
    g.dia_semana,
    g.horario,
    g.endereco,
    g.bairro,
    g.cidade,
    g.lider_id,
    g.co_lider_id,
    g.anfitriao_id,
    g.grupo_pai_id,
    g.multiplicado_em,
    g.whatsapp_link,
    g.ativo,
    g.data_inicio,
    g.created_at,
    g.updated_at,
    g.igreja_id,
    g.cep,
    g.numero,
    g.complemento,
    g.uf,
    ( SELECT count(*) AS count
           FROM pgm_membros m
          WHERE m.grupo_id = g.id AND m.ativo) AS qtd_membros,
    ( SELECT count(*) AS count
           FROM pgm_grupos f
          WHERE f.grupo_pai_id = g.id AND f.ativo) AS qtd_filhos,
    m_lider.nome_completo AS lider_nome,
    m_colider.nome_completo AS co_lider_nome,
    m_anfitri.nome_completo AS anfitriao_nome
   FROM pgm_grupos g
     LEFT JOIN membros m_lider ON m_lider.id = g.lider_id
     LEFT JOIN membros m_colider ON m_colider.id = g.co_lider_id
     LEFT JOIN membros m_anfitri ON m_anfitri.id = g.anfitriao_id;

CREATE OR REPLACE VIEW public.vw_pgm_proxima_reuniao AS  SELECT id AS grupo_id,
    nome,
    dia_semana,
    horario,
    bairro,
        CASE
            WHEN dia_semana IS NULL THEN NULL::date
            ELSE CURRENT_DATE + (dia_semana - EXTRACT(dow FROM CURRENT_DATE)::integer + 7) % 7
        END AS proxima_data
   FROM pgm_grupos g
  WHERE ativo;


