-- 8b · FUNCOES — segunda passagem  (397)
-- Resolve dependencia circular. Provado na Fase 4b: 9 funcoes referenciam views (vw_agenda_pastoral, vw_assuntos_dashboard, vw_fin_orcamento_vs_real) ou outras funcoes criadas depois delas, e falhavam na primeira passagem. Como tudo e CREATE OR REPLACE, repetir e idempotente.
-- ══════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.aceitar_convite(p_token uuid, p_senha text)
 RETURNS TABLE(ok boolean, erro text, email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  v_convite       public.convites_acesso%ROWTYPE;
  v_pessoa        public.membros%ROWTYPE;
  v_email_login   TEXT;
  v_user_id       UUID;
  v_telefone_norm TEXT;
BEGIN
  SELECT * INTO v_convite FROM public.convites_acesso ca WHERE ca.token = p_token;
  IF NOT FOUND THEN RETURN QUERY SELECT FALSE,'Convite invalido'::TEXT,NULL::TEXT; RETURN; END IF;
  IF v_convite.used_at IS NOT NULL THEN RETURN QUERY SELECT FALSE,'Convite ja utilizado'::TEXT,NULL::TEXT; RETURN; END IF;
  IF v_convite.expires_at < NOW() THEN RETURN QUERY SELECT FALSE,'Convite expirado'::TEXT,NULL::TEXT; RETURN; END IF;

  SELECT * INTO v_pessoa FROM public.membros m WHERE m.id = v_convite.pessoa_id;
  IF NOT FOUND THEN RETURN QUERY SELECT FALSE,'Pessoa nao encontrada'::TEXT,NULL::TEXT; RETURN; END IF;
  IF v_pessoa.telefone_celular IS NULL OR v_pessoa.telefone_celular = '' THEN
    RETURN QUERY SELECT FALSE,'Pessoa sem telefone'::TEXT,NULL::TEXT; RETURN;
  END IF;

  v_telefone_norm := public.normalizar_telefone(v_pessoa.telefone_celular);
  v_email_login   := v_telefone_norm || '@app.diakonia';

  SELECT u.id INTO v_user_id FROM auth.users u WHERE u.email = v_email_login LIMIT 1;

  IF v_user_id IS NOT NULL THEN
    UPDATE auth.users u
       SET encrypted_password = crypt(p_senha, gen_salt('bf')),
           updated_at         = NOW(),
           email_confirmed_at = COALESCE(u.email_confirmed_at, NOW()),
           raw_user_meta_data = COALESCE(u.raw_user_meta_data, '{}'::jsonb)
                              || jsonb_build_object(
                                   'must_change_password', false,
                                   'pessoa_id', v_pessoa.id,
                                   'nome', v_pessoa.nome_completo
                                 )
     WHERE u.id = v_user_id;
  ELSE
    v_user_id := gen_random_uuid();
    INSERT INTO auth.users (id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
    VALUES (v_user_id,'00000000-0000-0000-0000-000000000000','authenticated','authenticated',v_email_login,
            crypt(p_senha, gen_salt('bf')),NOW(),
            jsonb_build_object('provider','phone','providers',ARRAY['phone']),
            jsonb_build_object('must_change_password', false, 'pessoa_id', v_pessoa.id, 'nome', v_pessoa.nome_completo),
            NOW(),NOW());
  END IF;

  -- Sincronizar user_roles: apaga roles antigos e insere o do convite
  BEGIN
    DELETE FROM public.user_roles WHERE user_id = v_user_id;
    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, v_convite.role);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- Auto-aceite LGPD
  BEGIN
    INSERT INTO public.consentimento (auth_user_id, tipo, base_legal, aceito, texto_versao, canal, registrado_por)
    VALUES (v_user_id, 'politica_privacidade', 'consentimento', TRUE, '1.0', 'web_app', v_user_id)
    ON CONFLICT DO NOTHING;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  BEGIN
    INSERT INTO public.profiles AS p (id,pessoa_id,nome_completo,telefone,role,created_at,updated_at)
    VALUES (v_user_id, v_pessoa.id, v_pessoa.nome_completo, v_telefone_norm, v_convite.role, NOW(), NOW())
    ON CONFLICT (id) DO UPDATE
       SET pessoa_id=EXCLUDED.pessoa_id, nome_completo=EXCLUDED.nome_completo,
           telefone=EXCLUDED.telefone, role=EXCLUDED.role, updated_at=NOW();
  EXCEPTION WHEN OTHERS THEN NULL; END;

  BEGIN
    UPDATE public.membros m SET perfil_acesso = v_convite.role::perfil_acesso, updated_at = NOW()
     WHERE m.id = v_pessoa.id;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  UPDATE public.convites_acesso ca SET used_at = NOW() WHERE ca.token = p_token;

  RETURN QUERY SELECT TRUE, NULL::TEXT, v_email_login;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_pastoral_mes(p_ano integer DEFAULT NULL::integer, p_mes integer DEFAULT NULL::integer)
 RETURNS TABLE(tipo text, ref_id text, pessoa_id uuid, familia_id uuid, titulo text, subtitulo text, proxima_data date, anos_vai_completar integer, telefone text, telefone_secundario text, passou boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  WITH alvo AS (
    SELECT 
      COALESCE(p_ano, date_part('year', CURRENT_DATE)::int)  AS ano,
      COALESCE(p_mes, date_part('month', CURRENT_DATE)::int) AS mes
  )
  SELECT 
    v.tipo, v.ref_id, v.pessoa_id, v.familia_id,
    v.titulo, v.subtitulo, 
    make_date(alvo.ano, alvo.mes, LEAST(date_part('day', v.data_origem)::int, 28))::date AS proxima_data,
    -- anos no dia da efeméride neste ano
    (alvo.ano - date_part('year', v.data_origem)::int) AS anos_vai_completar,
    v.telefone, v.telefone_secundario,
    (make_date(alvo.ano, alvo.mes, date_part('day', v.data_origem)::int) < CURRENT_DATE) AS passou
    FROM public.vw_agenda_pastoral v, alvo
   WHERE date_part('month', v.data_origem)::int = alvo.mes
   ORDER BY date_part('day', v.data_origem), v.titulo;
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_pastoral_proximos_dias(p_dias integer DEFAULT 7)
 RETURNS TABLE(tipo text, ref_id text, pessoa_id uuid, familia_id uuid, titulo text, subtitulo text, data_evento date, anos_completar integer, dias_ate_evento integer, telefone text, telefone_secundario text, tipo_pessoa tipo_pessoa)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  with base as (
    select v.tipo, v.ref_id, v.pessoa_id, v.familia_id, v.titulo, v.subtitulo,
           v.data_origem, v.telefone, v.telefone_secundario, v.tipo_pessoa,
           -- Este ano se ainda não passou; senão, o ano que vem.
           case
             when public.proximo_aniversario(v.data_origem) >= current_date
               then public.proximo_aniversario(v.data_origem)
             else public.proximo_aniversario(v.data_origem, date_part('year', current_date)::int + 1)
           end as data_evento
      from public.vw_agenda_pastoral v
  )
  select b.tipo, b.ref_id, b.pessoa_id, b.familia_id, b.titulo, b.subtitulo,
         b.data_evento,
         date_part('year', age(b.data_evento, b.data_origem))::int as anos_completar,
         (b.data_evento - current_date) as dias_ate_evento,
         b.telefone, b.telefone_secundario, b.tipo_pessoa
    from base b
   where b.data_evento between current_date and current_date + p_dias
   order by b.data_evento, b.titulo;
$function$
;

CREATE OR REPLACE FUNCTION public.anonimizar_pessoa(p_pessoa_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_anon TEXT := 'ANONIMIZADO_' || LEFT(p_pessoa_id::TEXT,8);
BEGIN
  IF NOT public.has_role(auth.uid(),'admin') THEN
    RAISE EXCEPTION 'Acesso negado.';
  END IF;
  UPDATE public.pessoas SET
    nome_completo='[ANONIMIZADO]', email=v_anon||'@anonimizado.local',
    telefone=NULL, data_nascimento=NULL, genero=NULL, endereco=NULL, foto_url=NULL
  WHERE id=p_pessoa_id;
  DELETE FROM public.membros_detalhes WHERE pessoa_id=p_pessoa_id;
  UPDATE public.consentimento SET aceito=false, revogado_em=now() WHERE pessoa_id=p_pessoa_id;
  INSERT INTO public.log_auditoria (tabela,registro_id,acao,usuario_id,campos_alt)
  VALUES ('pessoas',p_pessoa_id,'DELETE',auth.uid(),jsonb_build_object('motivo','anonimizacao_lgpd'));
END; $function$
;

CREATE OR REPLACE FUNCTION public.arr_aprovar_reserva(p_reserva_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reserva record; v_template record;
begin
  select * into v_reserva from arr_reservas where id = p_reserva_id;
  if not found then raise exception 'Reserva não encontrada'; end if;
  if v_reserva.status <> 'solicitada' then
    raise exception 'Reserva no estado % não pode ser aprovada', v_reserva.status;
  end if;
  select * into v_template
  from arr_acordo_template
  where ativo and (espaco_id = v_reserva.espaco_id or espaco_id is null)
  order by (espaco_id = v_reserva.espaco_id) desc nulls last, versao desc
  limit 1;
  if not found then raise exception 'Nenhum template de acordo ativo'; end if;
  update arr_reservas
  set status = 'aprovada',
      aprovada_por = auth.uid(), aprovada_em = now(),
      acordo_template_id = v_template.id, acordo_texto = v_template.texto,
      acordo_enviado_em = now(), acordo_enviado_por = auth.uid(),
      updated_at = now()
  where id = p_reserva_id;
  return jsonb_build_object(
    'reserva_id', p_reserva_id,
    'template_id', v_template.id,
    'acordo_texto', v_template.texto
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_categorizar_problema(p_texto text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when p_texto ~* '(l[âa]mpada|luz|tomada|disjuntor|fio|el[ée]tric|fuga|curto)'
      then 'eletrico'
    when p_texto ~* '(torneira|vazamento|encanamento|cano|esgoto|pia|chuveiro|caixa.*d.água|hidr[aá]ulic)'
      then 'hidraulico'
    when p_texto ~* '(geladeira|fog[ãa]o|forno|micro-?ondas|liquidificador|sandwich|cafe?teira|fritadeira|el[ée]tro|equipamento)'
      then 'eletrodomestico'
    when p_texto ~* '(cadeira|mesa|banco|sof[áa]|estante|arm[áa]rio|prateleira|m[óo]vel|m[óo]veis|mobili[áa]rio)'
      then 'mobiliario'
    when p_texto ~* '(suj|lim[pl]|mau ?cheiro|odor|mofo|baixela|talher|pano|lixeira)'
      then 'limpeza'
    when p_texto ~* '(porta|janela|fechadura|chave|tranca|vidro|trinco|ma[çc]aneta)'
      then 'esquadrias'
    when p_texto ~* '(estoque|produto|insumo|falta|esgot|acabou)'
      then 'estoque'
    else 'outros'
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.arr_problemas_resumo()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total_aberto    int;
  v_total_andamento int;
  v_alta            int;
  v_por_categoria   jsonb;
  v_recorrentes     jsonb;
  v_top_espaco      jsonb;
begin
  select
    count(*) filter (where status = 'aberto'),
    count(*) filter (where status = 'em_andamento'),
    count(*) filter (where prioridade = 'alta' and status in ('aberto','em_andamento'))
  into v_total_aberto, v_total_andamento, v_alta
  from arr_problemas_manutencao;

  -- por categoria (só abertos / em andamento)
  select coalesce(jsonb_agg(jsonb_build_object(
    'categoria', categoria, 'qtd', qtd
  ) order by qtd desc), '[]'::jsonb)
  into v_por_categoria
  from (
    select coalesce(categoria, 'outros') as categoria, count(*) as qtd
    from arr_problemas_manutencao
    where status in ('aberto','em_andamento')
    group by 1
  ) t;

  -- recorrentes: mesmo título reportado 2+ vezes nos últimos 180 dias
  select coalesce(jsonb_agg(jsonb_build_object(
    'titulo', titulo, 'qtd', qtd, 'categoria', categoria
  ) order by qtd desc), '[]'::jsonb)
  into v_recorrentes
  from (
    select titulo, max(categoria) as categoria, count(*) as qtd
    from arr_problemas_manutencao
    where reportado_em > now() - interval '180 days'
    group by titulo
    having count(*) >= 2
    order by count(*) desc
    limit 5
  ) t;

  -- espaço com mais problemas em aberto
  select coalesce(jsonb_agg(jsonb_build_object(
    'espaco_id', espaco_id, 'codigo', codigo, 'nome', nome, 'qtd', qtd
  ) order by qtd desc), '[]'::jsonb)
  into v_top_espaco
  from (
    select p.espaco_id, e.codigo, e.nome, count(*) as qtd
    from arr_problemas_manutencao p
    join arr_espacos e on e.id = p.espaco_id
    where p.status in ('aberto','em_andamento')
    group by p.espaco_id, e.codigo, e.nome
    order by count(*) desc
  ) t;

  return jsonb_build_object(
    'total_aberto', v_total_aberto,
    'total_andamento', v_total_andamento,
    'total_alta_prioridade', v_alta,
    'por_categoria', v_por_categoria,
    'recorrentes', v_recorrentes,
    'top_espaco', v_top_espaco
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_produto_check_acervo_campanha()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_existe int;
begin
  -- Só interessa quando o item será visível no PDV.
  if new.codigo is null or new.ativo is not true or new.arquivado_em is not null then
    return new;
  end if;

  if new.reserva_id is null then
    -- ACERVO sendo inserido/ativado: rejeita se houver item de CAMPANHA
    -- ativo no mesmo espaço com o mesmo código.
    select 1 into v_existe
      from public.arr_produtos
     where espaco_id = new.espaco_id
       and codigo = new.codigo
       and reserva_id is not null
       and ativo = true
       and arquivado_em is null
       and id <> new.id
     limit 1;
    if v_existe is not null then
      raise exception
        'Conflito de código: já existe item de CAMPANHA ativo no espaço com código "%". '
        'Inative ou renomeie o item da campanha antes de cadastrar este acervo.',
        new.codigo;
    end if;
  else
    -- CAMPANHA sendo inserida/ativada: rejeita se houver ACERVO ativo no
    -- mesmo espaço com o mesmo código.
    select 1 into v_existe
      from public.arr_produtos
     where espaco_id = new.espaco_id
       and codigo = new.codigo
       and reserva_id is null
       and ativo = true
       and arquivado_em is null
       and id <> new.id
     limit 1;
    if v_existe is not null then
      raise exception
        'Conflito de código: já existe item de ACERVO ativo no espaço com código "%". '
        'Não dá pra reusar esse código na campanha — escolha outro.',
        new.codigo;
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.arr_produto_check_reserva_espaco()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_espaco_reserva uuid;
begin
  if new.reserva_id is null then
    return new;
  end if;
  select espaco_id into v_espaco_reserva
    from public.arr_reservas
   where id = new.reserva_id;
  if v_espaco_reserva is null then
    raise exception 'Reserva % não encontrada', new.reserva_id;
  end if;
  if v_espaco_reserva <> new.espaco_id then
    raise exception
      'Produto vinculado à reserva % deve ter o mesmo espaco_id da reserva (esperado %, recebido %)',
      new.reserva_id, v_espaco_reserva, new.espaco_id;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.arr_produtos_vendaveis(p_reserva_id uuid)
 RETURNS TABLE(id uuid, espaco_id uuid, reserva_id uuid, codigo text, nome text, categoria arr_produto_categoria, subcategoria text, preco_sugerido numeric, estoque_atual integer, estoque_minimo integer, observacao text, is_acervo boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p.id, p.espaco_id, p.reserva_id, p.codigo, p.nome, p.categoria,
         p.subcategoria, p.preco_sugerido, p.estoque_atual, p.estoque_minimo,
         p.observacao,
         (p.reserva_id is null) as is_acervo
    from public.arr_produtos p
    join public.arr_reservas r on r.id = p_reserva_id
   where p.arquivado_em is null
     and p.ativo = true
     and (
       (p.reserva_id is null and p.espaco_id = r.espaco_id)
       or p.reserva_id = p_reserva_id
     )
   order by is_acervo desc, p.nome;
$function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_caixa_arquivar_cascata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.arquivado_em is null and new.arquivado_em is not null then
    update arr_vendas
    set arquivado_em = new.arquivado_em
    where caixa_id = new.id and arquivado_em is null;
    update arr_movimentos
    set arquivado_em = new.arquivado_em
    where caixa_id = new.id and arquivado_em is null;
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_item_venda_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_estoque int;
begin
  if new.produto_id is null then return new; end if;
  select estoque_atual into v_estoque
  from arr_produtos where id = new.produto_id for update;
  if v_estoque is null then return new; end if;       -- produto sem controle de estoque
  if v_estoque < new.qtd then
    raise exception 'Estoque insuficiente para %: disponível %, pedido %',
      new.descricao, v_estoque, new.qtd;
  end if;
  update arr_produtos
  set estoque_atual = estoque_atual - new.qtd::int
  where id = new.produto_id;
  insert into arr_estoque_movimentos (
    produto_id, tipo, qtd, motivo, ref_tipo, ref_id, registrado_por
  ) values (
    new.produto_id, 'venda', -new.qtd::int,
    'Venda registrada', 'arr_vendas', new.venda_id, auth.uid()
  );
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_movimento_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_evento  text;
  v_pessoa  uuid;
  v_payload jsonb;
begin
  v_evento := case tg_op
    when 'INSERT' then 'arr_movimento_criado'
    when 'UPDATE' then case
      when old.arquivado_em is null and new.arquivado_em is not null
        then 'arr_movimento_arquivado'
      else 'arr_movimento_atualizado'
    end
    when 'DELETE' then 'arr_movimento_excluido'
  end;
  v_pessoa := case tg_op when 'DELETE' then old.beneficiario_membro_id
                          else new.beneficiario_membro_id end;
  v_payload := jsonb_build_object(
    'caixa_id',          coalesce(new.caixa_id, old.caixa_id),
    'tipo',              coalesce(new.tipo, old.tipo),
    'valor',             coalesce(new.valor, old.valor),
    'nf_numero',         coalesce(new.nf_numero, old.nf_numero),
    'fin_lancamento_id', coalesce(new.fin_lancamento_id, old.fin_lancamento_id)
  );
  -- Insert na estrutura REAL de audit_logs:
  --   acao         (era 'tipo_evento' na Fase 1)
  --   data         (timestamp do evento — preenchemos explicitamente)
  --   pessoa_id, user_id, executado_por, detalhes — mesmos nomes
  insert into public.audit_logs (
    acao, pessoa_id, user_id, executado_por, detalhes, data
  ) values (
    v_evento, v_pessoa, null, auth.uid(), v_payload, now()
  );
  return coalesce(new, old);
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_movimento_valida_saldo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saldo numeric;
  v_efeito numeric;
begin
  -- Advisory lock transacional por caixa: serializa concorrentes do mesmo caixa
  -- até o commit da transação atual. NÃO depende de nível de isolação.
  -- Diferente do FOR UPDATE em arr_caixas, este lock cobre uma chave LÓGICA
  -- (o caixa_id) e força a segunda transação a esperar — a leitura da view
  -- arr_caixa_resumo após o lock já enxerga o efeito da primeira (post-commit).
  perform pg_advisory_xact_lock(hashtextextended(new.caixa_id::text, 0));

  -- Saldo derivado via view, sob proteção do advisory lock
  select saldo_virtual into v_saldo
  from arr_caixa_resumo where caixa_id = new.caixa_id;

  if v_saldo is null then v_saldo := 0; end if;

  -- Efeito do novo movimento (tipos não-ajuste sempre subtraem)
  v_efeito := case new.tipo
    when 'ajuste' then case when new.ajuste_positivo then new.valor else -new.valor end
    else -new.valor
  end;

  if (v_saldo + v_efeito) < 0 then
    raise exception 'Saldo virtual ficaria negativo: atual %, efeito %, final %',
      v_saldo, v_efeito, (v_saldo + v_efeito)
      using hint = 'A área não pode reembolsar/reverter mais do que arrecadou.';
  end if;

  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_problema_para_manutencao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_espaco_id  uuid;
  v_titulo     text;
  v_categoria  text;
  v_prioridade text;
begin
  if not new.problema_reportado then return new; end if;
  if (tg_op = 'UPDATE' and old.problema_reportado = true) then
    return new;
  end if;
  select r.espaco_id into v_espaco_id
  from arr_reservas r where r.id = new.reserva_id;
  v_titulo := coalesce(nullif(trim(new.observacao), ''), new.item);
  v_categoria := public.arr_categorizar_problema(v_titulo || ' ' || coalesce(new.observacao,''));
  -- prioridade: hidraulico e eletrico = alta (perigo); outros = media
  v_prioridade := case
    when v_categoria in ('eletrico','hidraulico') then 'alta'
    else 'media'
  end;
  insert into public.arr_problemas_manutencao (
    reserva_id, reserva_checklist_id, espaco_id,
    titulo, descricao, categoria, prioridade,
    reportado_por
  ) values (
    new.reserva_id, new.id, v_espaco_id,
    v_titulo, new.observacao, v_categoria, v_prioridade,
    auth.uid()
  );
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_reembolso_gera_lancamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conta_cnpj uuid;
  v_centro     uuid;
  v_lanc_id    uuid;
  v_descricao  text;
begin
  if new.tipo <> 'reembolso_pessoa' then return new; end if;
  if new.fin_lancamento_id is not null then return new; end if;   -- já preenchido

  -- Conta CNPJ principal (única, garantida pelo unique index)
  select id into v_conta_cnpj from fin_contas where is_principal = true limit 1;
  if v_conta_cnpj is null then
    raise exception 'Nenhuma fin_contas com is_principal=true. '
      'Defina a conta CNPJ antes de registrar reembolsos.';
  end if;

  -- Centro de custo da reserva via caixa
  select r.centro_custo_id into v_centro
  from arr_caixas c join arr_reservas r on r.id = c.reserva_id
  where c.id = new.caixa_id;

  v_descricao := format('Reembolso a pessoa — %s (NF %s)',
    coalesce(new.descricao, ''), new.nf_numero);

  insert into fin_lancamentos (
    tipo, status, valor, descricao,
    data_competencia, data_vencimento, data_pagamento,
    conta_id, centro_custo_id, origem
  ) values (
    'saida', 'realizado', new.valor, v_descricao,
    new.data_movimento, new.data_movimento, new.data_movimento,
    v_conta_cnpj, v_centro, 'arrecadacao_reembolso'
  ) returning id into v_lanc_id;

  new.fin_lancamento_id := v_lanc_id;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_reserva_arquivar_cascata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.arquivado_em is null and new.arquivado_em is not null then
    -- Reserva agora arquivada — propagar
    update arr_caixas
    set arquivado_em = new.arquivado_em
    where reserva_id = new.id and arquivado_em is null;
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_valida_abate_cnpj()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existe_lanc boolean;
  v_ja_vinculado uuid;
  v_tipo text;
begin
  -- Garante que o fin_lancamentos referenciado existe E é saída
  select exists(select 1 from fin_lancamentos where id = new.fin_lancamento_id),
         coalesce((select tipo from fin_lancamentos where id = new.fin_lancamento_id), '')
  into v_existe_lanc, v_tipo;

  if not v_existe_lanc then
    raise exception 'fin_lancamento_id % não existe', new.fin_lancamento_id;
  end if;
  if v_tipo <> 'saida' then
    raise exception 'abate_compra_cnpj precisa apontar para fin_lancamentos.tipo=saida (atual: %)', v_tipo;
  end if;

  -- Idempotência: o mesmo lançamento não pode ser abatido por 2 movimentos
  select id into v_ja_vinculado
  from arr_movimentos
  where fin_lancamento_id = new.fin_lancamento_id
    and arquivado_em is null
    and id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid);
  if v_ja_vinculado is not null then
    raise exception 'fin_lancamento_id % já está vinculado ao movimento %',
      new.fin_lancamento_id, v_ja_vinculado;
  end if;

  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_validar_fechamento_caixa()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total      int;
  v_ok         int;
  v_reserva_id uuid;
begin
  -- Só age quando o estado MUDA pra 'fechado'
  if new.estado is distinct from 'fechado' or old.estado = 'fechado' then
    return new;
  end if;
  -- Estado anterior tem que ser conciliando (já era um check existente)
  if old.estado <> 'conciliando' then
    -- Será barrado pelo check arr_caixas_estado_coerente. Aqui só passa adiante.
    return new;
  end if;

  v_reserva_id := new.reserva_id;
  select
    count(*) filter (where obrigatorio),
    count(*) filter (where obrigatorio and ok)
  into v_total, v_ok
  from arr_reserva_checklist
  where reserva_id = v_reserva_id;

  if v_total > 0 and v_ok < v_total then
    raise exception 'Checklist incompleto: % de % itens obrigatórios marcados. '
                    'Marque tudo antes de fechar o caixa.', v_ok, v_total
      using errcode = 'check_violation',
            hint    = 'Itens não-obrigatórios podem ficar sem marcar.';
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_venda_estorno_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
begin
  if old.cancelada = false and new.cancelada = true then
    -- Para cada item da venda com produto que controla estoque, devolver
    for r in
      select i.produto_id, i.qtd
      from arr_itens_venda i
      join arr_produtos p on p.id = i.produto_id
      where i.venda_id = new.id and p.estoque_atual is not null
    loop
      update arr_produtos
      set estoque_atual = coalesce(estoque_atual, 0) + r.qtd::int
      where id = r.produto_id;
      insert into arr_estoque_movimentos (
        produto_id, tipo, qtd, motivo, ref_tipo, ref_id, registrado_por
      ) values (
        r.produto_id, 'ajuste', r.qtd::int,
        format('Estorno por cancelamento da venda %s', new.id),
        'arr_vendas', new.id, auth.uid()
      );
    end loop;
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.arr_trg_venda_valida_cancelamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_estado public.arr_caixa_estado;
  v_saldo  numeric;
begin
  -- AMARRA 2: cancelamento é IRREVERSÍVEL. Reabertura proibida.
  if old.cancelada = true and new.cancelada <> true then
    raise exception 'Venda cancelada não pode ser revertida por UPDATE. '
                    'Corrija lançando uma nova venda.'
      using errcode = 'check_violation';
  end if;

  -- Se não há transição false → true, nada a validar aqui.
  if not (old.cancelada = false and new.cancelada = true) then
    return new;
  end if;

  -- REGRA (b): caixa precisa estar ABERTO. Conciliação/fechamento bloqueia
  -- cancelamento para preservar consistência com relatórios distribuídos.
  select estado into v_estado
  from arr_caixas where id = new.caixa_id;

  if v_estado is distinct from 'aberto' then
    raise exception 'Venda só pode ser cancelada com o caixa ABERTO. '
                    'Use arr_movimentos tipo ajuste para corrigir após conciliação.'
      using hint = 'Estado atual do caixa: ' || coalesce(v_estado::text, 'NULL');
  end if;

  -- Advisory lock IDÊNTICO ao da trg_arr_mov_valida_saldo
  -- (mesma expressão garante exclusão mútua entre cancelamento e movimento)
  perform pg_advisory_xact_lock(hashtextextended(new.caixa_id::text, 0));

  -- REGRA (a): cancelar não pode deixar saldo virtual < 0.
  -- A view arr_caixa_resumo ainda enxerga esta venda como ativa (UPDATE BEFORE),
  -- então o efeito do cancelamento é subtrair valor_total - taxa correspondente.
  -- Como a fórmula da view já desconta taxa por forma de pagamento, basta
  -- recalcular o saldo APÓS hipoteticamente excluir esta venda do bruto:
  --   saldo_pos = saldo_atual - valor_total_da_venda + taxa_dessa_venda
  -- Implementação simples e correta: lê saldo atual, subtrai apenas a parte
  -- líquida (bruto - taxa) que essa venda contribuiu.
  select saldo_virtual into v_saldo
  from arr_caixa_resumo where caixa_id = new.caixa_id;
  if v_saldo is null then v_saldo := 0; end if;

  declare
    v_taxa_pct numeric;
    v_liquido_da_venda numeric;
  begin
    select case new.forma_pagamento
             when 'debito'  then c.taxa_debito_pct
             when 'credito' then c.taxa_credito_pct
             when 'pix'     then c.taxa_pix_pct
             else 0
           end
      into v_taxa_pct
      from arr_caixas c where c.id = new.caixa_id;
    v_liquido_da_venda := new.valor_total - round(new.valor_total * coalesce(v_taxa_pct,0) / 100, 2);

    if (v_saldo - v_liquido_da_venda) < 0 then
      raise exception 'Cancelamento deixaria o saldo virtual negativo: '
                      'saldo atual %, líquido da venda %, saldo final %.',
                      v_saldo, v_liquido_da_venda, (v_saldo - v_liquido_da_venda)
        using hint = 'Estorne primeiro os reembolsos vinculados antes de cancelar.';
    end if;
  end;

  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.assuntos_alertas()
 RETURNS TABLE(prioridade prioridade_alerta, tipo text, titulo text, descricao text, acao_sugerida text, link text, entidade_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  -- 1) URGENTE: atrasados
  select 'urgente'::prioridade_alerta, 'atrasado',
         titulo,
         'Atrasado há ' || (current_date - prazo) || ' dia(s)' ||
         case when responsavel_nome is not null then ' · Resp: ' || responsavel_nome else '' end,
         'Ver assunto',
         '/assunto/' || id::text, id
  from public.vw_assuntos_dashboard
  where situacao = 'atrasado' and status not in ('concluido','cancelado')

  union all

  -- 2) ATENÇÃO: vence em ≤ 3 dias
  select 'atencao'::prioridade_alerta, 'vence_breve',
         titulo,
         'Vence em ' || dias_para_prazo || ' dia(s)' ||
         case when responsavel_nome is not null then ' · Resp: ' || responsavel_nome else '' end,
         'Ver assunto',
         '/assunto/' || id::text, id
  from public.vw_assuntos_dashboard
  where situacao = 'vence_em_breve' and status not in ('concluido','cancelado')

  union all

  -- 3) INFO: assuntos parados há 7+ dias
  select 'informativo'::prioridade_alerta, 'parado',
         titulo,
         'Sem atualização há ' || (current_date - ultima_atualizacao_em::date) || ' dias',
         'Atualizar',
         '/assunto/' || id::text, id
  from public.vw_assuntos_dashboard
  where situacao = 'parado' and status = 'aberto'

  union all

  -- 4) INFO: gargalo — discutido 3+ vezes sem conclusão
  select 'informativo'::prioridade_alerta, 'gargalo',
         titulo,
         'Discutido ' || vezes_discutido || 'x sem conclusão',
         'Ver assunto',
         '/assunto/' || id::text, id
  from public.vw_assuntos_dashboard
  where vezes_discutido >= 3 and status in ('aberto','em_andamento')

  order by 1;
$function$
;

CREATE OR REPLACE FUNCTION public.assuntos_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    perform registrar_audit_log(
      'assuntos',
      new.id::text,
      'create',
      jsonb_build_object('titulo', new.titulo, 'prioridade', new.prioridade, 'responsavel', new.responsavel_nome)
    );
    return new;
  elsif tg_op = 'UPDATE' then
    -- só registra se mudou algo relevante
    if (old.status is distinct from new.status)
       or (old.responsavel_id is distinct from new.responsavel_id)
       or (old.prazo is distinct from new.prazo)
       or (old.prioridade is distinct from new.prioridade) then
      perform registrar_audit_log(
        'assuntos',
        new.id::text,
        case
          when old.status = 'aberto' and new.status = 'concluido' then 'concluir'
          when old.status is distinct from new.status then 'mudar_status'
          else 'atualizar'
        end,
        jsonb_build_object(
          'titulo', new.titulo,
          'status_antes', old.status, 'status_depois', new.status,
          'responsavel', new.responsavel_nome
        )
      );
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    perform registrar_audit_log(
      'assuntos',
      old.id::text,
      'excluir',
      jsonb_build_object('titulo', old.titulo)
    );
    return old;
  end if;
  return null;
end; $function$
;

CREATE OR REPLACE FUNCTION public.assuntos_meus_resumo()
 RETURNS TABLE(total_abertos integer, total_atrasados integer, total_vence_breve integer, total_parados integer, proximos jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_pessoa_id uuid;
begin
  -- Descobre a pessoa vinculada ao usuário autenticado
  select pessoa_id into v_pessoa_id
  from profiles
  where id = auth.uid();

  if v_pessoa_id is null then
    return query select 0, 0, 0, 0, '[]'::jsonb;
    return;
  end if;

  return query
  with meus as (
    select * from assuntos
    where responsavel_id = v_pessoa_id
      and status in ('aberto','em_andamento','aguardando_terceiro')
  ),
  classificados as (
    select
      a.*,
      case
        when a.prazo is not null and a.prazo < current_date then 'atrasado'
        when a.prazo is not null and a.prazo <= current_date + 3 then 'vence_breve'
        when coalesce(a.ultima_atualizacao_em, a.data_criacao) < now() - interval '14 days' then 'parado'
        else 'normal'
      end as situacao
    from meus a
  )
  select
    (select count(*)::int from meus),
    (select count(*)::int from classificados where situacao = 'atrasado'),
    (select count(*)::int from classificados where situacao = 'vence_breve'),
    (select count(*)::int from classificados where situacao = 'parado'),
    coalesce(
      (select jsonb_agg(jsonb_build_object(
          'id', c.id,
          'titulo', c.titulo,
          'prazo', c.prazo,
          'prioridade', c.prioridade,
          'situacao', c.situacao
        ) order by
          case c.situacao
            when 'atrasado' then 1
            when 'vence_breve' then 2
            when 'parado' then 3
            else 4
          end,
          c.prazo nulls last
       )
       from (select * from classificados limit 5) c),
      '[]'::jsonb
    );
end; $function$
;

CREATE OR REPLACE FUNCTION public.assuntos_para_reuniao(p_reuniao_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int := 0;
  v_assunto record;
begin
  -- Pega assuntos abertos/em_andamento NÃO vinculados a esta reunião
  for v_assunto in
    select a.id from public.assuntos a
    where a.status in ('aberto','em_andamento','aguardando_terceiro')
      and not exists (
        select 1 from public.reuniao_assuntos ra
        where ra.reuniao_id = p_reuniao_id and ra.assunto_id = a.id
      )
    order by
      case a.prioridade when 'alta' then 1 when 'media' then 2 else 3 end,
      coalesce(a.prazo, '2099-01-01'::date) asc,
      a.created_at asc
  loop
    insert into public.reuniao_assuntos(reuniao_id, assunto_id)
    values (p_reuniao_id, v_assunto.id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;$function$
;

CREATE OR REPLACE FUNCTION public.assuntos_por_responsavel()
 RETURNS TABLE(responsavel_id uuid, responsavel_nome text, total_abertos integer, atrasados integer, proximos integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    responsavel_id,
    responsavel_nome,
    count(*)::int as total,
    count(*) filter (where situacao = 'atrasado')::int as atrasados,
    count(*) filter (where situacao = 'vence_em_breve')::int as proximos
  from public.vw_assuntos_dashboard
  where responsavel_id is not null
    and status not in ('concluido','cancelado')
  group by responsavel_id, responsavel_nome
  order by atrasados desc, total desc;
$function$
;

CREATE OR REPLACE FUNCTION public.assuntos_urgentes_igreja()
 RETURNS TABLE(total_atrasados integer, total_vence_semana integer, lista jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
begin
  return query
  with classificados as (
    select
      a.*,
      case
        when a.prazo is not null and a.prazo < current_date then 'atrasado'
        when a.prazo is not null and a.prazo <= current_date + 7 then 'vence_semana'
        else null
      end as situacao
    from assuntos a
    where status in ('aberto','em_andamento','aguardando_terceiro')
  ),
  urgentes as (
    select * from classificados where situacao is not null
  )
  select
    (select count(*)::int from urgentes where situacao = 'atrasado'),
    (select count(*)::int from urgentes where situacao = 'vence_semana'),
    coalesce(
      (select jsonb_agg(jsonb_build_object(
          'id', u.id,
          'titulo', u.titulo,
          'prazo', u.prazo,
          'prioridade', u.prioridade,
          'situacao', u.situacao,
          'responsavel_id', u.responsavel_id,
          'responsavel_nome', u.responsavel_nome
        ) order by
          case u.situacao when 'atrasado' then 1 else 2 end,
          u.prazo nulls last
       )
       from (select * from urgentes limit 10) u),
      '[]'::jsonb
    );
end; $function$
;

CREATE OR REPLACE FUNCTION public.autocomplete_instituicoes(p_busca text)
 RETURNS TABLE(id uuid, nome text, sigla text, site_oficial text, tipo_instituicao text, permite_integracao boolean, oficial boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT i.id, i.nome, i.sigla, i.site_oficial,
         i.tipo_instituicao, i.permite_integracao, i.oficial
  FROM public.instituicoes i
  WHERE i.ativo = true
    AND (lower(i.nome)  ILIKE '%' || lower(p_busca) || '%'
      OR lower(COALESCE(i.sigla,'')) ILIKE '%' || lower(p_busca) || '%')
  ORDER BY i.oficial DESC, i.nome
  LIMIT 8;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.baixar_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE pdv_estoque
  SET quantidade = quantidade - NEW.quantidade
  WHERE produto_id = NEW.produto_id;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_estrutura_documento(p_nome text, p_tipo text DEFAULT NULL::text, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_result JSONB;
BEGIN
  IF length(trim(p_nome)) < 2 THEN RETURN '[]'::JSONB; END IF;
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', id, 'tipo', tipo, 'nome', nome,
      'descricao', descricao, 'responsabilidades', responsabilidades,
      'base_institucional', base_institucional,
      'referencia_documento', referencia_documento, 'nivel', nivel
    )
    ORDER BY CASE WHEN nome ILIKE trim(p_nome) || '%' THEN 0 ELSE 1 END, ordem, nome
  )
  INTO v_result
  FROM (
    SELECT * FROM public.documento_estrutura
    WHERE ativo = true
      AND nome ILIKE '%' || trim(p_nome) || '%'
      AND (p_tipo IS NULL OR tipo = p_tipo)
    LIMIT p_limit
  ) sub;
  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_instituicao_similar(p_nome text, p_site text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, nome text, sigla text, site_oficial text, tipo_instituicao text, permite_integracao boolean, oficial boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT i.id, i.nome, i.sigla, i.site_oficial,
         i.tipo_instituicao, i.permite_integracao, i.oficial
  FROM public.instituicoes i
  WHERE i.ativo = true
    AND (
      (p_site IS NOT NULL AND p_site <> ''
        AND lower(rtrim(i.site_oficial,'/')::TEXT) = lower(rtrim(p_site,'/')))
      OR (p_nome IS NOT NULL AND p_nome <> ''
        AND similarity(lower(i.nome), lower(p_nome)) > 0.5)
    )
  ORDER BY i.oficial DESC, similarity(lower(i.nome), lower(p_nome)) DESC
  LIMIT 5;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_modelo_ministerio(p_nome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_de     RECORD;
  v_modelo RECORD;
BEGIN
  SELECT nome, descricao, responsabilidades, base_institucional, referencia_documento
  INTO v_de
  FROM public.documento_estrutura
  WHERE ativo = true AND tipo = 'ministerio'
    AND nome ILIKE '%' || trim(p_nome) || '%'
  ORDER BY CASE WHEN nome ILIKE trim(p_nome) || '%' THEN 0 ELSE 1 END, nome
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'encontrado', true, 'origem', 'documento',
      'nome', v_de.nome, 'descricao', v_de.descricao,
      'responsabilidades', v_de.responsabilidades,
      'base_institucional', v_de.base_institucional,
      'referencia_documento', v_de.referencia_documento
    );
  END IF;

  SELECT nome, descricao, responsabilidades INTO v_modelo
  FROM public.modelos_ministerio
  WHERE nome ILIKE '%' || trim(p_nome) || '%'
  ORDER BY CASE WHEN nome ILIKE trim(p_nome) || '%' THEN 0 ELSE 1 END, nome
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'encontrado', true, 'origem', 'modelo',
      'nome', v_modelo.nome, 'descricao', v_modelo.descricao,
      'responsabilidades', v_modelo.responsabilidades
    );
  END IF;

  RETURN jsonb_build_object('encontrado', false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_secoes_por_tag(p_tag text)
 RETURNS TABLE(secao_id uuid, documento_id uuid, secao_titulo text, secao_conteudo text, documento_tipo text, documento_titulo text, tags text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT s.id, s.documento_id, s.titulo, s.conteudo, d.tipo, d.titulo, s.tags_conceituais
  FROM public.secoes_documento s
  JOIN public.documentos d ON d.id = s.documento_id
  WHERE s.tags_conceituais @> ARRAY[lower(p_tag)] AND d.vigente = true
  ORDER BY d.tipo, s.ordem;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_score_engajamento(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_score INTEGER := 1;
  v_visitas INTEGER;
  v_tipo TEXT;
BEGIN
  SELECT numero_visitas, tipo_pessoa
  INTO v_visitas, v_tipo
  FROM membros
  WHERE id = p_id;

  IF v_visitas >= 2 THEN
    v_score := v_score + 2;
  END IF;

  IF v_tipo IN ('congregado', 'membro') THEN
    v_score := v_score + 5;
  END IF;

  RETURN v_score;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cash_dist(money, money)
 RETURNS money
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/btree_gist', $function$cash_dist$function$
;

CREATE OR REPLACE FUNCTION public.criar_convite_acesso(p_pessoa_id uuid, p_role app_role)
 RETURNS TABLE(token uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  caller_role TEXT;
  v_token     UUID;
  v_expires   TIMESTAMPTZ;
BEGIN
  SELECT pr.role::text INTO caller_role FROM profiles pr WHERE pr.id = auth.uid();
  IF caller_role NOT IN ('admin','secretaria') THEN
    RAISE EXCEPTION 'Apenas admin e secretaria podem criar convites.';
  END IF;

  -- Invalida convites anteriores não usados desta pessoa
  UPDATE convites_acesso
     SET used_at = now()
   WHERE pessoa_id = p_pessoa_id
     AND tipo = 'primeiro_acesso'
     AND used_at IS NULL;

  v_expires := now() + INTERVAL '7 days';

  INSERT INTO convites_acesso (tipo, pessoa_id, role, expires_at, created_by)
  VALUES ('primeiro_acesso', p_pessoa_id, p_role, v_expires, auth.uid())
  RETURNING convites_acesso.token INTO v_token;

  RETURN QUERY SELECT v_token, v_expires;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.current_user_role()
 RETURNS app_role
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select role from public.profiles where id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.dashboard_ministerios(p_igreja_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
DECLARE
  v_resultado JSONB;
  v_mes_ini   DATE := date_trunc('month', CURRENT_DATE)::DATE;
  v_mes_fim   DATE := (date_trunc('month', CURRENT_DATE) + interval '1 month - 1 day')::DATE;
BEGIN
  SELECT jsonb_build_object(
    'ministerios', jsonb_build_object(
      'total',  (SELECT count(*) FROM ministerios WHERE ativo = true),
      'lista',  (SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'cor',cor_identidade,'icone',icone))
                 FROM ministerios WHERE ativo = true)
    ),
    'voluntarios', jsonb_build_object(
      'total_ativos',       (SELECT count(DISTINCT membro_id) FROM area_voluntarios WHERE status = 'ativo' AND data_fim IS NULL),
      'sem_escala_mes',     (SELECT count(DISTINCT av.membro_id)
                             FROM area_voluntarios av
                             WHERE av.status = 'ativo' AND av.data_fim IS NULL
                               AND av.membro_id NOT IN (
                                 SELECT DISTINCT ev.pessoa_id FROM escala_voluntarios ev
                                 JOIN escalas e ON e.id = ev.escala_id
                                 WHERE e.data_evento BETWEEN v_mes_ini AND v_mes_fim
                               )),
      'sobrecarregados',    (SELECT count(*) FROM perfil_servico WHERE nivel_sobrecarga >= 7 AND ativo = true),
      'em_descanso',        (SELECT count(*) FROM perfil_servico WHERE em_descanso = true AND ativo = true)
    ),
    'escalas_mes', jsonb_build_object(
      'total',      (SELECT count(*) FROM escalas WHERE data_evento BETWEEN v_mes_ini AND v_mes_fim),
      'planejadas', (SELECT count(*) FROM escalas WHERE data_evento BETWEEN v_mes_ini AND v_mes_fim AND status = 'planejada'),
      'confirmadas',(SELECT count(*) FROM escalas WHERE data_evento BETWEEN v_mes_ini AND v_mes_fim AND status = 'confirmada'),
      'realizadas', (SELECT count(*) FROM escalas WHERE data_evento BETWEEN v_mes_ini AND v_mes_fim AND status = 'realizada')
    ),
    'alertas', jsonb_build_object(
      'sobrecarregados', (SELECT jsonb_agg(jsonb_build_object(
          'nome', m.nome_completo,
          'carga', ps.carga_atual_mes,
          'sobrecarga', ps.nivel_sobrecarga
        ))
        FROM perfil_servico ps
        JOIN membros m ON m.id = ps.pessoa_id
        WHERE ps.nivel_sobrecarga >= 7 AND ps.ativo = true
        LIMIT 5
      ),
      'areas_sem_lider', (SELECT jsonb_agg(jsonb_build_object('id',a.id,'nome',a.nome))
        FROM areas a
        WHERE a.ativo = true
          AND NOT EXISTS (SELECT 1 FROM liderancas l WHERE l.tipo = 'area' AND l.referencia_id = a.id AND l.ativo = true)
        LIMIT 10
      ),
      'areas_sem_voluntarios', (SELECT jsonb_agg(jsonb_build_object('id',a.id,'nome',a.nome))
        FROM areas a
        WHERE a.ativo = true
          AND (SELECT count(*) FROM area_voluntarios av WHERE av.area_id = a.id AND av.status = 'ativo' AND av.data_fim IS NULL) = 0
        LIMIT 10
      )
    ),
    'gerado_em', now()
  ) INTO v_resultado;

  RETURN v_resultado;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.date_dist(date, date)
 RETURNS integer
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/btree_gist', $function$date_dist$function$
;

CREATE OR REPLACE FUNCTION public.definir_perfil(p_user_id uuid, p_role app_role)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nome    text;
  v_atual   text;
  v_admins  int;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Apenas a administração pode alterar perfis.';
  END IF;

  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode alterar o próprio perfil. Peça a outra pessoa da administração.';
  END IF;

  SELECT COALESCE(NULLIF(btrim(p.nome), ''), 'esta conta') INTO v_nome
    FROM public.profiles p WHERE p.id = p_user_id;
  IF v_nome IS NULL THEN
    RAISE EXCEPTION 'Conta não encontrada.';
  END IF;

  SELECT string_agg(role::text, ', ') INTO v_atual
    FROM public.user_roles WHERE user_id = p_user_id;

  -- Rebaixar o último administrador deixaria a igreja sem ninguém capaz de
  -- promover outro — e esta função é a única porta para promover.
  IF p_role <> 'admin'::app_role
     AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = p_user_id AND role = 'admin')
  THEN
    SELECT count(*) INTO v_admins FROM public.user_roles WHERE role = 'admin';
    IF v_admins <= 1 THEN
      RAISE EXCEPTION 'Este é o único administrador. Promova outra pessoa antes de rebaixar este perfil.';
    END IF;
  END IF;

  DELETE FROM public.user_roles WHERE user_id = p_user_id;
  INSERT INTO public.user_roles (user_id, role) VALUES (p_user_id, p_role);

  RETURN v_nome || ' agora é ' ||
         CASE p_role
           WHEN 'admin'      THEN 'Administrador'
           WHEN 'secretaria' THEN 'Secretaria'
           WHEN 'pastor'     THEN 'Pastor'
           WHEN 'diakonia'   THEN 'Pastor'
           WHEN 'lideranca'  THEN 'Liderança'
           WHEN 'voluntario' THEN 'Voluntário'
           ELSE p_role::text
         END ||
         COALESCE(' (era ' || v_atual || ')', ' (não tinha perfil)') || '.';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.domingo_da_semana(p_data date)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT (p_data - (EXTRACT(DOW FROM p_data)::int) * INTERVAL '1 day')::date;
$function$
;

CREATE OR REPLACE FUNCTION public.ebd_chamada_view(p_aula_id uuid)
 RETURNS TABLE(pessoa_id uuid, nome_completo text, idade integer, presente boolean, eh_visitante boolean, tipo text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  WITH aula AS (
    SELECT * FROM public.ebd_aulas WHERE id = p_aula_id
  )
  -- Matriculados ativos da classe
  SELECT m.id, m.nome_completo,
         CASE WHEN m.data_nascimento IS NOT NULL
              THEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, m.data_nascimento))::int
              ELSE NULL END AS idade,
         COALESCE(ep.presente, false) AS presente,
         false AS eh_visitante,
         'matriculado'::text AS tipo
    FROM aula a
    JOIN public.ebd_matriculas em ON em.classe_id = a.classe_id AND em.ativo
    JOIN public.membros m ON m.id = em.pessoa_id
    LEFT JOIN public.ebd_presencas ep ON ep.aula_id = a.id AND ep.pessoa_id = m.id
   WHERE m.status = 'ativo'
 
  UNION ALL
 
  -- Visitantes marcados nesta aula
  SELECT m.id, m.nome_completo,
         CASE WHEN m.data_nascimento IS NOT NULL
              THEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, m.data_nascimento))::int
              ELSE NULL END AS idade,
         ep.presente,
         true AS eh_visitante,
         'visitante'::text AS tipo
    FROM public.ebd_presencas ep
    JOIN public.membros m ON m.id = ep.pessoa_id
   WHERE ep.aula_id = p_aula_id AND ep.eh_visitante = true
   ORDER BY 6, 2;  -- tipo, depois nome
$function$
;

CREATE OR REPLACE FUNCTION public.ebd_classes_baixa_presenca()
 RETURNS TABLE(classe_id uuid, classe_nome text, qtd_aulas_recentes integer, taxa_media numeric, total_matriculados integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  WITH 
  ultimas_aulas AS (
    SELECT a.id, a.classe_id, a.data,
           ROW_NUMBER() OVER (PARTITION BY a.classe_id ORDER BY a.data DESC) AS rn
      FROM public.ebd_aulas a
     WHERE a.data <= CURRENT_DATE
  ),
  recentes AS (
    SELECT * FROM ultimas_aulas WHERE rn <= 4
  ),
  matric AS (
    SELECT classe_id, COUNT(*)::int AS qtd 
      FROM public.ebd_matriculas WHERE ativo = true GROUP BY classe_id
  ),
  presenca_por_aula AS (
    SELECT r.classe_id, r.id AS aula_id, m.qtd AS matriculados,
           (SELECT COUNT(*)::int FROM public.ebd_presencas ep 
             WHERE ep.aula_id = r.id AND ep.presente = true) AS presentes
      FROM recentes r
      JOIN matric m ON m.classe_id = r.classe_id
  )
  SELECT 
    p.classe_id,
    c.nome,
    COUNT(*)::int AS qtd_aulas_recentes,
    ROUND(AVG(100.0 * p.presentes / NULLIF(p.matriculados, 0)), 1) AS taxa_media,
    MAX(p.matriculados)
  FROM presenca_por_aula p
  JOIN public.ebd_classes c ON c.id = p.classe_id AND c.ativo = true
  GROUP BY p.classe_id, c.nome
  HAVING ROUND(AVG(100.0 * p.presentes / NULLIF(p.matriculados, 0)), 1) < 60
     AND COUNT(*) >= 2  -- precisa de ao menos 2 aulas pra ser representativo
  ORDER BY taxa_media ASC
  LIMIT 10;
$function$
;

CREATE OR REPLACE FUNCTION public.ebd_marcar_presenca(p_aula_id uuid, p_pessoa_id uuid, p_presente boolean, p_eh_visitante boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.ebd_presencas (aula_id, pessoa_id, presente, eh_visitante, registrado_por)
  VALUES (p_aula_id, p_pessoa_id, p_presente, p_eh_visitante, auth.uid())
  ON CONFLICT (aula_id, pessoa_id) DO UPDATE
     SET presente       = EXCLUDED.presente,
         eh_visitante   = EXCLUDED.eh_visitante,
         registrado_por = EXCLUDED.registrado_por
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ebd_obter_ou_criar_aula(p_classe_id uuid, p_data date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  SELECT id INTO v_id 
    FROM public.ebd_aulas 
   WHERE classe_id = p_classe_id AND data = p_data;
  IF v_id IS NULL THEN
    INSERT INTO public.ebd_aulas (classe_id, data, created_by)
         VALUES (p_classe_id, p_data, auth.uid())
         RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.esperados_da_classe(p_classe_id uuid)
 RETURNS TABLE(pessoa_id uuid, nome_completo text, sexo text, data_nascimento date, idade integer, ja_matriculado boolean, matricula_id uuid, outra_classe_id uuid, outra_classe_nome text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  WITH c AS (
    SELECT * FROM public.ebd_classes WHERE id = p_classe_id
  ),
  outras_mat AS (
    -- Para cada pessoa, qual classe ela est- hoje (se nao for a atual)
    SELECT em.pessoa_id, em.classe_id, em.id AS matricula_id, cl.nome AS classe_nome
      FROM public.ebd_matriculas em
      JOIN public.ebd_classes cl ON cl.id = em.classe_id
     WHERE em.ativo = true
  )
  SELECT m.id AS pessoa_id,
         m.nome_completo,
         m.sexo::text,
         m.data_nascimento,
         EXTRACT(YEAR FROM AGE(CURRENT_DATE, m.data_nascimento))::int AS idade,
         (om.classe_id = p_classe_id) AS ja_matriculado,
         CASE WHEN om.classe_id = p_classe_id THEN om.matricula_id ELSE NULL END AS matricula_id,
         CASE WHEN om.classe_id IS NOT NULL AND om.classe_id <> p_classe_id THEN om.classe_id ELSE NULL END AS outra_classe_id,
         CASE WHEN om.classe_id IS NOT NULL AND om.classe_id <> p_classe_id THEN om.classe_nome ELSE NULL END AS outra_classe_nome
    FROM public.membros m
    CROSS JOIN c
    LEFT JOIN outras_mat om ON om.pessoa_id = m.id
   WHERE m.status = 'ativo'
     AND m.tipo_pessoa IN ('membro','congregado')
     AND m.data_nascimento IS NOT NULL
     -- Exclui professores ativos em qualquer classe (professor nao eh aluno)
     AND NOT EXISTS (
       SELECT 1 FROM public.ebd_professores ep
        WHERE ep.pessoa_id = m.id AND ep.ativo = true
     )
     -- Exclui quem ja esta matriculado em outra classe ativa
     AND NOT EXISTS (
       SELECT 1 FROM public.ebd_matriculas em2
        WHERE em2.pessoa_id = m.id 
          AND em2.classe_id <> p_classe_id
          AND em2.ativo = true
     )
     AND (c.idade_min IS NULL OR EXTRACT(YEAR FROM AGE(CURRENT_DATE, m.data_nascimento)) >= c.idade_min)
     AND (c.idade_max IS NULL OR EXTRACT(YEAR FROM AGE(CURRENT_DATE, m.data_nascimento)) <= c.idade_max)
     AND (c.genero = 'misto' OR (m.sexo IS NOT NULL AND c.genero = m.sexo::text))
   ORDER BY m.nome_completo;
$function$
;

CREATE OR REPLACE FUNCTION public.eventos_bloqueia_local_arrecadacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_excl boolean;
begin
  if new.local_id is null then return new; end if;
  select coalesce(exclusivo_arrecadacao, false) into v_excl
    from public.locais where id = new.local_id;
  if v_excl then
    raise exception 'Este local é exclusivo de arrecadação. '
                    'Use o módulo /arrecadacao/reservas para reservá-lo.'
      using errcode = 'check_violation';
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.excluir_importacao(p_importacao_id uuid, p_deletar_dados boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id      UUID := auth.uid();
  v_user_email   TEXT;
  v_is_admin     BOOLEAN := false;
  v_qtd_membros  INT := 0;
  v_log_id       UUID;
  v_imp_status   TEXT;
BEGIN
  -- â”€â”€ ValidaÃ§Ãµes de seguranÃ§a â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NÃƒO_AUTENTICADO: Ã© necessÃ¡rio estar autenticado para executar esta operaÃ§Ã£o';
  END IF;

  -- Verificar role admin
  SELECT EXISTS(
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id AND role = 'admin'
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'PERMISSAO_NEGADA: somente administradores podem excluir importaÃ§Ãµes';
  END IF;

  -- Verificar se a importaÃ§Ã£o existe
  SELECT status INTO v_imp_status
    FROM public.importacoes_membros
   WHERE id = p_importacao_id;

  IF v_imp_status IS NULL THEN
    RAISE EXCEPTION 'NAO_ENCONTRADO: importaÃ§Ã£o % nÃ£o existe', p_importacao_id;
  END IF;

  -- Email do usuÃ¡rio
  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  -- â”€â”€ Contar registros que serÃ£o afetados â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  IF p_deletar_dados THEN
    SELECT COUNT(*) INTO v_qtd_membros
      FROM public.membros
     WHERE importacao_id = p_importacao_id;
  END IF;

  -- â”€â”€ Criar log antes de qualquer operaÃ§Ã£o â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  INSERT INTO public.log_exclusoes (
    usuario_id,
    usuario_email,
    tipo,
    importacao_id,
    quantidade,
    descricao
  ) VALUES (
    v_user_id,
    v_user_email,
    'importacao_membros',
    p_importacao_id,
    v_qtd_membros,
    CASE
      WHEN p_deletar_dados THEN
        'ExclusÃ£o completa: histÃ³rico + ' || v_qtd_membros || ' registro(s) importado(s)'
      ELSE
        'ExclusÃ£o apenas do histÃ³rico de importaÃ§Ã£o (dados mantidos)'
    END
  ) RETURNING id INTO v_log_id;

  -- â”€â”€ Backup + exclusÃ£o de dados â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  IF p_deletar_dados AND v_qtd_membros > 0 THEN

    -- Backup: salvar cÃ³pia JSONB de cada membro
    INSERT INTO public.membros_excluidos_backup (log_exclusao_id, membro_id, dados)
    SELECT
      v_log_id,
      id,
      to_jsonb(m) || jsonb_build_object('_backup_em', now(), '_importacao_id', p_importacao_id)
    FROM public.membros m
    WHERE importacao_id = p_importacao_id;

    -- Remover de tabelas dependentes (FK para membros)
    DELETE FROM public.ministerio_membros
     WHERE membro_id IN (
       SELECT id FROM public.membros WHERE importacao_id = p_importacao_id
     );

    -- familia_membros (se existir â€” sem erro se nÃ£o existir via DO block)
    BEGIN
      DELETE FROM public.familia_membros
       WHERE membro_id IN (
         SELECT id FROM public.membros WHERE importacao_id = p_importacao_id
       );
    EXCEPTION WHEN undefined_table THEN NULL;
    END;

    -- visita_historico (contato feito com esses membros)
    BEGIN
      DELETE FROM public.visita_historico
       WHERE visitante_id IN (
         SELECT id FROM public.membros WHERE importacao_id = p_importacao_id
       );
    EXCEPTION WHEN undefined_table THEN NULL;
    END;

    -- Excluir membros
    DELETE FROM public.membros
     WHERE importacao_id = p_importacao_id;

  END IF;

  -- â”€â”€ Marcar importaÃ§Ã£o como cancelada (mantÃ©m histÃ³rico) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  UPDATE public.importacoes_membros
     SET status      = 'cancelado',
         observacao  = 'ExcluÃ­do pelo administrador ' || v_user_email ||
                       ' em ' || to_char(now(), 'DD/MM/YYYY HH24:MI')
   WHERE id = p_importacao_id;

  -- â”€â”€ Retornar resultado â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  RETURN jsonb_build_object(
    'sucesso',           true,
    'membros_excluidos', v_qtd_membros,
    'dados_deletados',   p_deletar_dados,
    'log_id',            v_log_id
  );

EXCEPTION WHEN OTHERS THEN
  -- Re-raise com contexto
  RAISE EXCEPTION '%', SQLERRM;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.extrair_sobrenome(p_nome text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partes text[];
  v_idx    int;
  v_palavra text;
BEGIN
  IF p_nome IS NULL OR length(trim(p_nome)) = 0 THEN RETURN NULL; END IF;
  v_partes := regexp_split_to_array(lower(trim(p_nome)), E'\\s+');
  
  FOR v_idx IN REVERSE array_length(v_partes, 1)..1 LOOP
    v_palavra := v_partes[v_idx];
    -- Pula sufixos pessoais
    IF v_palavra IN ('filho','filha','junior','jr','jr.','neto','neta','sobrinho','sobrinha','iii','ii') THEN CONTINUE; END IF;
    -- Pula preposicoes e artigos
    IF v_palavra IN ('da','de','do','das','dos','e','dei','del','le','la') THEN CONTINUE; END IF;
    -- Tamanho minimo (evita iniciais "M.")
    IF length(v_palavra) < 3 THEN CONTINUE; END IF;
    -- Tira pontuacao residual
    v_palavra := regexp_replace(v_palavra, '[\.,;:]', '', 'g');
    RETURN v_palavra;
  END LOOP;
  
  RETURN v_partes[array_length(v_partes, 1)]; -- fallback: ultima palavra
END;
$function$
;

CREATE OR REPLACE FUNCTION public.familias_sem_responsavel()
 RETURNS TABLE(familia_id uuid, nome_familia text, qtd_membros bigint, primeiro_membro_id uuid, primeiro_membro_nome text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 
    f.id, 
    f.nome_familia,
    COUNT(vf.id) AS qtd_membros,
    (ARRAY_AGG(vf.membro_id ORDER BY vf.created_at))[1] AS primeiro_membro_id,
    (ARRAY_AGG(m.nome_completo ORDER BY vf.created_at))[1] AS primeiro_membro_nome
  FROM public.familias f
  LEFT JOIN public.vinculos_familiares vf ON vf.familia_id = f.id
  LEFT JOIN public.membros m ON m.id = vf.membro_id
  GROUP BY f.id, f.nome_familia
  HAVING COUNT(vf.id) > 0
     AND COUNT(vf.id) FILTER (WHERE vf.responsavel_familia = true) = 0
  ORDER BY f.nome_familia;
$function$
;

CREATE OR REPLACE FUNCTION public.fin_alertas_centros()
 RETURNS TABLE(centro_id uuid, centro_nome text, tipo_alerta text, titulo text, descricao text, severidade text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  -- 1) Acima do orçamento (≥ 100%)
  select o.centro_custo_id, o.centro_nome, 'acima_orcamento',
         'Acima do orçamento',
         o.centro_nome || ': ' || o.percentual_consumido || '% do orçamento (R$ ' ||
           to_char(o.valor_real, 'FM999999.99') || ' de R$ ' || to_char(o.valor_planejado, 'FM999999.99') || ')',
         'critico'
  from public.vw_fin_orcamento_vs_real o
  where o.percentual_consumido >= 100

  union all

  -- 2) 80%+ do orçamento (atenção)
  select o.centro_custo_id, o.centro_nome, 'orcamento_atencao',
         'Orçamento em alerta',
         o.centro_nome || ': ' || o.percentual_consumido || '% consumido',
         'atencao'
  from public.vw_fin_orcamento_vs_real o
  where o.percentual_consumido >= 80 and o.percentual_consumido < 100

  union all

  -- 3) Crescimento >40% vs trimestre anterior
  select cc.id, cc.nome, 'crescimento',
         'Crescimento atípico',
         cc.nome || ': gasto subiu vs trimestre anterior',
         'atencao'
  from public.fin_centros_custo cc
  where cc.ativo
    and (
      coalesce((
        select sum(l.valor) from public.fin_lancamentos l
        where l.centro_custo_id = cc.id and l.tipo = 'saida'
          and l.status in ('realizado','conciliado')
          and l.data >= current_date - interval '30 days'
      ), 0) > 1.4 * coalesce((
        select sum(l.valor) / 3.0 from public.fin_lancamentos l
        where l.centro_custo_id = cc.id and l.tipo = 'saida'
          and l.status in ('realizado','conciliado')
          and l.data >= current_date - interval '120 days'
          and l.data <  current_date - interval '30 days'
      ), 0)
    )
    and coalesce((
      select sum(l.valor) from public.fin_lancamentos l
      where l.centro_custo_id = cc.id and l.tipo = 'saida'
        and l.status in ('realizado','conciliado')
        and l.data >= current_date - interval '30 days'
    ), 0) > 100  -- ignora ruído

  union all

  -- 4) Centros ativos sem movimento em 60 dias
  select cc.id, cc.nome, 'sem_movimento',
         'Sem movimento recente',
         cc.nome || ': sem lançamentos nos últimos 60 dias',
         'info'
  from public.fin_centros_custo cc
  where cc.ativo
    and cc.vinculo_tipo <> 'geral'
    and not exists (
      select 1 from public.fin_lancamentos l
      where l.centro_custo_id = cc.id
        and l.data >= current_date - interval '60 days'
    );
$function$
;

CREATE OR REPLACE FUNCTION public.fin_alertas_financeiros()
 RETURNS TABLE(tipo text, titulo text, descricao text, severidade text, link text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  -- 1) Contas vencidas
  select 'conta_vencida', 'Conta vencida',
         count(*) || ' lançamento(s) vencido(s) totalizando R$ ' || to_char(sum(valor), 'FM9999999.99'),
         'critico', '/financas/agenda'
  from public.fin_lancamentos
  where status = 'previsto' and tipo = 'saida' and data < current_date
  having count(*) > 0

  union all

  -- 2) Vencendo nos proximos 5 dias
  select 'conta_proxima', 'Vencimentos próximos',
         count(*) || ' conta(s) para os próximos 5 dias totalizando R$ ' || to_char(sum(valor), 'FM9999999.99'),
         'atencao', '/financas/agenda'
  from public.fin_lancamentos
  where status = 'previsto' and tipo = 'saida'
    and data between current_date and current_date + interval '5 days'
  having count(*) > 0

  union all

  -- 3) Saldo previsto negativo em 30d
  select 'saldo_negativo_30d', 'Atenção: saldo projetado negativo em 30 dias',
         'Considere adiar pagamentos ou buscar receita extra',
         'critico', '/financas/insights'
  where (
    select saldo_projetado_30d from public.fin_previsao_caixa()
  ) < 0;
$function$
;

CREATE OR REPLACE FUNCTION public.fin_anomalias_mes(p_ano integer DEFAULT NULL::integer, p_mes integer DEFAULT NULL::integer)
 RETURNS TABLE(categoria_id uuid, categoria_nome text, tipo text, valor_mes numeric, media_6m numeric, variacao_pct numeric, severidade text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  with periodo_atual as (
    select coalesce(p_ano, extract(year from current_date)::int) as ano,
           coalesce(p_mes, extract(month from current_date)::int) as mes
  ),
  base as (
    select pa.ano, pa.mes,
           make_date(pa.ano, pa.mes, 1) as ini_mes,
           (make_date(pa.ano, pa.mes, 1) + interval '1 month - 1 day')::date as fim_mes
    from periodo_atual pa
  ),
  -- Total atual por categoria
  atual as (
    select l.categoria_id, k.nome, k.tipo::text,
           sum(l.valor) as valor_mes
    from public.fin_lancamentos l
    join base b on l.data between b.ini_mes and b.fim_mes
    left join public.fin_categorias k on k.id = l.categoria_id
    where l.status in ('realizado','conciliado') and l.categoria_id is not null
    group by l.categoria_id, k.nome, k.tipo
  ),
  -- Média dos 6 meses anteriores
  historico as (
    select l.categoria_id,
           sum(l.valor) / 6.0 as media_6m
    from public.fin_lancamentos l, base b
    where l.status in ('realizado','conciliado') and l.categoria_id is not null
      and l.data >= b.ini_mes - interval '6 months'
      and l.data <  b.ini_mes
    group by l.categoria_id
  )
  select a.categoria_id, a.nome, a.tipo, a.valor_mes,
         coalesce(h.media_6m, 0) as media_6m,
         case when coalesce(h.media_6m, 0) = 0 then null
              else round(100.0 * (a.valor_mes - h.media_6m) / h.media_6m, 1)
         end as variacao_pct,
         case
           when coalesce(h.media_6m, 0) = 0 then 'novo'
           when abs(a.valor_mes - h.media_6m) / h.media_6m >= 0.5 then 'critico'
           when abs(a.valor_mes - h.media_6m) / h.media_6m >= 0.3 then 'atencao'
           else 'normal'
         end as severidade
  from atual a
  left join historico h on h.categoria_id = a.categoria_id
  order by abs(a.valor_mes - coalesce(h.media_6m, 0)) desc;
$function$
;

CREATE OR REPLACE FUNCTION public.fin_atualiza_estoque_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_delta numeric;
  v_atual numeric;
begin
  if tg_op = 'INSERT' then
    v_delta := case new.tipo
      when 'entrada' then new.quantidade
      when 'saida'   then -new.quantidade
      when 'ajuste'  then new.quantidade  -- ajuste positivo (use negativo no quantidade pra reduzir)
      else 0
    end;
    update public.fin_estoque_itens
       set estoque_atual = estoque_atual + v_delta,
           custo_medio = case
             when new.tipo = 'entrada' and new.valor_unitario is not null then
               -- média ponderada simples
               coalesce(((estoque_atual * coalesce(custo_medio, 0)) + (new.quantidade * new.valor_unitario))
                        / nullif(estoque_atual + new.quantidade, 0), new.valor_unitario)
             else custo_medio
           end
     where id = new.item_id;
  elsif tg_op = 'DELETE' then
    v_delta := case old.tipo
      when 'entrada' then -old.quantidade
      when 'saida'   then old.quantidade
      when 'ajuste'  then -old.quantidade
      else 0
    end;
    update public.fin_estoque_itens
       set estoque_atual = estoque_atual + v_delta
     where id = old.item_id;
  end if;

  -- Calcular valor_total automaticamente
  if tg_op = 'INSERT' and new.valor_unitario is not null then
    update public.fin_estoque_movimentos
       set valor_total = new.quantidade * new.valor_unitario
     where id = new.id;
  end if;

  return null;
end;$function$
;

CREATE OR REPLACE FUNCTION public.fin_atualiza_saldo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op in ('INSERT','UPDATE') then
    perform public.fin_recalc_saldo_conta(new.conta_id);
    if tg_op = 'UPDATE' and old.conta_id <> new.conta_id then
      perform public.fin_recalc_saldo_conta(old.conta_id);
    end if;
  end if;
  if tg_op = 'DELETE' then
    perform public.fin_recalc_saldo_conta(old.conta_id);
  end if;
  return null;
end;$function$
;

CREATE OR REPLACE FUNCTION public.fin_calc_proxima_data(p_ultima date, p_dia integer, p_freq fin_frequencia)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_meses int;
  v_proximo_mes_inicio date;
  v_dia_max int;
begin
  v_meses := case p_freq
    when 'mensal'     then 1
    when 'bimestral'  then 2
    when 'trimestral' then 3
    when 'semestral'  then 6
    when 'anual'      then 12
    else 1
  end;
  -- 1º dia do mês alvo
  v_proximo_mes_inicio := (date_trunc('month', p_ultima) + (v_meses || ' month')::interval)::date;
  -- último dia do mês alvo
  v_dia_max := extract(day from (date_trunc('month', v_proximo_mes_inicio) + interval '1 month - 1 day'));
  return v_proximo_mes_inicio + (least(p_dia, v_dia_max) - 1);
end;$function$
;

CREATE OR REPLACE FUNCTION public.fin_comparativo_meses(p_n integer DEFAULT 6)
 RETURNS TABLE(ano integer, mes integer, rotulo text, entradas numeric, saidas numeric, resultado numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  with meses as (
    select generate_series(
      date_trunc('month', current_date)::date - (p_n - 1) * interval '1 month',
      date_trunc('month', current_date)::date,
      interval '1 month'
    )::date as ini
  ),
  agreg as (
    select m.ini,
           extract(year from m.ini)::int as ano,
           extract(month from m.ini)::int as mes,
           to_char(m.ini, 'TMMon/YY') as rotulo,
           coalesce((select sum(l.valor) from public.fin_lancamentos l
             where l.data >= m.ini and l.data < (m.ini + interval '1 month')
               and l.tipo = 'entrada' and l.status in ('realizado','conciliado')), 0) as entradas,
           coalesce((select sum(l.valor) from public.fin_lancamentos l
             where l.data >= m.ini and l.data < (m.ini + interval '1 month')
               and l.tipo = 'saida' and l.status in ('realizado','conciliado')), 0) as saidas
    from meses m
  )
  select ano, mes, rotulo, entradas, saidas, (entradas - saidas) as resultado
  from agreg
  order by ini;
$function$
;

CREATE OR REPLACE FUNCTION public.fin_decisao_para_assunto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_assunto_id uuid;
begin
  if new.assunto_id is not null then return new; end if;
  -- Cria assunto vinculado à decisão da reunião
  insert into assuntos (
    titulo, descricao, status, prioridade,
    responsavel_id, responsavel_nome, prazo,
    origem, vinculo_tipo, vinculo_id, vinculo_descricao
  ) values (
    new.descricao,
    'Decisão tomada em reunião financeira',
    'aberto',
    case when new.prazo is not null and new.prazo < current_date + 7 then 'alta'
         else 'media' end,
    new.responsavel_id, new.responsavel_nome, new.prazo,
    'reuniao_financeira', 'fin_reunioes_financeiras', new.reuniao_id,
    'Decisão de reunião financeira'
  ) returning id into v_assunto_id;
  new.assunto_id := v_assunto_id;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fin_exec_alertas()
 RETURNS TABLE(severidade text, categoria text, mensagem text, detalhe text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_ano int := extract(year from current_date)::int;
begin
  -- Contas com saldo crítico (< R$ 5000)
  return query
  select
    'alta'::text, 'caixa'::text,
    format('%s tem saldo crítico', c.nome) as mensagem,
    format('Saldo: R$ %s', to_char(c.saldo_inicial +
      coalesce((select sum(case when tipo='entrada' then valor else -valor end)
                from fin_lancamentos l
                where l.conta_id = c.id and l.status in ('realizado','conciliado')), 0),
      'FM999G999G999D90'))::text as detalhe
  from fin_contas c
  where c.saldo_inicial +
    coalesce((select sum(case when tipo='entrada' then valor else -valor end)
              from fin_lancamentos l
              where l.conta_id = c.id and l.status in ('realizado','conciliado')), 0) < 5000;

  -- Centros que ultrapassaram o orçamento anual
  return query
  with realiz as (
    select cc.id, cc.nome,
      coalesce(sum(l.valor), 0) as total,
      coalesce((select sum(o.valor) from fin_orcamentos o
                where o.centro_custo_id = cc.id and o.ano = v_ano), 0) as orcado
    from fin_centros_custo cc
    left join fin_lancamentos l on l.centro_custo_id = cc.id
      and l.tipo = 'saida'
      and l.status in ('realizado','conciliado')
      and extract(year from l.data_competencia) = v_ano
    group by cc.id, cc.nome
  )
  select
    case when r.total / nullif(r.orcado, 0) > 1 then 'alta' else 'media' end,
    'orcamento'::text,
    format('Orçamento %s', r.nome),
    format('R$ %s realizado de R$ %s (%s%%)',
      to_char(r.total, 'FM999G999D90'),
      to_char(r.orcado, 'FM999G999D90'),
      to_char(r.total / nullif(r.orcado, 0) * 100, 'FM990D0'))
  from realiz r
  where r.orcado > 0 and r.total / r.orcado > 0.9;

  -- Obrigações fiscais atrasadas
  begin
    return query
    select
      'alta'::text, 'fiscal'::text,
      format('%s obrigação(ões) fiscal(is) ATRASADA(S)', count(*)::text),
      'Veja em /financas/fiscal'::text
    from fiscal_agenda
    where status = 'atrasado'
    having count(*) > 0;
  exception when others then null;
  end;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fin_exec_centros_ano()
 RETURNS TABLE(centro_id uuid, nome text, realizado numeric, orcado numeric, percentual numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_ano int := extract(year from current_date)::int;
begin
  return query
  with realizados as (
    select cc.id, cc.nome,
      coalesce(sum(l.valor), 0)::numeric(12,2) as total
    from fin_centros_custo cc
    left join fin_lancamentos l on l.centro_custo_id = cc.id
      and l.tipo = 'saida'
      and l.status in ('realizado','conciliado')
      and extract(year from l.data_competencia) = v_ano
    group by cc.id, cc.nome
  ),
  com_orcamento as (
    select r.id as centro_id, r.nome, r.total as realizado,
      coalesce((select sum(o.valor) from fin_orcamentos o
                where o.centro_custo_id = r.id and o.ano = v_ano), 0)::numeric(12,2) as orcado
    from realizados r
  )
  select
    c.centro_id, c.nome, c.realizado, c.orcado,
    case when c.orcado > 0 then round(c.realizado / c.orcado * 100, 1)
         else null end as percentual
  from com_orcamento c
  where c.realizado > 0
  order by c.realizado desc
  limit 5;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fin_exec_fluxo_12m()
 RETURNS TABLE(mes date, rotulo text, entradas numeric, saidas numeric, saldo numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_mes date;
begin
  v_mes := date_trunc('month', current_date - interval '11 months')::date;
  for i in 0..11 loop
    return query
    select
      v_mes,
      to_char(v_mes, 'Mon/YY'),
      coalesce(sum(case when l.tipo='entrada' then l.valor else 0 end), 0)::numeric(12,2),
      coalesce(sum(case when l.tipo='saida'   then l.valor else 0 end), 0)::numeric(12,2),
      coalesce(sum(case when l.tipo='entrada' then l.valor else -l.valor end), 0)::numeric(12,2)
    from fin_lancamentos l
    where l.status in ('realizado','conciliado')
      and date_trunc('month', l.data_competencia) = v_mes;
    v_mes := (v_mes + interval '1 month')::date;
  end loop;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fin_exec_indicadores_eclesiasticos()
 RETURNS TABLE(indicador text, total_ano numeric, total_mes_atual numeric, total_mes_anterior numeric, variacao_pct numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_ano int := extract(year from current_date)::int;
begin
  return query
  with cats as (
    select
      case
        when c.nome ilike '%dizimo%' or c.nome ilike '%dízimo%' then 'Dízimos'
        when c.nome ilike '%oferta%' then 'Ofertas'
        when c.nome ilike '%missao%' or c.nome ilike '%missão%' or c.nome ilike '%missões%' or c.nome ilike '%missoes%' then 'Missões'
        else null
      end as indicador,
      c.id
    from fin_categorias c
    where c.tipo = 'entrada'
  ),
  base as (
    select
      ct.indicador,
      l.data_competencia,
      l.valor
    from fin_lancamentos l
    join cats ct on ct.id = l.categoria_id
    where ct.indicador is not null
      and l.status in ('realizado','conciliado')
  ),
  agregado as (
    select
      b.indicador,
      sum(case when extract(year from b.data_competencia) = v_ano then b.valor else 0 end)::numeric(12,2) as total_ano,
      sum(case when date_trunc('month', b.data_competencia) = date_trunc('month', current_date)
                then b.valor else 0 end)::numeric(12,2) as total_mes_atual,
      sum(case when date_trunc('month', b.data_competencia) = date_trunc('month', current_date - interval '1 month')
                then b.valor else 0 end)::numeric(12,2) as total_mes_anterior
    from base b
    group by b.indicador
  )
  select
    a.indicador, a.total_ano, a.total_mes_atual, a.total_mes_anterior,
    case when a.total_mes_anterior > 0
      then round((a.total_mes_atual - a.total_mes_anterior) / a.total_mes_anterior * 100, 1)
      else null end as variacao_pct
  from agregado a
  order by a.total_ano desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fin_exec_saldo_consolidado()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_saldo_atual numeric := 0;
  v_a_pagar_30 numeric := 0;
  v_a_receber_30 numeric := 0;
  v_a_pagar_60 numeric := 0;
  v_a_pagar_90 numeric := 0;
  v_qtd_contas int := 0;
begin
  -- saldo somando todas as contas (saldo_inicial + realizados/conciliados)
  select coalesce(sum(c.saldo_inicial), 0) into v_saldo_atual from fin_contas c;
  select v_saldo_atual + coalesce(sum(case when tipo='entrada' then valor else -valor end), 0)
    into v_saldo_atual
  from fin_lancamentos
  where status in ('realizado','conciliado');

  -- contagens pra previsão
  select count(*) into v_qtd_contas from fin_contas;

  select coalesce(sum(valor), 0) into v_a_pagar_30
  from fin_lancamentos
  where status = 'a_pagar' and tipo = 'saida'
    and data_vencimento between current_date and current_date + 30;

  select coalesce(sum(valor), 0) into v_a_pagar_60
  from fin_lancamentos
  where status = 'a_pagar' and tipo = 'saida'
    and data_vencimento between current_date and current_date + 60;

  select coalesce(sum(valor), 0) into v_a_pagar_90
  from fin_lancamentos
  where status = 'a_pagar' and tipo = 'saida'
    and data_vencimento between current_date and current_date + 90;

  select coalesce(sum(valor), 0) into v_a_receber_30
  from fin_lancamentos
  where status = 'a_pagar' and tipo = 'entrada'
    and data_vencimento between current_date and current_date + 30;

  return jsonb_build_object(
    'saldo_atual', v_saldo_atual,
    'qtd_contas', v_qtd_contas,
    'a_pagar_30d', v_a_pagar_30,
    'a_receber_30d', v_a_receber_30,
    'previsao_30d', v_saldo_atual + v_a_receber_30 - v_a_pagar_30,
    'previsao_60d', v_saldo_atual - v_a_pagar_60,
    'previsao_90d', v_saldo_atual - v_a_pagar_90
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.fin_gerar_recorrencias(p_ate_data date DEFAULT NULL::date, p_recorrencia_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_recorrencia record;
  v_ate date := coalesce(p_ate_data, current_date + interval '90 days');
  v_data date;
  v_count int := 0;
begin
  for v_recorrencia in
    select * from public.fin_recorrencias
    where ativo
      and (p_recorrencia_id is null or id = p_recorrencia_id)
  loop
    -- ponto de partida
    if v_recorrencia.ultimo_gerado_ate is null then
      -- primeira vez: começa do mês corrente
      v_data := date_trunc('month', current_date)::date +
                (least(v_recorrencia.dia_vencimento,
                       extract(day from (date_trunc('month', current_date) + interval '1 month - 1 day'))::int) - 1);
      -- Se a data já passou, pula pra próxima
      if v_data < current_date then
        v_data := public.fin_calc_proxima_data(v_data, v_recorrencia.dia_vencimento, v_recorrencia.frequencia);
      end if;
    else
      v_data := public.fin_calc_proxima_data(v_recorrencia.ultimo_gerado_ate, v_recorrencia.dia_vencimento, v_recorrencia.frequencia);
    end if;

    -- gera enquanto não passa do limite e da data_fim (se houver)
    while v_data <= v_ate and (v_recorrencia.data_fim is null or v_data <= v_recorrencia.data_fim) loop
      insert into public.fin_lancamentos(
        data, tipo, status, conta_id, categoria_id, centro_custo_id, fornecedor_id,
        valor, descricao, origem, data_competencia
      ) values (
        v_data, v_recorrencia.tipo, 'previsto', v_recorrencia.conta_id,
        v_recorrencia.categoria_id, v_recorrencia.centro_custo_id, v_recorrencia.fornecedor_id,
        v_recorrencia.valor, v_recorrencia.descricao, 'recorrencia',
        date_trunc('month', v_data)::date
      );
      v_count := v_count + 1;
      update public.fin_recorrencias set ultimo_gerado_ate = v_data where id = v_recorrencia.id;
      v_data := public.fin_calc_proxima_data(v_data, v_recorrencia.dia_vencimento, v_recorrencia.frequencia);
    end loop;
  end loop;

  return v_count;
end;$function$
;

CREATE OR REPLACE FUNCTION public.fin_previsao_caixa()
 RETURNS TABLE(saldo_atual numeric, entradas_previstas_30d numeric, saidas_previstas_30d numeric, saldo_projetado_30d numeric, entradas_previstas_60d numeric, saidas_previstas_60d numeric, saldo_projetado_60d numeric, entradas_previstas_90d numeric, saidas_previstas_90d numeric, saldo_projetado_90d numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  with saldo as (
    select coalesce(sum(saldo_atual), 0) as total
    from public.fin_contas where ativo
  ),
  previstos as (
    select
      sum(valor) filter (where tipo = 'entrada' and data <= current_date + interval '30 days') as ent_30,
      sum(valor) filter (where tipo = 'saida'   and data <= current_date + interval '30 days') as sai_30,
      sum(valor) filter (where tipo = 'entrada' and data <= current_date + interval '60 days') as ent_60,
      sum(valor) filter (where tipo = 'saida'   and data <= current_date + interval '60 days') as sai_60,
      sum(valor) filter (where tipo = 'entrada' and data <= current_date + interval '90 days') as ent_90,
      sum(valor) filter (where tipo = 'saida'   and data <= current_date + interval '90 days') as sai_90
    from public.fin_lancamentos
    where status = 'previsto'
      and data >= current_date
  )
  select
    s.total,
    coalesce(p.ent_30, 0), coalesce(p.sai_30, 0), s.total + coalesce(p.ent_30, 0) - coalesce(p.sai_30, 0),
    coalesce(p.ent_60, 0), coalesce(p.sai_60, 0), s.total + coalesce(p.ent_60, 0) - coalesce(p.sai_60, 0),
    coalesce(p.ent_90, 0), coalesce(p.sai_90, 0), s.total + coalesce(p.ent_90, 0) - coalesce(p.sai_90, 0)
  from saldo s, previstos p;
$function$
;

CREATE OR REPLACE FUNCTION public.fin_recalc_saldo_conta(p_conta_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.fin_contas c
     set saldo_atual = c.saldo_inicial + coalesce((
       select sum(case when l.tipo = 'entrada' then l.valor else -l.valor end)
       from public.fin_lancamentos l
       where l.conta_id = c.id
         and l.status in ('realizado','conciliado')
     ), 0)
   where c.id = p_conta_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.fin_seed_centros_custo()
 RETURNS TABLE(criados integer, ja_existiam integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_criados int := 0;
  v_existiam int := 0;
  rec record;
begin
  -- 1) Ministérios → centro raiz
  for rec in select id, nome from public.ministerios where ativo loop
    if not exists (
      select 1 from public.fin_centros_custo
      where vinculo_tipo = 'ministerio' and vinculo_id = rec.id
    ) then
      insert into public.fin_centros_custo (nome, vinculo_tipo, vinculo_id, vinculo_nome)
      values ('Min. ' || rec.nome, 'ministerio', rec.id, rec.nome);
      v_criados := v_criados + 1;
    else
      v_existiam := v_existiam + 1;
    end if;
  end loop;

  -- 2) Áreas → centro com pai = ministério
  for rec in
    select a.id, a.nome, a.ministerio_id, m.nome as ministerio_nome
    from public.areas a
    left join public.ministerios m on m.id = a.ministerio_id
    where a.ativo
  loop
    if not exists (
      select 1 from public.fin_centros_custo
      where vinculo_tipo = 'area' and vinculo_id = rec.id
    ) then
      insert into public.fin_centros_custo (nome, vinculo_tipo, vinculo_id, vinculo_nome, centro_pai_id)
      values (
        coalesce(rec.ministerio_nome || ' · ' || rec.nome, rec.nome),
        'area', rec.id, rec.nome,
        (select id from public.fin_centros_custo
         where vinculo_tipo = 'ministerio' and vinculo_id = rec.ministerio_id limit 1)
      );
      v_criados := v_criados + 1;
    else
      v_existiam := v_existiam + 1;
    end if;
  end loop;

  -- 3) Classes EBD
  for rec in select id, nome from public.ebd_classes where ativo loop
    if not exists (
      select 1 from public.fin_centros_custo
      where vinculo_tipo = 'ebd_classe' and vinculo_id = rec.id
    ) then
      insert into public.fin_centros_custo (nome, vinculo_tipo, vinculo_id, vinculo_nome)
      values ('EBD ' || rec.nome, 'ebd_classe', rec.id, rec.nome);
      v_criados := v_criados + 1;
    else
      v_existiam := v_existiam + 1;
    end if;
  end loop;

  -- 4) PGMs
  begin
    for rec in select id, nome from public.pgm_grupos where ativo loop
      if not exists (
        select 1 from public.fin_centros_custo
        where vinculo_tipo = 'pgm_grupo' and vinculo_id = rec.id
      ) then
        insert into public.fin_centros_custo (nome, vinculo_tipo, vinculo_id, vinculo_nome)
        values ('PGM ' || rec.nome, 'pgm_grupo', rec.id, rec.nome);
        v_criados := v_criados + 1;
      else
        v_existiam := v_existiam + 1;
      end if;
    end loop;
  exception when others then
    null; -- PGM pode não existir
  end;

  -- 5) Campanhas EBD ativas
  begin
    for rec in select id, nome from public.ebd_campanhas where ativo loop
      if not exists (
        select 1 from public.fin_centros_custo
        where vinculo_tipo = 'campanha' and vinculo_id = rec.id
      ) then
        insert into public.fin_centros_custo (nome, vinculo_tipo, vinculo_id, vinculo_nome)
        values ('Camp. ' || rec.nome, 'campanha', rec.id, rec.nome);
        v_criados := v_criados + 1;
      else
        v_existiam := v_existiam + 1;
      end if;
    end loop;
  exception when others then null;
  end;

  return query select v_criados, v_existiam;
end;$function$
;

CREATE OR REPLACE FUNCTION public.fin_sugerir_centro_por_categoria(p_categoria_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  -- Centro de custo mais usado para essa categoria (excluindo "geral")
  select l.centro_custo_id
  from public.fin_lancamentos l
  join public.fin_centros_custo cc on cc.id = l.centro_custo_id
  where l.categoria_id = p_categoria_id
    and l.centro_custo_id is not null
    and cc.vinculo_tipo <> 'geral'
    and l.status in ('realizado','conciliado')
    and l.data >= current_date - interval '180 days'
  group by l.centro_custo_id
  order by count(*) desc
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.fin_top_fornecedores(p_n integer DEFAULT 10, p_dias integer DEFAULT 90)
 RETURNS TABLE(fornecedor_id uuid, fornecedor_nome text, total numeric, qtd_lancamentos integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  select
    l.fornecedor_id,
    f.nome,
    sum(l.valor) as total,
    count(l.id)::int as qtd
  from public.fin_lancamentos l
  join public.fin_fornecedores f on f.id = l.fornecedor_id
  where l.tipo = 'saida'
    and l.status in ('realizado','conciliado')
    and l.data >= current_date - (p_dias || ' days')::interval
  group by l.fornecedor_id, f.nome
  order by total desc
  limit p_n;
$function$
;

CREATE OR REPLACE FUNCTION public.fiscal_alertas_proximos(p_dias integer DEFAULT 7)
 RETURNS TABLE(id uuid, codigo_obrigacao text, nome text, icone text, cor text, competencia date, vencimento date, dias_para_vencer integer, severidade text, valor_esperado numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_dias_alerta int;
begin
  select coalesce(alerta_dias_antes, 3) into v_dias_alerta
  from fiscal_config where id = 1;

  return query
  select
    a.id,
    a.codigo_obrigacao,
    t.nome,
    t.icone,
    t.cor,
    a.competencia,
    a.vencimento,
    (a.vencimento - current_date)::int as dias_para_vencer,
    case
      when a.vencimento < current_date then 'atrasado'
      when a.vencimento <= current_date + coalesce(v_dias_alerta,3) then 'urgente'
      else 'proximo'
    end as severidade,
    a.valor_esperado
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where a.status = 'pendente'
    and a.vencimento <= current_date + p_dias
  order by a.vencimento;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_criar_lancamento(p_agenda_id uuid, p_valor numeric, p_descricao text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_agenda record;
  v_obrig_ativa record;
  v_lancamento_id uuid;
  v_descricao text;
begin
  -- Carrega a obrigação na agenda
  select a.*, t.nome
  into v_agenda
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where a.id = p_agenda_id;

  if not found then
    raise exception 'Obrigação não encontrada';
  end if;

  if v_agenda.lancamento_id is not null then
    raise exception 'Esta obrigação já tem lançamento vinculado';
  end if;

  -- Carrega defaults da obrigação ativa (categoria, centro, conta)
  select * into v_obrig_ativa
  from fiscal_obrigacoes_ativas
  where codigo_obrigacao = v_agenda.codigo_obrigacao;

  v_descricao := coalesce(
    p_descricao,
    format('%s - competência %s',
      v_agenda.nome,
      to_char(v_agenda.competencia, 'MM/YYYY'))
  );

  -- Insere o lançamento financeiro
  insert into fin_lancamentos (
    tipo, status, valor, descricao,
    data_vencimento, data_competencia,
    categoria_id, centro_custo_id, conta_id,
    origem
  ) values (
    'saida', 'a_pagar', p_valor, v_descricao,
    v_agenda.vencimento, v_agenda.competencia,
    v_obrig_ativa.categoria_financeira_id,
    v_obrig_ativa.centro_custo_id,
    v_obrig_ativa.conta_pagadora_id,
    'fiscal'
  ) returning id into v_lancamento_id;

  -- Atualiza a agenda fiscal com o vínculo e valor esperado
  update fiscal_agenda
  set lancamento_id = v_lancamento_id,
      valor_esperado = coalesce(valor_esperado, p_valor),
      atualizado_em = now()
  where id = p_agenda_id;

  return v_lancamento_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_documentos_mes(p_ano integer, p_mes integer)
 RETURNS TABLE(documento_id uuid, codigo_obrigacao text, nome_obrigacao text, competencia date, vencimento date, status_obrigacao text, valor_pago numeric, data_pagamento date, tipo_doc text, nome_arquivo text, storage_path text, mime_type text, observacao text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  select
    d.id,
    a.codigo_obrigacao,
    t.nome,
    a.competencia,
    a.vencimento,
    a.status,
    a.valor_pago,
    a.data_pagamento,
    d.tipo,
    d.nome_arquivo,
    d.storage_path,
    d.mime_type,
    d.observacao
  from fiscal_documentos d
  join fiscal_agenda a on a.id = d.agenda_id
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where extract(year  from a.competencia) = p_ano
    and extract(month from a.competencia) = p_mes
  order by a.codigo_obrigacao, d.enviado_em;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_gerar_agenda(p_inicio date, p_fim date)
 RETURNS TABLE(codigo text, competencia date, vencimento date, novo boolean)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_obrig record;
  v_mes date;
  v_vencimento date;
  v_dia smallint;
  v_inseriu boolean;
begin
  for v_obrig in
    select t.*, coalesce(a.dia_vencimento_custom, t.dia_vencimento) as dia_efetivo
    from fiscal_tipos_obrigacao t
    join fiscal_obrigacoes_ativas a on a.codigo_obrigacao = t.codigo
    where a.ativa = true
      and (t.requer_funcionarios = false
           or (select possui_funcionarios from fiscal_config where id = 1))
  loop
    if v_obrig.periodicidade = 'mensal' then
      v_mes := date_trunc('month', p_inicio)::date;
      while v_mes <= p_fim loop
        v_dia := coalesce(v_obrig.dia_efetivo, 15);
        v_vencimento := make_date(extract(year from v_mes)::int, extract(month from v_mes)::int, v_dia);
        -- vencimento e sempre no mes SEGUINTE a competencia (regime padrao)
        v_vencimento := v_vencimento + interval '1 month';
        -- ajuste para dia util seguinte se cair em fim de semana
        while extract(dow from v_vencimento) in (0,6) loop
          v_vencimento := v_vencimento + interval '1 day';
        end loop;

        insert into fiscal_agenda(codigo_obrigacao, competencia, vencimento)
        select v_obrig.codigo, v_mes, v_vencimento
         where not exists (
           select 1 from fiscal_agenda fa
            where fa.codigo_obrigacao = v_obrig.codigo
              and fa.competencia      = v_mes
         );
        v_inseriu := found;

        codigo := v_obrig.codigo;
        competencia := v_mes;
        vencimento := v_vencimento;
        novo := v_inseriu;
        return next;

        v_mes := (v_mes + interval '1 month')::date;
      end loop;

    elsif v_obrig.periodicidade = 'anual' then
      for v_dia in extract(year from p_inicio)::int .. extract(year from p_fim)::int loop
        -- DIRF: ultimo dia util de fevereiro do ano subsequente
        v_vencimento := make_date(v_dia, coalesce(v_obrig.mes_anual, 2)::int, 28);
        while extract(dow from v_vencimento) in (0,6) loop
          v_vencimento := v_vencimento - interval '1 day';
        end loop;
        v_mes := make_date(v_dia - 1, 1, 1);  -- competencia = ano anterior

        insert into fiscal_agenda(codigo_obrigacao, competencia, vencimento)
        select v_obrig.codigo, v_mes, v_vencimento
         where not exists (
           select 1 from fiscal_agenda fa
            where fa.codigo_obrigacao = v_obrig.codigo
              and fa.competencia      = v_mes
         );
        v_inseriu := found;

        codigo := v_obrig.codigo;
        competencia := v_mes;
        vencimento := v_vencimento;
        novo := v_inseriu;
        return next;
      end loop;
    end if;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fiscal_historico_medio()
 RETURNS TABLE(codigo_obrigacao text, qtd_pagamentos integer, media_paga numeric, ultimo_pago numeric, desvio_padrao numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
begin
  return query
  select
    a.codigo_obrigacao,
    count(*)::int as qtd_pagamentos,
    avg(a.valor_pago)::numeric(12,2) as media_paga,
    (array_agg(a.valor_pago order by a.data_pagamento desc))[1]::numeric(12,2) as ultimo_pago,
    coalesce(stddev_samp(a.valor_pago), 0)::numeric(12,2) as desvio_padrao
  from fiscal_agenda a
  where a.status = 'pago'
    and a.valor_pago is not null
    and a.data_pagamento >= current_date - interval '6 months'
  group by a.codigo_obrigacao
  having count(*) >= 2;     -- precisa de pelo menos 2 pagamentos pra ter base
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_inconsistencias()
 RETURNS TABLE(tipo text, severidade text, agenda_id uuid, codigo_obrigacao text, nome_obrigacao text, competencia date, mensagem text, detalhes jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
begin
  -- 1) Valor anômalo (fora de 30% da média)
  return query
  with hist as (select * from fiscal_historico_medio())
  select
    'valor_anomalo'::text as tipo,
    (case
       when abs(a.valor_pago - h.media_paga) / nullif(h.media_paga, 0) > 0.5 then 'alta'
       else 'media'
     end)::text as severidade,
    a.id as agenda_id,
    a.codigo_obrigacao,
    t.nome as nome_obrigacao,
    a.competencia,
    format('Pago R$ %s — média histórica R$ %s (%s %s de variação)',
      to_char(a.valor_pago, 'FM999G999D90'),
      to_char(h.media_paga, 'FM999G999D90'),
      to_char(abs(a.valor_pago - h.media_paga) / h.media_paga * 100, 'FM990D0'),
      '%') as mensagem,
    jsonb_build_object(
      'valor_pago', a.valor_pago,
      'media_historica', h.media_paga,
      'desvio_padrao', h.desvio_padrao,
      'qtd_pagamentos_base', h.qtd_pagamentos
    ) as detalhes
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  join hist h on h.codigo_obrigacao = a.codigo_obrigacao
  where a.status = 'pago'
    and a.valor_pago is not null
    and a.data_pagamento >= current_date - interval '60 days'
    and abs(a.valor_pago - h.media_paga) / nullif(h.media_paga, 0) > 0.3;

  -- 2) Obrigação paga SEM documento anexado
  return query
  select
    'sem_documento'::text as tipo,
    'media'::text as severidade,
    a.id as agenda_id,
    a.codigo_obrigacao,
    t.nome as nome_obrigacao,
    a.competencia,
    format('%s de %s consta como paga mas não tem comprovante anexado',
      t.nome,
      to_char(a.competencia, 'MM/YYYY')) as mensagem,
    jsonb_build_object('data_pagamento', a.data_pagamento, 'valor_pago', a.valor_pago) as detalhes
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where a.status = 'pago'
    and a.data_pagamento >= current_date - interval '90 days'
    and not exists (select 1 from fiscal_documentos d where d.agenda_id = a.id);

  -- 3) Obrigação do mês anterior sem nenhum movimento (esperada mas não criada)
  -- (já coberto pela RPC fiscal_marcar_atrasados na FB-2, mas trazemos aqui)
  return query
  select
    'sem_movimento'::text as tipo,
    'alta'::text as severidade,
    a.id as agenda_id,
    a.codigo_obrigacao,
    t.nome as nome_obrigacao,
    a.competencia,
    format('%s da competência %s está ATRASADA há %s dia(s)',
      t.nome,
      to_char(a.competencia, 'MM/YYYY'),
      (current_date - a.vencimento)::text) as mensagem,
    jsonb_build_object('vencimento', a.vencimento, 'dias_atraso', current_date - a.vencimento) as detalhes
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where a.status in ('pendente','atrasado')
    and a.vencimento < current_date;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_insights()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_ano int := extract(year from current_date)::int;
  v_total_pago_ytd numeric;
  v_total_pago_mes_atual numeric;
  v_total_pago_mes_anterior numeric;
  v_count_inconsistencias int;
  v_obrig_mais_cara text;
  v_obrig_mais_cara_total numeric;
begin
  -- Total pago YTD (ano corrente)
  select coalesce(sum(valor_pago), 0)
  into v_total_pago_ytd
  from fiscal_agenda
  where status = 'pago'
    and extract(year from data_pagamento) = v_ano;

  -- Mês atual vs anterior
  select coalesce(sum(valor_pago), 0)
  into v_total_pago_mes_atual
  from fiscal_agenda
  where status = 'pago'
    and date_trunc('month', data_pagamento) = date_trunc('month', current_date);

  select coalesce(sum(valor_pago), 0)
  into v_total_pago_mes_anterior
  from fiscal_agenda
  where status = 'pago'
    and date_trunc('month', data_pagamento) = date_trunc('month', current_date - interval '1 month');

  -- Obrigação que mais drena recursos no ano
  select t.nome, sum(a.valor_pago)
  into v_obrig_mais_cara, v_obrig_mais_cara_total
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where a.status = 'pago'
    and extract(year from a.data_pagamento) = v_ano
  group by t.nome
  order by sum(a.valor_pago) desc
  limit 1;

  -- Quantas inconsistências
  select count(*)::int into v_count_inconsistencias from fiscal_inconsistencias();

  return jsonb_build_object(
    'ano', v_ano,
    'total_pago_ytd', v_total_pago_ytd,
    'total_pago_mes_atual', v_total_pago_mes_atual,
    'total_pago_mes_anterior', v_total_pago_mes_anterior,
    'variacao_mes_pct',
      case when v_total_pago_mes_anterior > 0
        then round((v_total_pago_mes_atual - v_total_pago_mes_anterior) / v_total_pago_mes_anterior * 100, 1)
        else null end,
    'obrigacao_mais_cara', v_obrig_mais_cara,
    'obrigacao_mais_cara_total', v_obrig_mais_cara_total,
    'count_inconsistencias', v_count_inconsistencias
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_marcar_atrasados()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_count int;
begin
  with atualizados as (
    update fiscal_agenda
    set status = 'atrasado', atualizado_em = now()
    where status = 'pendente'
      and vencimento < current_date
    returning 1
  )
  select count(*) into v_count from atualizados;
  return v_count;
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_resumo_dashboard()
 RETURNS TABLE(total_atrasados integer, total_urgentes integer, total_proximos integer, total_pagos_mes integer, proximos jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_dias_alerta int;
begin
  select coalesce(alerta_dias_antes, 3) into v_dias_alerta
  from fiscal_config where id = 1;
  v_dias_alerta := coalesce(v_dias_alerta, 3);

  return query
  with classificados as (
    select
      a.id, a.codigo_obrigacao, a.vencimento, a.status, a.competencia, a.valor_esperado,
      t.nome, t.icone,
      case
        when a.status = 'pago' then 'pago'
        when a.vencimento < current_date then 'atrasado'
        when a.vencimento <= current_date + v_dias_alerta then 'urgente'
        when a.vencimento <= current_date + 30 then 'proximo'
        else 'futuro'
      end as severidade
    from fiscal_agenda a
    join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  )
  select
    (select count(*)::int from classificados where severidade = 'atrasado'),
    (select count(*)::int from classificados where severidade = 'urgente'),
    (select count(*)::int from classificados where severidade = 'proximo'),
    (select count(*)::int from classificados
       where severidade = 'pago'
         and date_trunc('month', vencimento) = date_trunc('month', current_date)),
    coalesce(
      (select jsonb_agg(jsonb_build_object(
          'id', c.id,
          'codigo', c.codigo_obrigacao,
          'nome', c.nome,
          'icone', c.icone,
          'vencimento', c.vencimento,
          'dias_para_vencer', (c.vencimento - current_date)::int,
          'severidade', c.severidade,
          'valor_esperado', c.valor_esperado
        ) order by c.vencimento
       )
       from (
         select * from classificados
         where severidade in ('atrasado','urgente','proximo')
         order by vencimento
         limit 5
       ) c),
      '[]'::jsonb
    );
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_resumo_malote(p_ano integer, p_mes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total_obrigacoes int;
  v_total_pagas int;
  v_total_pendentes int;
  v_total_valor numeric;
  v_por_obrigacao jsonb;
begin
  select
    count(*),
    count(*) filter (where status = 'pago'),
    count(*) filter (where status in ('pendente','atrasado')),
    sum(valor_pago) filter (where status = 'pago')
  into v_total_obrigacoes, v_total_pagas, v_total_pendentes, v_total_valor
  from fiscal_agenda
  where extract(year  from competencia) = p_ano
    and extract(month from competencia) = p_mes;

  select coalesce(jsonb_agg(jsonb_build_object(
    'codigo', a.codigo_obrigacao,
    'nome', t.nome,
    'icone', t.icone,
    'status', a.status,
    'vencimento', a.vencimento,
    'valor_pago', a.valor_pago,
    'data_pagamento', a.data_pagamento,
    'qtd_documentos', (select count(*) from fiscal_documentos d where d.agenda_id = a.id)
  ) order by a.codigo_obrigacao), '[]'::jsonb)
  into v_por_obrigacao
  from fiscal_agenda a
  join fiscal_tipos_obrigacao t on t.codigo = a.codigo_obrigacao
  where extract(year  from a.competencia) = p_ano
    and extract(month from a.competencia) = p_mes;

  return jsonb_build_object(
    'ano', p_ano,
    'mes', p_mes,
    'total_obrigacoes', v_total_obrigacoes,
    'total_pagas', v_total_pagas,
    'total_pendentes', v_total_pendentes,
    'valor_total_pago', coalesce(v_total_valor, 0),
    'por_obrigacao', v_por_obrigacao
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.fiscal_sincronizar_pagamento_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
begin
  -- Se um lançamento que está vinculado a uma obrigação fiscal foi PAGO:
  if new.status = 'pago' and (old.status is distinct from 'pago') then
    update fiscal_agenda
    set status = 'pago',
        valor_pago = new.valor,
        data_pagamento = coalesce(new.data_pagamento, current_date),
        atualizado_em = now()
    where lancamento_id = new.id
      and status != 'pago';
  end if;
  return new;
end; $function$
;

