 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  -- Lista vazia quer dizer "sem função", que neste enum se escreve 'membro'.
  new.funcao_ministerial := coalesce(new.funcoes_ministeriais[1], 'membro'::funcao_ministerial);
