CREATE OR REPLACE FUNCTION public.fn_listar_acessos_sistema()
 RETURNS TABLE(membro_id uuid, nome text, email text, role app_role, role_label text, desde timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem listar acessos do sistema';
  END IF;
  
  RETURN QUERY
  SELECT
    ur.user_id,
    COALESCE(m.nome_completo, p.nome, 'Sem nome') AS nome,
    COALESCE(m.email, p.email, '')                AS email,
    ur.role,
    CASE ur.role
      WHEN 'admin'      THEN 'Administrador'
      WHEN 'secretaria' THEN 'Secretaria'
      WHEN 'lideranca'  THEN 'Liderança'
      WHEN 'diakonia'   THEN 'Diakonia'
      WHEN 'operador'   THEN 'Operador'
      WHEN 'voluntario' THEN 'Voluntário'
      ELSE ur.role::text
    END AS role_label,
    ur.created_at
  FROM user_roles ur
  LEFT JOIN membros  m ON m.id = ur.user_id
  LEFT JOIN profiles p ON p.id = ur.user_id
  ORDER BY ur.role, nome;
END;
$function$
;

