CREATE OR REPLACE FUNCTION public.locais_auto_historico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
BEGIN
  IF OLD.status_operacional = 'em_manutencao' AND NEW.status_operacional = 'disponivel' THEN
    INSERT INTO public.locais_historico_operacional (local_id, tipo, descricao, data)
    VALUES (NEW.id, 'reativacao', 'Local reativado automaticamente apos manutencao', CURRENT_DATE);
  END IF;
  IF OLD.status_operacional != 'em_manutencao' AND NEW.status_operacional = 'em_manutencao' THEN
    INSERT INTO public.locais_historico_operacional (local_id, tipo, descricao, data)
    VALUES (NEW.id, 'manutencao', COALESCE(NEW.motivo_status, 'Entrada em manutencao'), CURRENT_DATE);
  END IF;
  IF OLD.status_operacional != 'interditado' AND NEW.status_operacional = 'interditado' THEN
    INSERT INTO public.locais_historico_operacional (local_id, tipo, descricao, data)
    VALUES (NEW.id, 'interdito', COALESCE(NEW.motivo_status, 'Local interditado'), CURRENT_DATE);
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.locais_calc_proxima_manutencao()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ultima_manutencao IS NOT NULL AND NEW.periodicidade_manutencao IS NOT NULL THEN
    NEW.proxima_manutencao := NEW.ultima_manutencao + (NEW.periodicidade_manutencao || ' days')::interval;
  ELSE
    NEW.proxima_manutencao := NULL;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.locais_set_nome_completo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.nome_completo :=
    NEW.nome
    || COALESCE(' - ' || NEW.pavimento::text, '')
    || COALESCE(' - ' || NEW.localizacao_interna::text, '');
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.locais_sync_agendamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status_operacional IN ('em_manutencao', 'interditado', 'inativo') THEN
    NEW.permite_agendamento := false;
  END IF;
  IF NEW.status_operacional = 'inativo' THEN NEW.status := 'inativo';
  ELSE NEW.status := 'ativo'; END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.log_lideranca_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entidade text := TG_ARGV[0]; -- 'ministerio' ou 'area'
  v_user uuid := auth.uid();
BEGIN
  IF NEW.lider_id IS DISTINCT FROM OLD.lider_id THEN
    INSERT INTO public.historico_lideranca (entidade, entidade_id, cargo, acao, membro_anterior_id, membro_novo_id, registrado_por)
    VALUES (
      v_entidade, NEW.id, 'lider',
      CASE
        WHEN OLD.lider_id IS NULL THEN 'assumiu'
        WHEN NEW.lider_id IS NULL THEN 'encerrou'
        ELSE 'substituiu'
      END,
      OLD.lider_id, NEW.lider_id, v_user
    );
  END IF;

  IF NEW.co_lider_id IS DISTINCT FROM OLD.co_lider_id THEN
    INSERT INTO public.historico_lideranca (entidade, entidade_id, cargo, acao, membro_anterior_id, membro_novo_id, registrado_por)
    VALUES (
      v_entidade, NEW.id, 'co_lider',
      CASE
        WHEN OLD.co_lider_id IS NULL THEN 'assumiu'
        WHEN NEW.co_lider_id IS NULL THEN 'encerrou'
        ELSE 'substituiu'
      END,
      OLD.co_lider_id, NEW.co_lider_id, v_user
    );
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_tipo_pessoa_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
BEGIN
  IF NEW.tipo_pessoa IS DISTINCT FROM OLD.tipo_pessoa THEN
    INSERT INTO public.historico_membro (membro_id, tipo, descricao, data, registrado_por)
    VALUES (
      NEW.id,
      'conversao_tipo',
      'Tipo alterado de ' || OLD.tipo_pessoa::text || ' para ' || NEW.tipo_pessoa::text,
      CURRENT_DATE,
      auth.uid()
    );
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.minhas_permissoes()
 RETURNS TABLE(codigo text, modulo text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select distinct rp.permissao_codigo, p.modulo
  from public.user_roles ur
  join public.role_permissoes rp on rp.role = ur.role
  join public.permissoes p on p.codigo = rp.permissao_codigo
  where ur.user_id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.montar_pauta_financeira(p_competencia_inicio date, p_competencia_fim date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_entradas numeric;
  v_saidas numeric;
  v_saldo_periodo numeric;
  v_contas_a_pagar jsonb;
  v_total_a_pagar numeric;
  v_nao_conciliados jsonb;
  v_total_nao_conc numeric;
  v_top_centros jsonb;
  v_alertas_fiscais jsonb;
  v_orcamento_estourado jsonb;
begin
  -- 1. Resumo do período
  select
    coalesce(sum(case when tipo = 'entrada' then valor else 0 end), 0),
    coalesce(sum(case when tipo = 'saida'   then valor else 0 end), 0)
  into v_entradas, v_saidas
  from fin_lancamentos
  where status in ('realizado','conciliado')
    and data_competencia between p_competencia_inicio and p_competencia_fim;
  v_saldo_periodo := v_entradas - v_saidas;

  -- 2. Contas a pagar pendentes
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'descricao', l.descricao,
    'valor', l.valor,
    'vencimento', l.data_vencimento,
    'categoria', c.nome
  ) order by l.data_vencimento), '[]'::jsonb),
  coalesce(sum(l.valor), 0)
  into v_contas_a_pagar, v_total_a_pagar
  from fin_lancamentos l
  left join fin_categorias c on c.id = l.categoria_id
  where l.status = 'a_pagar'
    and l.data_vencimento <= current_date + 60;

  -- 3. Lançamentos não conciliados (atenção do tesoureiro)
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', l.id, 'descricao', l.descricao,
    'valor', l.valor, 'data', l.data_competencia
  ) order by l.data_competencia desc), '[]'::jsonb),
  coalesce(sum(l.valor), 0)
  into v_nao_conciliados, v_total_nao_conc
  from fin_lancamentos l
  where l.status = 'realizado'
    and l.data_competencia between p_competencia_inicio and p_competencia_fim
  limit 10;

  -- 4. Top 5 centros de custo do período
  begin
    select coalesce(jsonb_agg(t ORDER BY total desc), '[]'::jsonb)
    into v_top_centros
    from (
      select cc.nome, sum(l.valor) as total
      from fin_lancamentos l
      join fin_centros_custo cc on cc.id = l.centro_custo_id
      where l.tipo = 'saida'
        and l.status in ('realizado','conciliado')
        and l.data_competencia between p_competencia_inicio and p_competencia_fim
      group by cc.nome
      order by sum(l.valor) desc
      limit 5
    ) t;
  exception when others then
    v_top_centros := '[]'::jsonb;
  end;

  -- 5. Alertas fiscais
  begin
    select coalesce(jsonb_agg(jsonb_build_object(
      'codigo', a.codigo_obrigacao,
      'vencimento', a.vencimento,
      'status', a.status,
      'valor_pago', a.valor_pago
    ) order by a.vencimento), '[]'::jsonb)
    into v_alertas_fiscais
    from fiscal_agenda a
    where a.vencimento between p_competencia_inicio and current_date + 30
      and a.status in ('pendente','atrasado');
  exception when others then
    v_alertas_fiscais := '[]'::jsonb;
  end;

  -- 6. Orçamento estourado
  begin
    select coalesce(jsonb_agg(jsonb_build_object(
      'centro', cc.nome,
      'orcado', o.valor,
      'realizado', sum(l.valor),
      'percentual', round(sum(l.valor) / nullif(o.valor, 0) * 100, 1)
    )), '[]'::jsonb)
    into v_orcamento_estourado
    from fin_orcamentos o
    join fin_centros_custo cc on cc.id = o.centro_custo_id
    join fin_lancamentos l on l.centro_custo_id = cc.id
      and l.tipo = 'saida'
      and l.status in ('realizado','conciliado')
      and l.data_competencia between p_competencia_inicio and p_competencia_fim
    where o.ano = extract(year from p_competencia_inicio)::int
    group by cc.nome, o.valor
    having sum(l.valor) > o.valor * 0.9;       -- alerta a partir de 90% do orçado
  exception when others then
    v_orcamento_estourado := '[]'::jsonb;
  end;

  -- Monta o pacote final
  return jsonb_build_object(
    'periodo', jsonb_build_object(
      'inicio', p_competencia_inicio,
      'fim', p_competencia_fim
    ),
    'resumo', jsonb_build_object(
      'entradas', v_entradas,
      'saidas', v_saidas,
      'saldo_periodo', v_saldo_periodo
    ),
    'contas_a_pagar', jsonb_build_object(
      'total', v_total_a_pagar,
      'qtd', jsonb_array_length(v_contas_a_pagar),
      'lista', v_contas_a_pagar
    ),
    'nao_conciliados', jsonb_build_object(
      'total', v_total_nao_conc,
      'lista', v_nao_conciliados
    ),
    'top_centros_custo', v_top_centros,
    'alertas_fiscais', v_alertas_fiscais,
    'orcamento_estourado', v_orcamento_estourado,
    'gerada_em', now()
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.mover_aluno_classe(p_pessoa_id uuid, p_classe_nova uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nova_mat_id uuid;
BEGIN
  -- 1. Desativar todas as matriculas ativas da pessoa
  UPDATE public.ebd_matriculas
     SET ativo = false, updated_at = NOW()
   WHERE pessoa_id = p_pessoa_id AND ativo = true;

  -- 2. Inserir nova matricula
  INSERT INTO public.ebd_matriculas (pessoa_id, classe_id, ativo)
       VALUES (p_pessoa_id, p_classe_nova, true)
       RETURNING id INTO v_nova_mat_id;

  RETURN v_nova_mat_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalizar_site(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_url IS NULL OR trim(p_url) = '' THEN RETURN NULL; END IF;
  RETURN rtrim(lower(trim(p_url)), '/');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalizar_telefone(tel text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  limpo text;
BEGIN
  IF tel IS NULL OR btrim(tel) = '' THEN
    RETURN NULL;
  END IF;
  limpo := regexp_replace(tel, '\D', '', 'g');
  IF limpo = '' THEN
    RETURN NULL;
  END IF;
  IF length(limpo) BETWEEN 12 AND 13 AND substr(limpo, 1, 2) = '55' THEN
    RETURN limpo;
  END IF;
  IF length(limpo) BETWEEN 10 AND 11 THEN
    RETURN '55' || limpo;
  END IF;
  RETURN limpo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_nome_familia()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.nome_familia IS NOT NULL THEN
    NEW.nome_familia := btrim(regexp_replace(NEW.nome_familia, '^\s*fam[ií]lia\s+', '', 'i'));
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.oid_dist(oid, oid)
 RETURNS oid
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/btree_gist', $function$oid_dist$function$
;

CREATE OR REPLACE FUNCTION public.painel_de_acessos()
 RETURNS TABLE(user_id uuid, nome text, login text, telefone text, pessoa_id uuid, papeis text[], ultimo_acesso timestamp with time zone, criado_em timestamp with time zone, bloqueado boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Apenas a administração pode ver o painel de acessos.';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    -- A ficha da pessoa manda quando existe: é o nome que a igreja usa. O do
    -- profile é o que o usuário digitou ao criar a conta.
    COALESCE(NULLIF(btrim(m.nome_completo), ''), NULLIF(btrim(p.nome), ''), 'Sem nome')::text,
    COALESCE(au.email, p.email, '')::text,
    COALESCE(p.telefone, m.telefone_celular, '')::text,
    p.pessoa_id,
    COALESCE(
      (SELECT array_agg(ur.role::text ORDER BY ur.role::text)
         FROM public.user_roles ur WHERE ur.user_id = p.id),
      ARRAY[]::text[]
    ),
    au.last_sign_in_at,
    au.created_at,
    (au.banned_until IS NOT NULL AND au.banned_until > now())
  FROM public.profiles p
  LEFT JOIN public.membros m ON m.id = p.pessoa_id
  LEFT JOIN auth.users   au ON au.id = p.id
  ORDER BY 2;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.pessoa_atual()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.pessoa_id from public.profiles p where p.id = auth.uid()
$function$
;

CREATE OR REPLACE FUNCTION public.pessoas_sem_familia_sobrenome_conhecido()
 RETURNS TABLE(pessoa_id uuid, nome_completo text, sobrenome text, qtd_pessoas_mesmo_sobrenome integer, familia_sugerida_id uuid, familia_sugerida_nome text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH 
  -- Pessoas ativas e seu sobrenome
  pessoas AS (
    SELECT m.id, m.nome_completo, public.extrair_sobrenome(m.nome_completo) AS sobrenome
    FROM public.membros m
    WHERE m.status = 'ativo'
      AND m.tipo_pessoa IN ('membro','congregado')
  ),
  -- Pessoas SEM vínculo familiar
  sem_familia AS (
    SELECT p.* FROM pessoas p
    LEFT JOIN public.vinculos_familiares vf ON vf.membro_id = p.id
    WHERE vf.id IS NULL
      AND p.sobrenome IS NOT NULL
      AND length(p.sobrenome) >= 3
  ),
  -- Familias existentes com sobrenome correspondente (via primeiro membro)
  familias_por_sobrenome AS (
    SELECT f.id, f.nome_familia, 
           public.extrair_sobrenome(f.nome_familia) AS fam_sobrenome,
           COUNT(vf.id) AS qtd_membros
    FROM public.familias f
    LEFT JOIN public.vinculos_familiares vf ON vf.familia_id = f.id
    GROUP BY f.id, f.nome_familia
    HAVING COUNT(vf.id) > 0
  ),
  -- Contar quantas pessoas têm o mesmo sobrenome (pra mostrar urgência)
  contagem AS (
    SELECT sobrenome, COUNT(*) AS qtd FROM pessoas GROUP BY sobrenome
  )
  SELECT 
    sf.id, sf.nome_completo, sf.sobrenome,
    c.qtd::int,
    fps.id,
    fps.nome_familia
  FROM sem_familia sf
  LEFT JOIN contagem c ON c.sobrenome = sf.sobrenome
  LEFT JOIN familias_por_sobrenome fps ON fps.fam_sobrenome = sf.sobrenome
  WHERE 
    (c.qtd >= 2 OR fps.id IS NOT NULL)  -- pelo menos uma referência conhecida
  ORDER BY 
    (fps.id IS NOT NULL) DESC,
    c.qtd DESC NULLS LAST,
    sf.nome_completo
  LIMIT 50;
$function$
;

CREATE OR REPLACE FUNCTION public.pgm_alertas_ausencia(p_grupo_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(pessoa_id uuid, nome text, grupo_id uuid, grupo_nome text, faltas_seguidas integer, ultima_presenca date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  with ultimas as (
    select r.id as reuniao_id, r.grupo_id, r.data
    from public.pgm_reunioes r
    where r.data >= current_date - interval '60 days'
      and (p_grupo_id is null or r.grupo_id = p_grupo_id)
  ),
  joined as (
    select m.pessoa_id, m.grupo_id,
           u.reuniao_id, u.data,
           coalesce(p.presente, false) as presente
    from public.pgm_membros m
    join ultimas u on u.grupo_id = m.grupo_id
    left join public.pgm_presencas p on p.reuniao_id = u.reuniao_id and p.pessoa_id = m.pessoa_id
    where m.ativo
  ),
  ranks as (
    select pessoa_id, grupo_id, data, presente,
           row_number() over (partition by pessoa_id, grupo_id order by data desc) as rn
    from joined
  ),
  recentes as (
    select pessoa_id, grupo_id,
           bool_or(presente) filter (where rn <= 3) as algum_presente_recente,
           max(data) filter (where presente) as ultima_pres,
           count(*) filter (where rn <= 3) as ult3_count
    from ranks
    group by pessoa_id, grupo_id
  )
  select r.pessoa_id, mem.nome_completo, r.grupo_id, g.nome,
         3::int as faltas_seguidas, r.ultima_pres
  from recentes r
  join public.membros mem on mem.id = r.pessoa_id
  join public.pgm_grupos g on g.id = r.grupo_id
  where r.ult3_count >= 3
    and r.algum_presente_recente = false;
$function$
;

CREATE OR REPLACE FUNCTION public.pgm_garante_principal_unico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.principal then
    update public.pgm_membros
       set principal = false
     where pessoa_id = new.pessoa_id
       and id <> new.id;
  end if;
  return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.pgm_iniciar_reuniao(p_grupo_id uuid, p_data date, p_tema text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reuniao_id uuid;
begin
  insert into public.pgm_reunioes(grupo_id, data, tema, registrada_por)
  values (p_grupo_id, p_data, p_tema, auth.uid())
  on conflict (grupo_id, data) do update
    set tema = coalesce(excluded.tema, public.pgm_reunioes.tema)
  returning id into v_reuniao_id;

  insert into public.pgm_presencas(reuniao_id, pessoa_id, presente)
  select v_reuniao_id, m.pessoa_id, false
  from public.pgm_membros m
  where m.grupo_id = p_grupo_id and m.ativo
  on conflict (reuniao_id, pessoa_id) do nothing;

  return v_reuniao_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.pgm_multiplicar_grupo(p_pai_id uuid, p_nome_filho text, p_lider_id uuid, p_pessoas_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_filho_id uuid;
  v_pessoa_id uuid;
begin
  insert into public.pgm_grupos(nome, lider_id, grupo_pai_id, multiplicado_em)
  values (p_nome_filho, p_lider_id, p_pai_id, current_date)
  returning id into v_filho_id;

  -- Inclui o líder do filho como participante "lider"
  insert into public.pgm_membros(grupo_id, pessoa_id, papel, principal)
  values (v_filho_id, p_lider_id, 'lider', true)
  on conflict (grupo_id, pessoa_id) do update set papel = 'lider';

  -- Transfere as pessoas escolhidas (saem do pai, entram no filho)
  if p_pessoas_ids is not null then
    foreach v_pessoa_id in array p_pessoas_ids loop
      update public.pgm_membros
         set ativo = false, data_saida = current_date
       where grupo_id = p_pai_id and pessoa_id = v_pessoa_id;
      insert into public.pgm_membros(grupo_id, pessoa_id, papel, principal)
      values (v_filho_id, v_pessoa_id, 'participante', true)
      on conflict (grupo_id, pessoa_id) do update set ativo = true, principal = true;
    end loop;
  end if;

  return v_filho_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.pgm_resumo_geral()
 RETURNS TABLE(total_grupos integer, grupos_ativos integer, multiplicadores integer, total_membros integer, reunioes_semana integer, presenca_media_pct numeric, pedidos_ativos integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  with rs as (
    select
      r.id,
      (select count(*) from public.pgm_presencas p where p.reuniao_id = r.id) as total,
      (select count(*) from public.pgm_presencas p where p.reuniao_id = r.id and p.presente) as presentes
    from public.pgm_reunioes r
    where r.data >= current_date - interval '30 days'
  )
  select
    (select count(*) from public.pgm_grupos)::int,
    (select count(*) from public.pgm_grupos where ativo)::int,
    (select count(distinct grupo_pai_id) from public.pgm_grupos where grupo_pai_id is not null)::int,
    (select count(*) from public.pgm_membros where ativo)::int,
    (select count(*) from public.pgm_reunioes
      where data between (current_date - extract(dow from current_date)::int)
                     and (current_date - extract(dow from current_date)::int + 6))::int,
    coalesce((select round(avg(case when total = 0 then 0
                                    else 100.0 * presentes / total end), 0)
              from rs), 0),
    (select count(*) from public.pgm_pedidos_oracao where status = 'ativo')::int;
$function$
;

CREATE OR REPLACE FUNCTION public.pgm_resumo_presenca(p_grupo_id uuid, p_n integer DEFAULT 4)
 RETURNS TABLE(reuniao_id uuid, data date, tema text, total integer, presentes integer, percentual numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    r.id, r.data, r.tema,
    count(p.id)::int,
    count(*) filter (where p.presente)::int,
    case when count(p.id) = 0 then 0
         else round(100.0 * count(*) filter (where p.presente) / count(p.id), 0)
    end
  from public.pgm_reunioes r
  left join public.pgm_presencas p on p.reuniao_id = r.id
  where r.grupo_id = p_grupo_id
  group by r.id
  order by r.data desc
  limit p_n;
$function$
;

CREATE OR REPLACE FUNCTION public.pgm_sugerir_por_bairro(p_bairro text)
 RETURNS TABLE(id uuid, nome text, dia_semana smallint, horario time without time zone, bairro text, qtd_membros integer, lider_nome text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with res as (
    select g.id, g.nome, g.dia_semana, g.horario, g.bairro,
           (select count(*) from public.pgm_membros pm
              where pm.grupo_id = g.id and pm.ativo)::int as qm,
           lider.nome_completo as ln
    from public.pgm_grupos g
    left join public.membros lider on lider.id = g.lider_id
    where g.ativo
      and lower(coalesce(g.bairro, '')) = lower(coalesce(p_bairro, ''))
  )
  select res.id, res.nome, res.dia_semana, res.horario, res.bairro,
         res.qm, res.ln
  from res
  order by res.qm desc;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_locais_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'Locais não podem ser excluídos. Utilize o status (ativo/inativo).';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_membros_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- ADMIN pode excluir; demais roles são bloqueados
  IF public.has_role(auth.uid(), 'admin') THEN
    RETURN OLD;  -- permite o DELETE prosseguir
  END IF;

  RAISE EXCEPTION 'Apenas administradores podem excluir contatos. Utilize o status para inativar.';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.proximo_aniversario(p_data date, p_ano integer DEFAULT NULL::integer)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  select make_date(
    coalesce(p_ano, date_part('year', current_date)::int),
    date_part('month', p_data)::int,
    least(
      date_part('day', p_data)::int,
      -- último dia daquele mês naquele ano: protege 29/02 em ano comum
      date_part('day',
        (make_date(coalesce(p_ano, date_part('year', current_date)::int),
                   date_part('month', p_data)::int, 1) + interval '1 month - 1 day')
      )::int
    )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.redefinir_senha(p_token uuid, p_senha text)
 RETURNS TABLE(ok boolean, erro text, email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
BEGIN
  RETURN QUERY SELECT * FROM aceitar_convite(p_token, p_senha);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_audit_log(p_tipo_evento text, p_pessoa_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_detalhes jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  INSERT INTO audit_logs (acao, pessoa_id, user_id, executado_por, detalhes, data)
  VALUES (p_tipo_evento, p_pessoa_id, p_user_id, auth.uid(), p_detalhes, now());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_contato(p_pessoa uuid, p_tipo text, p_obs text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_linhas integer;
begin
  -- SECURITY DEFINER contorna a politica da tabela, entao a checagem de papel
  -- passa a ser responsabilidade daqui. Pastor entra na lista porque ja tinha
  -- escrita por outra politica; lideranca entra porque e o motivo desta
  -- migracao existir.
  if not public.has_any_role(
       (select auth.uid()),
       array['admin','secretaria','diakonia','operador','pastor','lideranca']::app_role[]
     ) then
    raise exception 'sem permissao para registrar contato';
  end if;

  update public.membros
     set ultimo_contato_em         = now(),
         ultimo_contato_tipo       = p_tipo,
         ultimo_contato_observacao = nullif(btrim(coalesce(p_obs, '')), '')
   where id = p_pessoa;

  get diagnostics v_linhas = row_count;

  -- Devolve se gravou de verdade. E o que impede o chamador de anunciar
  -- sucesso sobre coisa nenhuma -- que foi exatamente o defeito original.
  return v_linhas > 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_exportacao(p_filtro_tipo text DEFAULT 'todos'::text, p_filtro_valor text DEFAULT NULL::text, p_total_registros integer DEFAULT 0, p_formato text DEFAULT 'csv'::text, p_campos text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id UUID;
BEGIN
  INSERT INTO public.exportacoes_log
    (usuario_id, usuario_email, filtro_tipo, filtro_valor,
     total_registros, formato, campos_incluidos)
  VALUES
    (auth.uid(), auth.email(),
     p_filtro_tipo, p_filtro_valor,
     p_total_registros, p_formato, p_campos)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_financeiro_pdv(p_venda_id uuid, p_valor_bruto numeric, p_valor_taxa numeric, p_conta text, p_ministerio_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN

  -- entrada
  INSERT INTO fin_lancamentos (
    tipo, valor, categoria,
    conta, centro_custo,
    origem, origem_id, data
  )
  VALUES (
    'entrada',
    p_valor_bruto,
    'bazar',
    p_conta,
    p_ministerio_id,
    'pdv',
    p_venda_id,
    now()
  );

  -- taxa
  IF p_valor_taxa > 0 THEN
    INSERT INTO fin_lancamentos (
      tipo, valor, categoria,
      conta, centro_custo,
      origem, origem_id, data
    )
    VALUES (
      'saida',
      p_valor_taxa,
      'taxa_maquininha',
      p_conta,
      p_ministerio_id,
      'pdv',
      p_venda_id,
      now()
    );
  END IF;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_historico_assunto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
declare
  v_user_nome text;
  v_acao text;
  v_desc text;
begin
  if auth.uid() is not null then
    select coalesce(nome, email) into v_user_nome from public.profiles where id = auth.uid();
  end if;

  if tg_op = 'INSERT' then
    v_acao := 'criado'; v_desc := 'Assunto criado: ' || new.titulo;
  elsif tg_op = 'UPDATE' then
    if old.status is distinct from new.status then
      v_acao := 'status_alterado'; v_desc := 'Status: ' || old.status::text || ' → ' || new.status::text;
      if new.status = 'concluido' then
        update public.assuntos set data_conclusao = coalesce(data_conclusao, current_date) where id = new.id;
      end if;
    elsif old.prioridade is distinct from new.prioridade then
      v_acao := 'prioridade_alterada'; v_desc := 'Prioridade: ' || old.prioridade::text || ' → ' || new.prioridade::text;
    elsif old.responsavel_id is distinct from new.responsavel_id then
      v_acao := 'responsavel_alterado';
      v_desc := 'Responsável: ' || coalesce(old.responsavel_nome, '(ninguém)') || ' → ' || coalesce(new.responsavel_nome, '(ninguém)');
    elsif old.prazo is distinct from new.prazo then
      v_acao := 'prazo_alterado'; v_desc := 'Prazo: ' || coalesce(old.prazo::text, '(sem)') || ' → ' || coalesce(new.prazo::text, '(sem)');
    end if;
  end if;

  if v_acao is not null then
    insert into public.assuntos_historico(assunto_id, acao, descricao, user_id, user_nome)
    values (
      case when tg_op = 'INSERT' then new.id else new.id end,
      v_acao, v_desc, auth.uid(), v_user_nome
    );
    update public.assuntos set ultima_atualizacao_em = now() where id = new.id;
  end if;
  return null;
end;$function$
;

CREATE OR REPLACE FUNCTION public.registrar_historico_documento(p_documento_id uuid, p_acao text, p_versao_de text DEFAULT NULL::text, p_versao_para text DEFAULT NULL::text, p_titulo text DEFAULT NULL::text, p_observacao text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  INSERT INTO public.documentos_historico
    (documento_id, acao, usuario_id, usuario_email, versao_de, versao_para, titulo_doc, observacao)
  VALUES
    (p_documento_id, p_acao,
     auth.uid(),
     (SELECT email FROM auth.users WHERE id = auth.uid()),
     p_versao_de, p_versao_para, p_titulo, p_observacao);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_historico_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_acao text;
  v_desc text;
  v_user_nome text;
begin
  -- pega nome do user que fez a ação
  if auth.uid() is not null then
    select coalesce(nome, email) into v_user_nome from public.profiles where id = auth.uid();
  end if;

  if tg_op = 'INSERT' then
    v_acao := 'criada';
    v_desc := 'Solicitação criada (tipo: ' || new.tipo::text || ')';
  elsif tg_op = 'UPDATE' then
    if old.status <> new.status then
      v_acao := 'status_alterado';
      v_desc := 'Status: ' || old.status::text || ' → ' || new.status::text;
    end if;
    if old.data_assembleia is distinct from new.data_assembleia and new.data_assembleia is not null then
      v_acao := 'assembleia_agendada';
      v_desc := 'Assembleia agendada para ' || new.data_assembleia::text;
    end if;
    if old.carta_url is distinct from new.carta_url and new.carta_url is not null then
      v_acao := 'carta_gerada';
      v_desc := 'Carta gerada (v' || coalesce(new.carta_versao_atual, 1) || ')';
    end if;
  end if;

  if v_acao is not null then
    insert into public.solicitacoes_historico(solicitacao_id, acao, descricao, user_id, user_nome)
    values (
      case when tg_op = 'INSERT' then new.id else new.id end,
      v_acao, v_desc, auth.uid(), v_user_nome
    );
  end if;
  return null;
end;$function$
;

CREATE OR REPLACE FUNCTION public.reset_user_password(target_user_id uuid, new_password text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  caller_role TEXT;
BEGIN
  SELECT role INTO caller_role FROM profiles WHERE id = auth.uid();
  IF caller_role NOT IN ('admin', 'secretaria') THEN
    RAISE EXCEPTION 'Permissao negada: apenas admin e secretaria podem resetar senhas.';
  END IF;
  UPDATE auth.users
     SET encrypted_password = crypt(new_password, gen_salt('bf')),
         raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || '{"must_change_password": true}'::jsonb,
         updated_at = now()
   WHERE id = target_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Usuario nao encontrado: %', target_user_id;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resumo_campanha_ebd(p_campanha_id uuid)
 RETURNS TABLE(meta numeric, arrecadado numeric, percentual numeric, dias_decorridos integer, dias_totais integer, meta_diaria numeric, esperado_ate_hoje numeric, status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
DECLARE
  v_c     public.ebd_campanhas%ROWTYPE;
  v_total numeric;
BEGIN
  SELECT * INTO v_c FROM public.ebd_campanhas WHERE id = p_campanha_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT COALESCE(SUM(valor), 0) INTO v_total
    FROM public.ebd_entradas WHERE campanha_id = p_campanha_id;
 
  meta              := v_c.meta_valor;
  arrecadado        := v_total;
  percentual        := CASE WHEN v_c.meta_valor > 0 THEN ROUND((v_total / v_c.meta_valor) * 100, 1) ELSE 0 END;
  dias_decorridos   := GREATEST(0, LEAST(CURRENT_DATE - v_c.data_inicio, v_c.data_fim - v_c.data_inicio));
  dias_totais       := GREATEST(1, v_c.data_fim - v_c.data_inicio);
  meta_diaria       := ROUND(v_c.meta_valor / dias_totais, 2);
  esperado_ate_hoje := ROUND(meta_diaria * dias_decorridos, 2);
  status := CASE
    WHEN v_total >= v_c.meta_valor       THEN 'meta_atingida'
    WHEN v_total >= esperado_ate_hoje*1.10 THEN 'acima_esperado'
    WHEN v_total <= esperado_ate_hoje*0.50 THEN 'muito_abaixo'
    WHEN v_total <= esperado_ate_hoje*0.85 THEN 'abaixo_esperado'
    ELSE 'no_ritmo'
  END;
  RETURN NEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resumo_ebd_dashboard()
 RETURNS TABLE(total_alunos integer, total_classes_ativas integer, ultimo_domingo date, domingo_anterior date, classes_com_aula_ult integer, presentes_ult integer, matriculados_classes_ult integer, taxa_presenca_ult numeric, presentes_ant integer, matriculados_classes_ant integer, taxa_presenca_ant numeric, variacao_presenca numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  WITH 
  ultima_data AS (
    SELECT public.domingo_da_semana(CURRENT_DATE) AS d
  ),
  anterior_data AS (
    SELECT (SELECT d FROM ultima_data) - INTERVAL '7 days' AS d
  ),
  aulas_ult AS (
    SELECT a.id, a.classe_id 
      FROM public.ebd_aulas a, ultima_data
     WHERE a.data = (SELECT d FROM ultima_data)
  ),
  aulas_ant AS (
    SELECT a.id, a.classe_id 
      FROM public.ebd_aulas a, anterior_data
     WHERE a.data = ((SELECT d FROM anterior_data))::date
  ),
  presencas_ult AS (
    SELECT COUNT(*)::int AS qtd FROM public.ebd_presencas ep
     WHERE ep.aula_id IN (SELECT id FROM aulas_ult)
       AND ep.presente = true
  ),
  presencas_ant AS (
    SELECT COUNT(*)::int AS qtd FROM public.ebd_presencas ep
     WHERE ep.aula_id IN (SELECT id FROM aulas_ant)
       AND ep.presente = true
  ),
  matric_classes_ult AS (
    SELECT COUNT(*)::int AS qtd FROM public.ebd_matriculas em
     WHERE em.ativo = true 
       AND em.classe_id IN (SELECT classe_id FROM aulas_ult)
  ),
  matric_classes_ant AS (
    SELECT COUNT(*)::int AS qtd FROM public.ebd_matriculas em
     WHERE em.ativo = true 
       AND em.classe_id IN (SELECT classe_id FROM aulas_ant)
  )
  SELECT
    (SELECT COUNT(*)::int FROM public.ebd_matriculas WHERE ativo = true),
    (SELECT COUNT(*)::int FROM public.ebd_classes WHERE ativo = true),
    (SELECT d FROM ultima_data),
    ((SELECT d FROM anterior_data))::date,
    (SELECT COUNT(*)::int FROM aulas_ult),
    (SELECT qtd FROM presencas_ult),
    (SELECT qtd FROM matric_classes_ult),
    CASE WHEN (SELECT qtd FROM matric_classes_ult) > 0 
         THEN ROUND(100.0 * (SELECT qtd FROM presencas_ult) / (SELECT qtd FROM matric_classes_ult), 1)
         ELSE 0 END,
    (SELECT qtd FROM presencas_ant),
    (SELECT qtd FROM matric_classes_ant),
    CASE WHEN (SELECT qtd FROM matric_classes_ant) > 0
         THEN ROUND(100.0 * (SELECT qtd FROM presencas_ant) / (SELECT qtd FROM matric_classes_ant), 1)
         ELSE 0 END,
    -- variacao = ult - ant em pontos percentuais
    CASE WHEN (SELECT qtd FROM matric_classes_ant) > 0 AND (SELECT qtd FROM matric_classes_ult) > 0
         THEN ROUND(
           (100.0 * (SELECT qtd FROM presencas_ult) / NULLIF((SELECT qtd FROM matric_classes_ult),0)) -
           (100.0 * (SELECT qtd FROM presencas_ant) / NULLIF((SELECT qtd FROM matric_classes_ant),0))
         , 1)
         ELSE 0 END;
$function$
;

CREATE OR REPLACE FUNCTION public.resumo_meus_dados()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_email TEXT; v_result JSONB;
BEGIN
  SELECT email INTO v_email FROM public.profiles WHERE id=auth.uid();
  SELECT jsonb_build_object(
    'identificacao', jsonb_build_object('nome',pe.nome_completo,'email',pe.email,'tipo',pe.tipo,'desde',pe.created_at),
    'consentimentos',(SELECT jsonb_agg(jsonb_build_object('tipo',c.tipo,'base_legal',c.base_legal,'aceito',c.aceito,'em',c.registrado_em)) FROM public.consentimento c WHERE c.pessoa_id=pe.id),
    'solicitacoes',  (SELECT jsonb_agg(jsonb_build_object('tipo',sl.tipo,'status',sl.status,'em',sl.solicitado_em)) FROM public.solicitacoes_lgpd sl WHERE sl.pessoa_id=pe.id),
    'politica_versao',(SELECT versao FROM public.politica_privacidade WHERE vigente=true LIMIT 1)
  ) INTO v_result FROM public.pessoas pe WHERE pe.email=v_email LIMIT 1;
  RETURN COALESCE(v_result,'{}'::JSONB);
END; $function$
;

CREATE OR REPLACE FUNCTION public.resumo_painel_pastoral()
 RETURNS TABLE(aniversarios_hoje integer, bodas_hoje integer, aniversarios_semana integer, bodas_semana integer, familias_sem_resp integer, pessoas_sem_familia_sugerida integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  SELECT
    (SELECT COUNT(*)::int FROM public.vw_agenda_pastoral v
      WHERE v.tipo = 'aniversario' 
        AND date_part('month', v.data_origem) = date_part('month', CURRENT_DATE)
        AND date_part('day',   v.data_origem) = date_part('day',   CURRENT_DATE)),
    (SELECT COUNT(*)::int FROM public.vw_agenda_pastoral v
      WHERE v.tipo = 'casamento' 
        AND date_part('month', v.data_origem) = date_part('month', CURRENT_DATE)
        AND date_part('day',   v.data_origem) = date_part('day',   CURRENT_DATE)),
    (SELECT COUNT(*)::int FROM public.agenda_pastoral_proximos_dias(7) p
      WHERE p.tipo = 'aniversario'),
    (SELECT COUNT(*)::int FROM public.agenda_pastoral_proximos_dias(7) p
      WHERE p.tipo = 'casamento'),
    (SELECT COUNT(*)::int FROM public.familias_sem_responsavel()),
    (SELECT COUNT(*)::int FROM public.pessoas_sem_familia_sobrenome_conhecido());
$function$
;

CREATE OR REPLACE FUNCTION public.revogar_acesso(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_nome     text;
  v_era_admin boolean;
  v_admins   int;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Apenas a administração pode remover acessos.';
  END IF;

  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode remover o próprio acesso.';
  END IF;

  SELECT COALESCE(NULLIF(btrim(p.nome), ''), 'esta conta') INTO v_nome
    FROM public.profiles p WHERE p.id = p_user_id;
  IF v_nome IS NULL THEN
    RAISE EXCEPTION 'Acesso não encontrado.';
  END IF;

  -- Sem esta guarda, remover o penultimo admin deixaria a igreja com um so, e
  -- remover o ultimo trancaria todo mundo do lado de fora sem volta pela tela.
  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = p_user_id AND role = 'admin')
    INTO v_era_admin;
  IF v_era_admin THEN
    SELECT count(*) INTO v_admins FROM public.user_roles WHERE role = 'admin';
    IF v_admins <= 1 THEN
      RAISE EXCEPTION 'Este é o único administrador. Promova outra pessoa antes de remover este acesso.';
    END IF;
  END IF;

  DELETE FROM public.user_roles WHERE user_id = p_user_id;

  UPDATE auth.users SET banned_until = 'infinity'::timestamptz WHERE id = p_user_id;

  BEGIN
    DELETE FROM auth.users WHERE id = p_user_id;
    RETURN 'O acesso de ' || v_nome || ' foi removido por completo.';
  EXCEPTION WHEN foreign_key_violation THEN
    RETURN 'O acesso de ' || v_nome || ' foi bloqueado e as permissões, removidas. ' ||
           'A conta permanece no sistema porque há registros feitos por ela — apagá-la ' ||
           'deixaria esse histórico sem autor.';
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.secretaria_alertas()
 RETURNS TABLE(prioridade prioridade_alerta, tipo text, titulo text, descricao text, acao_sugerida text, link text, solicitacao_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'America/Sao_Paulo'
AS $function$
  -- 1) URGENTE: Solicitações sem documento
  select 'urgente'::prioridade_alerta, 'sem_documento',
         pessoa_nome || ' não tem documento anexado',
         pessoa_nome || ' solicitou ' || replace(tipo::text, '_', ' ') ||
           ' há ' || (current_date - data_solicitacao) || ' dias',
         'Anexar documento',
         '/membresia/' || id::text, id
  from public.solicitacoes_membresia
  where status in ('rascunho','aguardando_documento')
    and not exists (
      select 1 from public.solicitacoes_documentos
      where solicitacao_id = solicitacoes_membresia.id and tipo = 'pedido'
    )

  union all

  -- 2) URGENTE: Aprovadas sem carta gerada
  select 'urgente'::prioridade_alerta, 'sem_carta',
         pessoa_nome || ' aprovado(a) mas sem carta gerada',
         'Aprovada em ' || coalesce(data_aprovacao::text, '?') || ' — carta pendente',
         'Gerar carta',
         '/membresia/' || id::text, id
  from public.solicitacoes_membresia
  where status = 'aprovada' and carta_url is null

  union all

  -- 3) ATENÇÃO: Prontas para assembleia (com documento) mas sem data agendada
  select 'atencao'::prioridade_alerta, 'sem_assembleia',
         pessoa_nome || ' pronta para assembleia',
         'Documento anexado. Falta agendar para uma assembleia.',
         'Agendar assembleia',
         '/membresia/' || id::text, id
  from public.solicitacoes_membresia
  where status = 'pronta_assembleia' and data_assembleia is null

  union all

  -- 4) ATENÇÃO: Assembleia próxima (≤ 14 dias) com solicitações pendentes
  select 'atencao'::prioridade_alerta, 'assembleia_proxima',
         'Assembleia em ' || (data_assembleia - current_date) || ' dia(s)',
         pessoa_nome || ' — confirmar tudo pronto',
         'Ver solicitação',
         '/membresia/' || id::text, id
  from public.solicitacoes_membresia
  where status = 'pronta_assembleia'
    and data_assembleia is not null
    and data_assembleia between current_date and current_date + interval '14 days'

  union all

  -- 5) INFO: Solicitações antigas (>30d) sem mudança
  select 'informativo'::prioridade_alerta, 'antiga_parada',
         pessoa_nome || ' sem movimento há ' || (current_date - updated_at::date) || ' dias',
         'Status: ' || status::text || ' · Talvez precise de atenção',
         'Ver solicitação',
         '/membresia/' || id::text, id
  from public.solicitacoes_membresia
  where status not in ('concluida','rejeitada','cancelada')
    and updated_at::date < current_date - interval '30 days'

  order by 1, 2;
$function$
;

