CREATE OR REPLACE FUNCTION public.solicitar_reset_senha(p_telefone text)
 RETURNS TABLE(ok boolean, token uuid, pessoa_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  v_tel       TEXT;
  v_pess_id   UUID;
  v_role      public.app_role;
  v_token     UUID;
BEGIN
  v_tel := regexp_replace(p_telefone, '\D', '', 'g');
  IF length(v_tel) BETWEEN 10 AND 11 THEN v_tel := '55' || v_tel; END IF;

  -- Acha a pessoa via membros.telefone_celular
  SELECT m.id INTO v_pess_id FROM membros m WHERE m.telefone_celular = v_tel LIMIT 1;
  IF v_pess_id IS NULL THEN
    -- Nunca revela se telefone existe ou não (segurança)
    RETURN QUERY SELECT true, NULL::UUID, NULL::UUID;
    RETURN;
  END IF;

  -- Role default = voluntario se não houver
  SELECT pr.role INTO v_role FROM profiles pr WHERE pr.pessoa_id = v_pess_id LIMIT 1;
  v_role := COALESCE(v_role, 'voluntario'::public.app_role);

  -- Invalida resets anteriores
  UPDATE convites_acesso SET used_at = now()
   WHERE pessoa_id = v_pess_id AND tipo = 'reset_senha' AND used_at IS NULL;

  INSERT INTO convites_acesso (tipo, pessoa_id, role, expires_at)
  VALUES ('reset_senha', v_pess_id, v_role, now() + INTERVAL '1 hour')
  RETURNING convites_acesso.token INTO v_token;

  RETURN QUERY SELECT true, v_token, v_pess_id;
END;
$function$
;

